comms.text:
@1 וְאִלֵין דִינַיָא דִי תַסְדַר קֳדָמֵיהוֹן:
@2 אֲרֵי תִזְבַּן עַבְדָא בַר יִשְׂרָאֵל שִׁתְּ שְׁנִין יִפְלָח וּבַשְׁבִיעֵתָא יִפּוֹק לְבַר חוֹרִין מַגָן:
@3 אִם בִּלְחוֹדוֹהִי יֵיעוֹל בִּלְחוֹדוֹהִי יִפּוֹק אִם בְּעֵל אִתְּתָא הוּא וְתִפּוֹק אִתְּתֵהּ עִמֵהּ:
@4 אִם רִבּוֹנֵהּ יִתֶּן לֵהּ אִתְּתָא וּתְלִיד לֵהּ בְּנִין אוֹ בְנָן אִתְּתָא וּבְנָהָא תְּהֵי לְרִבּוֹנָהָא וְהוּא יִפּוֹק בִּלְחוֹדוֹהִי:
@5 וְאִם מֵימַר יֵימַר עַבְדָא רָחֵימְנָא יָת רִבּוֹנִי יָת אִתְּתִי וְיָת בְּנָי לָא אֶפּוֹק לְבַר חוֹרִין:
@6 וִיקָרְבִנֵהּ רִבּוֹנֵהּ לִקֳדָם דַיָנַיָא וִיקָרְבִנֵהּ לְוָת דָשָׁא אוֹ לְוָת (נ''א דִילְוָת) מְזְזֶתָּא וְיַרְצַע רִבּוֹנֵהּ יָת אוּדְנֵהּ בְּמַרְצְעָא וִיהֵי לֵהּ עֲבַד פָּלַח לְעָלָם:
@7 וַאֲרֵי יְזַבֵּן גְבַר יָת בְּרַתֵּהּ לְאַמְהוּ לָא תִפּוֹק כְּמַפְקָנוּת עַבְדַיָא:
@8 אִם בִּישָׁא בְּעֵינֵי רִבּוֹנַהּ דִיקַיְמַהּ לֵהּ וְיִפְרְקִנַהּ לִגְבַר אָחֳרָן לֵית לֵהּ רְשׁוּ לְזַבּוֹנַהּ בְּמִשְׁלְטֵהּ בַהּ:
@9 וְאִם לִבְרֵהּ יְקַיְמִנַהּ כְּהִלְכַת בְּנַת יִשְׂרָאֵל יַעְבֵּד לַהּ:
@10 אִם אָחֳרַנְתָּא יִסַב לֵהּ זִיוּנַהּ כְּסוּתַהּ וְעוֹנָתַהּ לָא יִתְמְנָע:
@11 וְאִם תְּלָת אִלֵין לָא יַעְבֵּד לַהּ וְתִפּוֹק מַגָן בְּלָא כְסַף:
@12 דְיִמְחֵי לֶאֱנַשׁ וְיִקְטְלִנֵהּ אִתְקְטָלָא יִתְקְטֵל:
@13 וּדְלָא כְמַן לֵהּ וּמִן קֳדָם יְיָ אִתִּמְסַר לִידֵהּ וֶאֱשַׁוִי לָךְ אֲתַר דִי יֵעִרוֹק לְתַמָן:
@14 וַאֲרֵי יַרְשַׁע גְבַר עַל חַבְרֵהּ לְמִקְטְלֵהּ בִנְכִילוּ מִן מַדְבְּחִי תִּדְבְּרִנֵהּ לִמְמָת:
@15 וּדְיִמְחֵי אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@16 וְדִיִגְנוּב נַפְשָׁא מִן בְּנֵי יִשְׂרָאֵל וִיזַבְּנִנֵהּ וְיִשְׁתְּכַח בִּידֵהּ אִתְקְטָלָא יִתְקְטֵל:
@17 וְדִיְלוּט אֲבוּהִי וְאִמֵהּ אִתְקְטָלָא יִתְקְטֵל:
@18 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחֵי גְבַר יָת חַבְרֵהּ בְּאַבְנָא אוֹ בְכוּרְמֵיזָא וְלָא יְמוּת וְיִפּוֹל לְבוּטְלָן:
@19 אִם יְקוּם וִיהַלִיךְ בְּבָרָא עַל בּוּרְיֵהּ וִיהֵי זַכָּאָה מָחַיָא לְחוֹד בּוּטְּלָנֵהּ יִתֵּן וַאֲגַר אַסְיָא יְשַׁלֵם:
@20 וַאֲרֵי יִמְחֵי גְבַר יָת עַבְדֵהּ אוֹ יָת אַמְתֵהּ בְּשָׁלְטָּן וִימוּת תְּחוֹת יְדֵהּ אִתְדָנָא יִתְּדָן:
@21 בְּרַם אִם יוֹמָא אוֹ תְרֵין יוֹמִין יִתְקַיָם לָא יִתְּדָן אֲרֵי כַסְפֵּהּ הוּא:
@22 וַאֲרֵי יִנְצוּן גֻבְרִין וְיִמְחוּן אִתְּתָא מַעַדְיָא וְיִפְּקוּן וַלְדָהָא וְלָא יְהֵי מוֹתָא אִתְגְבָאָה יִתְגְבֵי כְּמָא דִי יְשַׁוִי עֲלוֹהִי בַּעֲלַהּ דְאִתְּתָא וְיִתֵּן עַל מֵימַר דַיָנַיָא:
@23 וְאִם מוֹתָא יְהֵא וְתִתֵּן נַפְשָׁא חֳלָף נַפְשָׁא:
@24 עֵינָא חֳלָף עֵינָא שִׁנָא חֳלָף שִׁנָא יְדָא חֳלָף יְדָא רַגְלָא חֳלָף רַגְלָא:
@25 כְּוָאָה חֳלָף כְּוָאָה פִּדְעָא חֳלָף פִּדְעָא מַשְׁקוֹפֵי חֳלָף מַשְׁקוֹפֵי:
@26 וַאֲרֵי יִמְחֵי גְבַר יָת עֵינָא דְעַבְדֵהּ אוֹ יָת עֵינָא דְאַמְתֵהּ וִיחַבְּלִנַהּ לְבַר חוֹרִין יִפְטְּרִנֵהּ חֳלָף עֵינֵהּ:
@27 וְאִם שִׁנָא דְעַבְדֵהּ אוֹ שִּׁנָא דְאַמְתֵהּ יַפֵּל לְבַר חוֹרִין יִפְטְרִנֵהּ חֳלָף שִׁנֵהּ:
@28 וַאֲרֵי יַגַח תּוֹרָא יָת גַבְרָא אוֹ יָת אִתְּתָא וִימוּת אִתְרְגְמָא יִתְרְגֵם תּוֹרָא וְלָא יִתְאָכֵל יָת בִּסְרֵהּ וּמָרֵהּ דְתוֹרָא יְהֵי זַכָּאָה:
@29 וְאִם תּוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְיִתַּסְהֵד בְּמָרֵהּ וְלָא נַטְרֵהּ וְיִקְטוֹל גַבְרָא אוֹ אִתְּתָא תּוֹרָא יִתְרְגֵם וְאַף מָרֵהּ יִתְקְטֵל:
@30 אִם מָמוֹן יְשַׁווּן עֲלוֹהִי וְיִתֵּן פּוּרְקַן נַפְשֵׁהּ כְּכֹל דִי יְשַׁווּן עֲלוֹהִי:
@31 אוֹ לְבַר יִשְׂרָאֵל יַגַח תּוֹרָא אוֹ לְבַת יִשְׂרָאֵל יַגָח כְּדִינָא הָדֵין יִתְעֲבֵד לֵהּ:
@32 אִם לְעַבְדָא יַגַח תּוֹרָא אוֹ לְאַמְתָא כְּסַף תְּלָתִין סִלְעִין יִתֵּן לְרִבּוֹנֵהּ וְתוֹרָא יִתְרְגֵם:
@33 וַאֲרֵי יִפְתַּח גְבַר גוֹב אוֹ אֲרֵי יִכְרֶה גְבַר גוֹב וְלָא יְכַסִנֵהּ וְיִפֵּל תַּמָן תּוֹרָא אוֹ חֲמָרָא:
@34 מָרֵי דְגֻבָּא יְשַׁלֵם כַּסְפָּא יָתִיב לְמָרוֹהִי וּמֵיתָא יְהֵי דִילֵהּ:
@35 וַאֲרֵי יִגוֹף תּוֹר דִגְבַר יָת תּוֹרָא דְחַבְרֵהּ וִימוּת וִזַבְּנוּן יָת תּוֹרָא חַיָא וִיפַלְגוּן יָת כַּסְפֵּהּ וְאַף יָת דְמֵי מֵיתָא יְפַלְגוּן:
@36 אוֹ אִתְיְדַע אֲרֵי תוֹר נַגַח הוּא מֵאִתְּמַלֵי וּמִדְקַמוֹהִי וְלָא נָטְרֵהּ מָרֵהּ שַׁלָמָא יְשַׁלֵם תּוֹרָא חֲלַף תּוֹרָא וּמֵיתָא יְהֵא דִילֵהּ:
@37 אֲרֵי יִגְנוּב גְבַר תּוֹר אוֹ אִמָר וְיִכְּסִנֵהּ אוֹ זַבְּנִנֵהּ חַמְשָׁא תוֹרִין יְשַׁלֵם חָלָף תּוֹרָא וְאַרְבַּע עָנָא חֳלָף אִמְרָא:
@38 אִם בְּמַחְתַּרְתָּא יִשְׁתְּכַח גַנָבָא וְיִתְמְחֵי וִימוּת לֵית לֵהּ דָם:
@39 אִם עֵינָא דְסַהֲדַיָא נְפָלַת עֲלוֹהִי דְמָא לֵהּ שַׁלָמָא יְשַׁלֵם אִם לֵית לֵהּ וְיִזְדַבַּן בִּגְנֻבְתֵּהּ:
@40 אִם אִשְׁתְּכָחָא יִשְׁתְּכַח בִּידֵהּ גְנֻבְתָּא מִתּוֹר עַד חֲמַר עַד אִמַר דְאִנוּן חַיִין עַל חַד תְּרֵין יְשַׁלֵם:
@41 אֲרֵי יאכִיל גְבַר חֲקַל אוֹ כְרָם וִישַׁלַח יָת בְּעִירֵהּ וְיֵיכוּל בַּחֲקַל אָחֳרָן שְׁפַר חַקְלֵהּ וּשְׁפַר כַּרְמֵהּ יְשַׁלֵם:
@42 אֲרֵי תִתַּפַּק נוּר וְיַשְׁכַּח כּוּבִין וְיֵיכוּל גְדִישִׁין אוֹ קֳמָא אוֹ חַקְלָא שַׁלָמָא יְשַׁלֵם דְאַדְלֵק יָת דְלֶקְתָּא:
@43 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ כְּסַף אוֹ מָנִין לְמִטַר וְיִתְגַנְבוּן מִבֵּית גַבְרָא אִם יִשְׁתְּכַח גַנָבָא יְשַׁלֵם עַל חַד תְּרֵין:
@44 אִם לָא יִשְׁתְּכַח גַנָבָא וְיִתְקָרֵב מָרֵי דְבֵיתָא לִקֳדָם דַיָנַיָא אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ:
@45 עַל כָּל פִּתְגַם דְחוֹב עַל תּוֹר עַל חֲמַר עַל אִמָר עַל כְּסוּ עַל כָּל אֲבֶדְתָּא דִי יֵימַר אֲרֵי הוּא דֵין לִקֳדָם דַיָנַיָא יֵיעוֹל דִין תַּרְוֵיהוֹן דִי יְחַיְבוּן דַיָנַיָא יְשַׁלֵם עַל חַד תְּרֵין לְחַבְרֵהּ:
@46 אֲרֵי יִתֵּן גְבַר לְחַבְרֵהּ חֲמַר אוֹ תוֹר אוֹ אִמָר וְכָל בְּעִירָא לְמִטָּר וּמִית אוֹ אִתְּבַר אוֹ אִשְׁתְּבִי לֵית דְחָזֵי:
@47 מוֹמָתָא דַיְיָ תְּהֵי בֵּין תַּרְוֵיהוֹן אִם לָא אוֹשִׁיט יְדֵהּ בְּמָא דִמְסַר לֵהּ חַבְרֵהּ וִיקַבֵּל מָרֵהּ מִנֵהּ מוֹמָתָא וְלָא יְשַׁלֵם:
@48 וְאִם אִתְגְנָבָא יִתְגְנֵב מֵעִמֵהּ יְשַׁלֵם לְמָרוֹהִי:
@49 אִם אִתְּבָרָא יִתְּבַר יַיְתִי סַהֲדִין דִתְבִירָא לָא יְשַׁלֵם:
@50 וַאֲרֵי יִשְׁאַל גְבַר מִן חַבְרֵהּ וְיִתְּבַר אוֹ מִית מָרֵהּ לֵית עִמֵהּ שַׁלָמָא יְשַׁלֵם:
@51 אִם מָרֵהּ עִמֵהּ לָא יְשַׁלֵם אִם אֲגִירָא הוּא עַל בְּאַגְרֵהּ:
@52 וַאֲרֵי יְשַׁדֵל גְבַר בְּתֻלְתָּא דִּי לָא מְאַרְסָא וְיִשְׁכּוּב עִמַהּ קַיָמָא יְקַיְמִנַהּ לֵהּ לְאִנְתּוּ:
@53 אִם מִצְבָּא לָא יִצְבֵּי אֲבוּהָא לְמִתְּנַהּ לֵהּ כַּסְפָּא יִתְקוֹל כְּמוֹהֲרֵי בְּתֻלְתָּא:
@54 חָרָשָׁא לָא תָחֵי:
@55 כָּל דְיִשְׁכּוּב עִם בְּעִירָא אִתְקְטָלָא יִתְקְטֵל:
@56 דְדַבַּח לְטַעְוַת עַמְמַיָא יִתְקְטֵל אֶלָהֵן לִשְׁמָא דַיְיָ בִּלְחוֹדוֹהִי:
@57 וְגִיוֹרָא לָא תוֹנוּן וְלָא תְעִיקוּן לֵהּ אֲרֵי דַיָרִין הֱוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@58 כָּל אַרְמְלָא וְיִתָּם לָא תְעַנוּן:
@59 אִם עַנָאָה תְעַנֵי יָתֵהּ אֲרֵי אִם מִקְבַל יִקְבֵל קֳדָמַי קַבָּלָא אֱקַבֵּל קְבִלְתֵּהּ:
@60 וְיִתְקֵף רוּגְזִי וְאֶקְטוֹל יָתְכוֹן בְּחַרְבָּא וִיהֶוְיָן נְשֵׁיכוֹן אַרְמְלִין וּבְנֵיכוֹן יַתְמִין:
@61 אִם כַּסְפָּא תּוֹזֵף בְּעַמִי לְּעַנְיָא דִי עִמָךְ לָא תְהֵי לֵהּ כְּרַשְׁיָא לָא תְשַׁוּוֹן עֲלוֹהִי חִבּוּלְיָא:
@62 אִם מַשְׁכּוֹנָא תִסַב כְּסוּתָא דְחַבְרָךְ עַד מֵעַל שִׁמְשָׁא תְּתִיבִנֵהּ לֵהּ:
@63 אֲרֵי הִיא כְסוּתֵהּ בִּלְחוֹדַהּ הִיא תוֹתְבֵהּ לְמַשְׁכֵּיהּ בְּמָא יִשְׁכּוּב וִיהֵי אֲרֵי יִקְבֵל קֳדָמַי וֶאֱקַבֵּל קְבִלְתֵּהּ אֲרֵי חַנָנָא אֲנָא:
@64 דַיָנָא לָא תְקִיל וְרַבָּא בְעַמָךְ לָא תְלוּט:
@65 בִּכּוּרָךְ וְדִמְעָךְ לָא תְאַחֵר בּוּכְרָא דִבְנָיךְ תַּפְרֵשׁ קֳדָמָי:
@66 כֵּן תַּעְבֵּד לְתוֹרָךְ לְעָנָךְ שִׁבְעָא יוֹמִין יְהֵי עִם אִמֵהּ בְּיוֹמָא תְמִינָאָה תִּפְרְשִׁנֵהּ קֳדָמָי:
@67 וֶאֱנָשִׁין קַדִישִׁין תְּהוֹן קֳדָמָי וּבְשַׂר תְּלִישׁ מִן חֵיוָא חַיְתָא לָא תֵיכְלוּן לְכַלְבָּא תִּרְמוּן יָתֵהּ:
@68 לָא תְקַבֵּל שְׁמַע דִשְׁקָר לָא תְשַׁוִי יְדָךְ עִם חַיָבָא לְמֶהֱוֵי לֵהּ סָהִיד שְׁקָר:
@69 לָא תְהֵי בָּתַר סַגִיאִין לְאַבְאָשָׁא וְלָא תִתִּמְנַע מִלְאַלָפָא מָא דִבְעֵינָךְ עַל דִינָא בָּתַר סַגִיאֵי שְׁלַם דִינָא:
@70 וְעַל מִסְכֵּינָא לָא תְרַחֵם בְּדִינֵהּ:
@71 אֲרֵי תִפְגַע תּוֹרָא דְסָנְאָךְ אוֹ חֲמָרֵהּ דְטָּעֵי אָתָבָא תְּתִיבִנֵהּ לֵהּ:
@72 אֲרֵי תֶחֱזֵי חֲמָרָא דְסָנְאָךְ רְבִיעַ תְּחוֹת טוֹעֲנֵיהּ וְתִתִּמְנַע מִלְמִשְׁבַּק לֵהּ מִשְׁבַּק תִּשְׁבּוֹק מָא דִבְלִבָּךְ עֲלוֹהִי וּתְפָרֵק עִמֵהּ:
@73 לָא תַצְלֵי דִין מִסְכֵּינָךְ בְּדִינֵהּ:
@74 מִפִּתְגָמָא דְשִׁקְרָא הֱוֵי רָחִיק וְדִזְכֵי וְדִי נְפַק (דְכֵי) מִן דִינָא לָא תִקְטוֹל אֲרֵי לָא אֱזַכֵּי חַיָבָא:
@75 וְשׁוֹחֲדָא לָא תְקַבֵּל אֲרֵי שׁוֹחֲדָא מְעַוֵר עֵינֵי חַכִּימִין וּמְקַלְקֵל פִּתְגָמִין תְּרִיצִין:
@76 וְגִיוֹרָא לָא תְעִיקוּן וְאַתּוּן יְדַעְתּוּן יָת נַפְשָׁא דְגִיוֹרָא אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם:
@77 וְשִׁית שְׁנִין תִּזְרַע יָת אַרְעָךְ וְתִכְנוֹשׁ יָת עֲלַלְתַּהּ:
@78 וּשְׁבִעֵתָא תַּשְׁמְטִּנַהּ וְתַרְטְשִׁנַהּ וְיֵיכְלוּן מִסְכְּנֵי עַמָךְ וּשְׁאָרְהוֹן תֵּיכוּל חֵיוַת בָּרָא כֵּן תַּעְבֵּד לְכַרְמָךְ לְזֵיתָךְ:
@79 שִׁתָּא יוֹמִין תַּעְבֵּד עוֹבָדָיךְ וּבְיוֹמָא שְׁבִיעָאָה תָּנוּחַ בְּדִיל דִינוּחַ תּוֹרָךְ וְחַמָרָךְ וְיִשְּׁקוֹט בַּר אַמְתָךְ וְגִיוֹרָא:
@80 וּבְכֹל דִי אֲמָרִית לְכוֹן תִּסְתַּמְרוּן וְשׁוּם טַעֲוַת עַמְמַיָא לָא תִדְכְּרוּן לָא יִשְׁתְּמַע עַל פּוּמְכוֹן:
@81 תְּלַת זִמְנִין תֵּחוֹג קֳדָמַי בְּשַׁתָּא:
@82 יָת חַגָא דְפַטִירַיָא תִּטַר שִׁבְעָא יוֹמִין תֵּיכוּל פַּטִירָא כְּמָא דִפַקֵידִתָּךְ לִזְמַן יַרְחָא דַאֲבִיבָא אֲרֵי בֵהּ נְפַקְתָּ מִמִצְרָיִם וְלָא יִתְחֲזוּן קֳדָמַי רֵיקָנוּן:
@83 וְחַגָא דַחֲצָדָא בִּכּוּרֵי עוֹבָדָיךְ דִי תִזְרַע בְּחַקְלָא וְחַגָא דִכְנָשָׁא בְּמִפְּקָא דְשַׁתָּא בְּמִכְנְשָׁךְ יָת עוֹבָדָיךְ מִן חַקְלָא:
@84 תְּלַת זִמְנִין בְּשַׁתָּא יִתְחֲזוּן כָּל דְכוּרָךְ קֳדָם רִבּוֹן עָלְמָא יְיָ:
@85 לָא תִכּוֹס עַל חֲמִיעַ דַם פִּסְחִי וְלָא יְבִיתוּן בַּר מִן מַדְבְּחָא תַּרְבֵּי נִכְסַת חַגָא עַד צַפְרָא:
@86 רֵישׁ בִּכּוּרֵי אַרְעָךְ תַּיְתִי לְבֵית מִקְדְשָׁא דַיְיָ אֱלָהָךְ לָא תֵיכְלוּן בְּשַׂר בַּחֲלָב:
@87 הָא אֲנָא שָׁלַח מַלְאָכָא קֳדָמָךְ לְמִטְרָךְ בְּאָרְחָא וּלְאָעֳלוּתָךְ לְאַתְרָא דִאַתְקֵנִית:
@88 אִסְתַּמַּר מִן קֳדָמוֹהִי וְקַבֵּל לְמֵימְרֵהּ לָא תְסָרֵב לְקִבְלֵהּ אֲרֵי לָא יִשְׁבּוֹק לְחוֹבֵיכוֹן אֲרֵי בִשְׁמִי מֵימְרֵהּ:
@89 אֲרֵי אִם קַבָּלָא תְקַבֵּל לְמֵימְרֵהּ וְתַעְבֵּד כֹּל דִאֱמַלֵל וְאֶסְנֵי יָת סָנְאָךְ וְאָעִיק לְדִמְעִיקִין לָךְ:
@90 אֲרֵי יְהַךְ מַלְאָכִי קֳדָמָךְ וְיָעֵלִנָךְ לְוָת אֱמוֹרָאֵי וְחִתָּאֵי וּפְרִיזָאֵי וּכְנַעֲנָאֵי חִוָאֵי וִיבוּסָאֵי וֶאֱשֵׁצִנוּן:
@91 לָא תִסְגוּד לְטַעֲוָתְהוֹן וְלָא תִפְלְחִנוּן וְלָא תַעְבֵּד כְּעוֹבָדֵיהוֹן אֲרֵי פַגָרָא תְּפַגְרִנוּן וְתַבָּרָא תְתַבַּר קָמָתְהוֹן:
@92 וְתִפְלְחוּן קֳדָם יְיָ אֱלָהֲכוֹן וִיבָרֵךְ יָת מֵיכְלָךְ וְיָת מִשְׁתְּיָךְ וְאַעְדִי מַרְעִין בִּישִׁין מִבֵּינָךְ:
@93 לָא תְהֵי מְתַכְּלָא וְעַקְרָא בְּאַרְעָךְ יָת מִנְיַן יוֹמָיךְ אַשְׁלִים:
@94 יָת אֵימְתִי אֲשַׁלַח קֳדָמָךְ ואֶתְּפַר (נ''א וֶאֱשַׁגֵשׁ) יָת כָּל עַמָא דְאַתְּ אָתֵי לַאֲגָחָא בְּהוֹן וְאֶמְסַר יָת כָּל בַּעֲלֵי דְבָבָךְ קֳדָמָךְ מְחַזְרֵי קְדָל:
@95 וְאֶשְׁלַח יָת עֲרָעִיתָא קֳדָמָךְ וּתְתָרֵךְ יָת חִוָאֵי יָת כְּנַעֲנָאֵי וְיָת חִתָּאֵי מִן קֳדָמָךְ:
@96 לָא אֱתָרֵכִנוּן מִן קֳדָמָךְ בְּשַׁתָּא חֲדָא דִילְמָא תְהֵי אַרְעָא צַדְיָא וְתִסְגֵי עֲלָךְ חֵיוַת בָּרָא:
@97 זְעֵיר זְעֵיר אֱתָרֵכִנוּן מִן קֳדָמָךְ עַד דְתִסְגֵי וְתַחְסֵן יָת אַרְעָא:
@98 וֶאֱשַׁוֵי יָת תְּחוּמָךְ מִיַמָא דְסוּף וְעַד יַמָא דִפְלִשְׁתָּאֵי וּמִמַדְבְּרָא עַד פְּרָת אֲרֵי אֶמְסַר בִּידֵיכוֹן יָת יָתְבֵי אַרְעָא וּתְתָרֵכִנוּן מִן קֳדָמָךְ:
@99 לָא תִגְזַר לְהוֹן וּלְּטַעֲוָתְהוֹן קְיָם:
@100 לָא יֵתְבוּן בְּאַרְעָךְ דִילְמָא יְחַיְבוּן יָתָךְ קֳדָמָי אֲרֵי תִפְלַח יָת טַעֲוָתְהוֹן אֲרֵי יְהוֹן לָךְ לְתַקְלָא:
@101 וּלְמשֶׁה אֲמַר סַק לִקֳדָם יְיָ אַתְּ וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל וְתִסְגְדוּן מֵרָחִיק:
@102 וְיִתְקְרֵב משֶׁה בִלְחוֹדוֹהִי לִקֳדָם יְיָ וְאִנוּן לָא יִתְקָרְבוּן וְעַמָא לָא יִסְקוּן עִמֵהּ:
@103 וַאֲתָא משֶׁה וְאִשְׁתָּעִי לְעַמָא יָת כָּל פִּתְגָמַיָא דַיְיָ וְיָת כָּל דִינַיָא וַאֲתֵיב כָּל עַמָא קָלָא חַד וַאֲמָרוּ כָּל פִּתְגָמַיָא דִי מַלִיל יְיָ נַעְבֵּד:
@104 וּכְתַב משֶׁה יָת כָּל פִּתְגָמַיָא דַיְיָ וְאַקְדֵם בְּצַפְרָא וּבְנָא מַדְבְּחָא בְּשִׁפּוֹלֵי טוּרָא וְתַרְתָּא עֶשְׂרֵי קָמָן לִתְרֵי עֲסַר שִׁבְטַיָא דְיִשְׂרָאֵל:
@105 וּשְׁלַח יָת בּוּכְרֵי בְּנֵי יִשְׂרָאֵל וְאַסִיקוּ עֲלָוָן וְקָרִיבוּ נִכְסַת קוּדְשִׁין קֳדָם יְיָ תּוֹרִין:
@106 וּנְסִיב משֶׁה פַּלְגוּת דְמָא וְשַׁוִי בְּמִזְרְקַיָא וּפַלְגוּת דְמָא זְרַק עַל מַדְבְּחָא:
@107 וּנְסִיב סִפְרָא דִקְיָמָא וּקְרָא קֳדָם עַמָא וַאֲמָרוּ כֹּל דִי מַלִיל יְיָ נַעְבֵּד וּנְקַבֵּל:
@108 וּנְסִיב משֶׁה יָת דְמָא וּזְרַק עַל מַדְבְּחָא לְכַפָּרָא עַל עַמָא וַאֲמַר הָא דֵין דָם קְיָמָא דִגְזַר יְיָ עִמְכוֹן עַל כָּל פִּתְגָמַיָא הָאִלֵין:
@109 וּסְלֵיק משֶׁה וְאַהֲרֹן נָדָב וַאֲבִיהוּא וְשִׁבְעִין מִסָבֵי יִשְׂרָאֵל:
@110 וַחֲזוֹ יָת יְקַר אֱלָהָא דְיִשְׂרָאֵל וּתְחוֹת כָּרְסָא יְקָרֵהּ כְּעוֹבַד אֶבֶן טָבָא וּכְמֶחֱזֵי שְׁמַיָא לְבָרִירוּ:
@111 וּלְרַבְרְבֵי בְּנֵי יִשְׂרָאֵל לָא הֲוָה נִזְקָא וַחֲזוֹ יָת יְקָרָא דַיְיָ וַהֲווֹ חָדָן בְּקָרְבָּנֵיהוֹן דְאִתְקַבָּלוּ בְּרַעֲוָא כְּאִלוּ אָכְלִין וְשָׁתָן:
@112 וַאֲמַר יְיָ לְמשֶׁה סַק לִקֳדָמַי לְטוּרָא וֶהֱוֵי תַמָן וְאֶתֵּן לָךְ יָת לוּחֵי אַבְנָא וְאוֹרַיְתָא וְתַפְקֶדְתָּא דִכְתָבִית לְאַלוּפֵיהוֹן:
@113 וְקָם משֶׁה וִיהוֹשֻׁעַ מְשֻׁמְשָׁנֵהּ וּסְלֵיק משֶׁה לְטוּרָא דְאִתְגְלִי עֲלוֹהִי יְקָרָא דַיְיָ:
@114 וּלְםָבַיָא אֲמַר אוֹרִיכוּ לָנָא הָכָא עַד דִנְתוּב לְוָתְכוֹן וְהָא אַהֲרֹן וְחוּר עִמְכוֹן מָן דְאִית לֵהּ דִינָא יִתְקְרֵב לִקֳדָמֵיהוֹן:
@115 וּסְלֵק משֶׁה לְטוּרָא וַחֲפָא עֲנָנָא יָת טוּרָא:
@116 וּשְׁרָא יְקָרָא דַיְיָ עַל טוּרָא דְסִינַי וַחֲפָהִי עֲנָנָא שִׁתָּא יוֹמִין וּקְרָא לְמשֶׁה בְּיוֹמָא שְׁבִיעָאָה מִגוֹ עֲנָנָא:
@117 וְחֵיזוּ יְקָרָא דַיְיָ כְּחֵיזוּ אֶשָׁא אָכְלָא בְּרֵישׁ טוּרָא לְעֵינֵי בְּנֵי יִשְׂרָאֵל:
@118 וְעַל משֶׁה בְּגוֹ עֲנָנָא וּסְלֵיק לְטוּרָא וַהֲוָה משֶׁה בְּטּוּרָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן: פפפ:

@1 **ואלה המשפטים.** כל מקום שנאמר אלה פסל את הראשונים, ואלה מוסיף על הראשונים, מה הראשונים מסיני, אף אלו מסיני. ולמה נסמכה פרשת דינין לפרשת מזבח, לומר לך שתשים סנהדרין אצל המקדש [המזבח] : **אשר תשים לפניהם.** אמר לו הקדוש ברוך הוא למשה לא תעלה על דעתך לומר אשנה להם הפרק וההלכה ב' או ג' פעמים עד שתהא סדורה בפיהם כמשנתה, ואיני מטריח עצמי להבינם טעמי הדבר ופירושו, לכך נאמר אשר תשים לפניהם, כשלחן הערוך ומוכן לאכול לפני האדם: **לפניהם.** ולא לפני גוים, ואפילו ידעת בדין אחד שהם דנין אותו כדיני ישראל, אל תביאהו בערכאות שלהם, שהמביא דיני ישראל לפני גוים מחלל את השם ומיקר שם עבודה זרה להחשיבה, שנאמר (דברים לב לא) כי לא כצורנו צורם ואויבינו פלילים, כשאויבינו פלילים זהו עדות לעלוי יראתם:
@2 **כי תקנה עבד עברי.** עבד שהוא עברי, או אינו אלא עבדו של עברי, עבד כנעני שלקחתו מישראל, ועליו הוא אומר שש שנים יעבד, ומה אני מקים (ויקרא כה מו) והתנחלתם אתם, בלקוח מן הגוי, אבל בלקוח מישראל יצא בשש, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי, לא אמרתי אלא באחיך: **כי תקנה.** מיד בית דין שמכרוהו בגנבתו כמו שנאמר (שמות כב ב) אם אין לו ונמכר בגנבתו. או אינו אלא במוכר עצמו מפני דחקו, אבל מכרוהו בית דין לא יצא בשש, כשהוא אומר (ויקרא כה לט) וכי ימוך אחיך עמך ונמכר לך, הרי מוכר עצמו מפני דחקו אמור, ומה אני מקים כי תקנה, בנמכר בבית דין: **לחפשי.** לחרות:
@3 **אם בגפו יבא.** שלא היה נשוי אשה כתרגומו אם בלחודוהי. ולשון בגפו בכנפו, שלא בא אלא כמות שהוא, יחידי, בתוך לבושו בכנף בגדו: **בגפו יצא.** מגיד שאם לא היה נשוי מתחלה, אין רבו מוסר לו שפחה כנענית להוליד ממנה עבדים: **אם בעל אשה הוא.** ישראלית: **ויצאה אשתו עמו.** וכי מי הכניסה שתצא, אלא מגיד הכתוב, שהקונה עבד עברי חיב במזונות אשתו ובניו:
@4 **אם אדניו יתן לו אשה.** מכאן שהרשות ביד רבו למסור לו שפחה כנענית להוליד ממנה עבדים. או אינו אלא בישראלית, תלמוד לומר האשה וילדיה תהיה לאדוניה, הא אינו מדבר אלא בכנענית, שהרי העבריה אף היא יוצאה בשש, ואפילו לפני שש אם הביאה סימנין יוצאה, שנאמר (דברים טו יב) אחיך העברי או העבריה, מלמד, שאף העבריה יוצאה בשש:
@5 **את אשתי.** השפחה:
@6 **אל האלהים.** לבית דין, צריך שימלך במוכריו שמכרוהו לו: **אל הדלת או אל המזוזה.** יכול שתהא המזוזה כשרה לרצוע עליה, תלמוד לומר (דברים טו יז) ונתתה באזנו ובדלת, בדלת ולא במזוזה, הא מה תלמוד לומר או אל המזוזה, הקיש דלת למזוזה מה מזוזה מעומד אף דלת מעומד: **ורצע אדניו את אזנו במרצע.** הימנית. או אינו אלא של שמאל, תלמוד לומר אזן, אזן לגזרה שוה נאמר כאן ורצע אדניו את אזנו, ונאמר במצורע (ויקרא יד יד) תנוך אזן המטהר הימנית, מה להלן הימנית, אף כאן הימנית. ומה ראה אזן להרצע מכל שאר אברים שבגוף, אמר רבי יוחנן בן זכאי (קידושין כב ע''ב) אזן זאת ששמעה על הר סיני לא תגנוב, והלך וגנב, תרצע. ואם מוכר עצמו, אזן ששמעה על הר סיני (ויקרא כה נה) כי לי בני ישראל עבדים, והלך וקנה אדון לעצמו, תרצע. ר' שמעון היה דורש מקרא זה כמין חמר מה נשתנו דלת ומזוזה מכל כלים שבבית, אמר הקדוש ברוך הוא דלת ומזוזה שהיו עדים במצרים כשפסחתי על המשקוף ועל שתי המזוזות ואמרתי כי לי בני ישראל עבדים, עבדי הם ולא עבדים לעבדים, והלך זה וקנה אדון לעצמו, ירצע בפניהם: **ועבדו לעלם.** עד היובל. או אינו אלא לעולם כמשמעו, תלמוד לומר (ויקרא כה י) ואיש אל משפחתו תשובו, מגיד שחמשים שנה קרויים עולם, ולא שיהא עובדו כל חמשים שנה, אלא עובדו עד היובל בין סמוך בין מפלג:
@7 **וכי ימכר איש את בתו לאמה.** בקטנה הכתוב מדבר. יכול אפלו הביאה סימנים. אמרת קל וחמר ומה מכורה קדם לכן יוצאה בסימנין, כמו שנאמר (פסוק יא) ויצאה חנם אין כסף, שאנו דורשים אותן לסימני נערות, שאינה מכורה אינו דין שלא תמכר: **לא תצא כצאת העבדים.** כיציאת עבדים כנענים שיוצאים בשן ועין, אבל זו לא תצא בשן ועין, אלא עובדת שש או עד היובל, או עד שתביא סימנין, וכל הקודם קדם לחירותה ונותן לה דמי עינה או דמי שנה, או אינו אלא לא תצא כצאת העבדים בשש וביובל, תלמוד לומר (דברים טו יב) כי ימכר לך אחיך העברי או העבריה. מקיש עבריה לעברי לכל יציאותיו מה עברי יוצא בשש וביובל, אף עבריה יוצאה בשש וביובל, ומהו לא תצא כצאת העבדים, לא תצא בראשי אברים כעבדים כנענים. יכול העברי יוצא בראשי אברים, תלמוד לומר העברי או העבריה, מקיש עברי לעבריה מה העבריה אינה יוצאה בראשי אברים, אף הוא אינו יוצא בראשי אברים:
@8 **אם רעה בעיני אדניה.** שלא נשאה חן בעיניו לכנסה: **אשר לא יעדה.** שהיה לו ליעדה ולהכניסה לו לאשה, וכסף קניתה הוא כסף קדושיה. כאן רמז לך הכתוב שמצוה ביעוד ורמז לך שאינה צריכה קדושין אחרים: **והפדה.** יתן לה מקום להפדות ולצאת, שאף הוא מסיע בפדיונה ומה הוא מקום שנותן לה, שמגרע מפדיונה כמספר השנים שעשתה אצלו, כאלו היא שכורה אצלו. כיצד, הרי שקנאה במנה ועשתה אצלו שתי שנים אומרים לו יודע היית שעתידה לצאת לסוף שש, נמצא שקנית עבודת כל שנה ושנה בששית המנה, ועשתה אצלך שתי שנים, הרי שלישית המנה, טול שתי שלישיות המנה ותצא מאצלך: **לעם נכרי לא ימשל למכרה.** אינו רשאי למכרה לאחר, לא האדון ולא האב: **בבגדו בה.** אם בא לבגד בה, שלא לקים בה מצות ייעוד, וכן אביה, מאחר שבגד בה ומכרה לזה:
@9 **ואם לבנו ייעדנה.** האדון. מלמד, שאף בנו קם תחתיו ליעדה, אם ירצה אביו, ואינו צריך לקדשה קדושין אחרים. אלא אומר לה הרי את מיועדת לי בכסף שקבל אביך בדמיך: **כמשפט הבנות.** שאר, כסות ועונה:
@10 **אם אחרת יקח לו.** עליה: **שארה כסותה וענתה לא יגרע.** מן האמה שיעד לו כבר: **שארה.** מזונות: **כסותה.** כמשמעו: **ענתה.** תשמיש:
@11 **ואם שלש אלה לא יעשה לה.** אם אחת משלש אלה לא יעשה לה, ומה הן השלש, ייעדנה לו, או לבנו, או יגרע מפדיונה ותצא, וזה לא יעדה לא לו ולא לבנו, והיא לא היה בידה לפדות את עצמה: **ויצאה חנם.** רבה לה יציאה לזו יותר ממה שרבה לעבדים, ומה היא היציאה, ללמדך שתצא בסימנין ותשהה עמו עד שתביא סימנין. ואם הגיעו שש שנים קודם סימנין, כבר למדנו שתצא, שנאמר (דברים טו יב) העברי או העבריה ועבדך שש שנים, ומהו האמור כאן ויצאה חנם, שאם קדמו סימנים לשש שנים תצא בהן, או אינו אומר שתצא אלא בבגרות תלמוד לומר אין כסף לרבות יציאת בגרות ואם לא נאמרו שניהם הייתי אומר ויצאה חנם זו בגרות, לכך נאמרו שניהם, שלא לתן פתחון פה לבעל הדין לחלוק:
@12 **מכה איש ומת.** כמה כתובים נאמרו בפרשת רוצחין, ומה שבידי לפרש למה באו כלם, אפרש: **מכה איש ומת.** למה נאמר, לפי שנאמר (ויקרא כד יז) ואיש כי יכה כל נפש אדם מות יומת, שומע אני בהכאה בלא מיתה, תלמוד לומר מכה איש ומת, אינו חיב אלא בהכאה של מיתה. ואם נאמר מכה איש, ולא נאמר ואיש כי יכה, הייתי אומר אינו חיב עד שיכה איש, הכה את האשה ואת הקטן מנין, תלמוד לומר כי יכה כל נפש אדם, אפלו קטן ואפילו אשה. ועוד אלו נאמר מכה איש, שומע אני, אפלו קטן שהכה והרג יהא חיב, תלמוד לומר ואיש כי יכה, ולא קטן שהכה. ועוד, כי יכה כל נפש אדם, אפלו נפלים במשמע, תלמוד לומר מכה איש, אינו חיב עד שיכה בן קימא ראוי להיות איש:
@13 **ואשר לא צדה.** לא ארב לו ולא נתכון: **צדה.** לשון ארב, וכן הוא אומר (שמואל א כד יא) ואתה צודה את נפשי לקחתה, ולא יתכן לומר צדה לשון הצד ציד (בראשית כז לג) , שצידת חיות אין נופל ה''א בפועל שלה, ושם דבר בה ציד, וזה שם דבר בו צדיה ופועל שלו צודה, וזה פועל שלו צד. ואומר אני פתרונו כתרגומו ודלא כמן ליה. ומנחם חברו בחלק צד ציד, ואין אני מודה לו. ואם יש לחברו באחת ממחלוקת של צד, נחברנו בחלק (ישעיה סו יב) על צד תנשאו, (שמואל א' כ כ) צדה אורה, (דניאל ז כה) ומלין לצד עלאה ימלל. אף כאן אשר לא צדה לא צדד למצוא לו שום צד מיתה, ואף זה יש להרהר עליו, סוף דבר לשון אורב הוא: **והאלהים אנה לידו.** זמן לידו, לשון (תהלים צא י) לא תאנה אליך רעה, (משלי יב כא) לא יאנה לצדיק כל און, (מלכים ב' ה ז) מתאנה הוא לי, מזדמן למצא לי עלה: **והאלהים אנה לידו.** ולמה תצא זאת מלפניו, הוא שאמר דוד (שמואל א' כד יג) כאשר יאמר משל הקדמוני מרשעים יצא רשע, ומשל הקדמוני היא התורה, שהיא משל הקדוש ברוך הוא שהוא קדמונו של עולם. והיכן אמרה תורה מרשעים יצא רשע, והאלהים אנה לידו. במה הכתוב מדבר, בשני בני אדם, אחד הרג שוגג ואחד הרג מזיד, ולא היו עדים בדבר שיעידו, זה לא נהרג וזה לא גלה, והקדוש ברוך הוא מזמנן לפנדק אחד, זה שהרג במזיד יושב תחת הסלם, וזה שהרג שוגג עולה בסלם ונופל על זה שהרג במזיד והורגו, ועדים מעידים עליו ומחייבים אותו לגלות, נמצא זה שהרג בשוגג גולה, וזה שהרג במזיד נהרג: **ושמתי לך מקום.** אף במדבר, שינוס שמה, ואיזה מקום קולטו, זה מחנה לויה:
@14 **וכי יזיד.** למה נאמר, לפי שנאמר מכה איש וגו' שומע אני אפילו גוי, והרופא שהרג ושליח בית דין שהמית במלקות ארבעים, והאב המכה את בנו, והרב הרודה את תלמידו, והשוגג, תלמוד לומר וכי יזיד ולא שוגג על רעהו ולא על גוי. להרגו בערמה. ולא שליח בית דין והרופא והרודה את בנו ותלמידו, שאף על פי שהם מזידין אין מערימין: **מעם מזבחי.** אם היה כהן ורוצה לעבוד עבודה, תקחנו למות:
@15 **ומכה אביו ואמו.** לפי שלמדנו על החובל בחברו שהוא בתשלומין ולא במיתה, הצרך לומר על החובל באביו שהוא במיתה, ואינו חיב אלא בהכאה שיש בה חבורה: **אביו ואמו.** או זה או זה: **מות יומת.** בחנק:
@16 **וגנב איש ומכרו.** למה נאמר, לפי שנאמר (דברים כד ז) כי ימצא איש גונב נפש מאחיו, אין לי אלא איש שגנב נפש, אשה או טומטום או אנדרוגינוס שגנבו מנין, תלמוד לומר וגונב איש ומכרו. ולפי שנאמר כאן וגונב איש, אין לי אלא גונב איש, גונב אשה מנין, תלמוד לומר (שם) גונב נפש, לכך הצרכו שניהם, מה שחסר זה גלה זה: **ונמצא בידו.** שראוהו עדים שגנבו ומכרו ונמצא בידו כבר קדם מכירה: **מות יומת.** בחנק, כל מיתה האמורה בתורה סתם חנק היא. והפסיק הענין וכתב וגונב איש, בין מכה אביו ואמו למקלל אביו ואמו, ונראה לי הינו פלוגתא, דמר סבר מקשנן הכאה לקללה, ומר סבר לא מקשנן:
@17 **ומקלל אביו ואמו.** למה נאמר, לפי שהוא אומר (ויקרא כ ט) איש איש אשר יקלל את אביו, אין לי אלא איש שקלל את אביו, אשה שקללה את אביה מנין, תלמוד לומר ומקלל אביו ואמו סתם בין איש ובין אשה. אם כן למה נאמר איש אשר יקלל, להוציא את הקטן: **מות יומת.** בסקילה, וכל מקום שנאמר דמיו בו, בסקילה ובנין אב לכלם (ויקרא כ כז) באבן ירגמו אותם דמיהם בם, ובמקלל אביו ואמו נאמר (ויקרא כ ט) דמיו בו:
@18 **וכי יריבן אנשים.** למה נאמר, לפי שנאמר (פסוק כד) עין תחת עין, לא למדנו אלא דמי אבריו, אבל שבת ורפוי לא למדנו, לכך נאמרה פרשה זו: **ונפל למשכב.** כתרגומו ויפל לבוטלן, לחולי שמבטלו ממלאכתו:
@19 **על משענתו.** על בוריו וכחו: **ונקה המכה.** וכי תעלה על דעתך שיהרג זה שלא הרג, אלא למדך כאן שחובשים אותו, עד שנראה אם יתרפא זה, וכן משמעו כשקם זה והולך על משענתו אז נקה המכה, אבל עד שלא יקום זה לא נקה המכה: **רק שבתו.** בטול מלאכתו מחמת החולי, אם קטע ידו או רגלו, רואין בטול מלאכתו מחמת החולי כאלו הוא שומר קשואין, שהרי אף לאחר החולי אינו ראוי למלאכת יד ורגל, והוא כבר נתן לו מחמת נזקו דמי ידו ורגלו, שנאמר (פסוק כד) יד תחת יד רגל תחת רגל: **ורפא ירפא.** כתרגומו, ישלם שכר הרופא:
@20 **וכי יכה איש את עבדו או את אמתו.** בעבד כנעני הכתוב מדבר. או אינו אלא בעברי, תלמוד לומר כי כספו הוא, מה כספו קנוי לו עולמית, אף עבד הקנוי לו עולמית. והרי היה בכלל (פסוק יב) מכה איש ומת, אלא בא הכתוב והוציאו מן הכלל, להיות נדון בדין יום או יומים, שאם לא מת תחת ידו ושהה מעת לעת פטור: **בשבט.** כשיש בו כדי להמית הכתוב מדבר. או אינו אלא אפלו אין בו כדי להמית, תלמוד לומר בישראל (במדבר לה יז) ואם באבן יד אשר ימות בה הכהו, והלא דברים קל וחמר מה ישראל חמור אין חיב עליו, אלא אם כן הכהו בדבר שיש בו כדי להמית, ועל אבר שהוא כדי למות בהכאה זו, עבד הקל לא כל שכן: **נקם ינקם.** מיתת סייף, וכן הוא אומר (ויקרא כו כה) חרב נוקמת נקם ברית:
@21 **אך אם יום או יומים יעמד לא יקם.** אם על יום אחד הוא פטור, על יומים לא כל שכן, אלא יום שהוא כיומים, ואיזה, זה מעת לעת: **לא יקם כי כספו הוא.** הא אחר שהכהו, אף על פי ששהה מעת לעת קדם שמת, חיב:
@22 **וכי ינצו אנשים.** זה עם זה, ונתכון להכות את חברו והכה את האשה: **ונגפו.** אין נגיפה אלא לשון דחיפה והכאה, כמו (תהלים צא יב) פן תגוף באבן רגלך, (ירמיה יג טז) ובטרם יתנגפו רגליכם, (ישעיה ח יד) ולאבן נגף: **ולא יהיה אסון.** באשה: **ענוש יענש.** לשלם דמי ולדות לבעל שמין אותה, כמה היתה ראויה למכר בשוק להעלות בדמיה בשביל הריונה: **ענוש יענש.** יגבו ממון ממנו, כמו (דברים כב יט) וענשו אותו מאה כסף: **כאשר ישית עליו** וגו' **.** כשיתבענו הבעל בבית דין להשית עליו עונש על כך: **ונתן.** המכה דמי ולדות: **בפללים.** על פי הדינים:
@23 **ואם אסון יהיה.** באשה: **ונתתה נפש תחת נפש.** רבותינו חולקין בדבר. יש אומרים נפש ממש, ויש אומרים ממון, אבל לא נפש ממש, שהמתכון להרג את זה והרג את זה פטור ממיתה ומשלם ליורשיו דמיו, כמו שהיה נמכר בשוק:
@24 **עין תחת עין.** סמא עין חברו נותן לו דמי עינו, כמה שפחתו דמיו למכר בשוק, וכן כלם, ולא נטילת אבר ממש, כמו שדרשו רבותינו בפרק החובל (בבא קמא פד א) :
@25 **כויה תחת כויה.** מכות אש, ועד עכשיו דבר בחבלה שיש בה פחת דמים, ועכשיו בשאין בה פחת דמים, אלא צער, כגון כואו בשפוד על צפרנו אומדים כמה אדם כיוצא בזה רוצה לטל להיות מצטער כך: **פצע.** היא מכה המוציאה דם, שפצע את בשרו, נברדור''א בלעז , הכל לפי מה שהוא אם יש בו פחת דמים נותן נזק, ואם נפל למשכב נותן שבת ורפוי ובשת וצער. ומקרא זה יתר הוא, ובהחובל דרשוהו רבותינו לחייב על הצער אפלו במקום נזק, שאף על פי שנותן לו דמי ידו, אין פוטרין אותו מן הצער לומר הואיל וקנה ידו יש עליו לחתכה בכל מה שירצה, אלא אומרים יש לו לחתכה בסם, שאינו מצטער כל כך, וזה חתכה בברזל וצערו: **חבורה.** היא מכה שהדם נצרר בה ואינו יוצא, אלא שמאדים הבשר כנגדו ולשון חבורה [ טי''א ] בלעז [כתם] , כמו (ירמיה יג כג) ונמר חברברתיו ותרגומו משקופי, לשון חבטה בטדור''א בלעז , וכן ושדופת קדים (בראשית מא ו) שקיפן קדום, חבוטות ברוח, וכן על המשקוף (לעיל יב כג) על שם שהדלת נושק עליו:
@26 **את עין עבדו.** כנעני, אבל עברי אינו יוצא בשן ועין, כמו שאמרנו אצל לא תצא כצאת העבדים (פסוק ז) : **תחת עינו.** וכן בעשרים וארבעה ראשי אברים אצבעות הידים והרגלים. ושתי אזנים והחוטם וראש הגויה, שהוא גיד האמה. ולמה נאמר שן ועין, שאם נאמר עין ולא נאמר שן, הייתי אומר מה עין שנברא עמו אף כל שנברא עמו, והרי שן לא נברא עמו, ואם נאמר שן ולא נאמר עין, הייתי אומר אפלו שן תינוק שיש לה חליפין, לכך נאמר עין:
@28 **וכי יגח שור.** אחד שור ואחד כל בהמה וחיה ועוף אלא שדבר הכתוב בהוה: **ולא יאכל את בשרו.** ממשמע שנאמר סקול יסקל השור, איני יודע שהוא נבלה, ונבלה אסורה באכילה, אלא מה תלמוד לומר ולא יאכל את בשרו, שאפלו שחטו לאחר שנגמר דינו, אסור באכילה. בהנאה מנין, תלמוד לומר: **ובעל השור נקי.** כאדם האומר לחברו יצא פלוני נקי מנכסיו ואין לו בהם הנאה של כלום, זהו מדרשו. ופשוטו כמשמעו לפי שנאמר במועד וגם בעליו יומת, הצרך לומר בתם ובעל השור נקי:
@29 **מתמל שלשם.** הרי שלש נגיחות: **והועד בבעליו.** לשון התראה בעדים, כמו (בראשית מג ג) העד העיד בנו האיש: **והמית איש** וגו' **.** לפי שנאמר וכי יגח, אין לי אלא שהמיתו בנגיחה, המיתו בנשיכה, דחיפה, רביצה, בעיטה מנין, תלמוד לומר והמית [מכל מקום] : **וגם בעליו יומת.** בידי שמים. יכול בידי אדם, תלמוד לומר (במדבר לה כא) מות יומת המכה רוצח הוא, על רציחתו אתה הורגו, ואי אתה הורגו על רציחת שורו:
@30 **אם כפר יושת עליו.** ''אם'' זה אינו תלוי, והרי הוא כמו (לקמן כב כד) אם כסף תלוה, לשון אשר זה משפטו, שישיתו עליו בית דין כופר: **ונתן פדיון נפשו.** דמי נזק, דברי רבי ישמעאל, רבי עקיבא אומר דמי מזיק:
@31 **או בן יגח.** בן שהוא קטן: **או בת.** שהיא קטנה. לפי שנאמר והמית איש או אשה, יכול אינו חיב אלא על הגדולים, תלמוד לומר או בן יגח וגו' , לחייב על הקטנים כגדולים:
@32 **אם עבד' או אמה.** כנעניים: **שלשים שקלים יתן.** גזרת הכתוב הוא, בין שהוא שוה אלף זוז, בין שאינו שוה אלא דינר. והשקל משקלו ארבעה זהובים שהם חצי אונקיא למשקל הישר של קולוניי''א :
@33 **וכי יפתח איש בור.** שהיה מכסה וגלהו: **או כי יכרה.** למה נאמר, אם על הפתיחה חיב, על הכריה לא כל שכן, אלא להביא כורה אחר כורה שהוא חיב: **ולא יכסנו.** הא אם כסהו, פטור, ובחופר ברשות הרבים דבר הכתוב: **שור או חמור.** הוא הדין לכל בהמה וחיה, שבכל מקום שנאמר שור וחמור, אנו למדין אותו שור שור משבת, שנאמר למען ינוח שורך וחמורך (שמות כג יב) , מה להלן כל בהמה וחיה כשור. שהרי נאמר במקום אחר וכל בהמתך (דברים ה יג) אף כאן, כל בהמה וחיה כשור, ולא נאמר שור וחמור אלא שור, ולא אדם, חמור, ולא כלים:
@34 **בעל הבור.** בעל התקלה, אף על פי שאין הבור שלו, שעשאו ברשות הרבים, עשאו הכתוב בעליו להתחיב עליו בנזקיו: **כסף ישיב לבעליו.** ישיב, לרבות שוה כסף, ואפלו סבין: **והמת יהיה לו.** לנזק, שמין את הנבלה ונוטלה בדמים ומשלם לו המזיק עליה תשלומי נזקו:
@35 **וכי יגף.** ידחוף, בין בקרניו, בין בגופו, בין ברגליו, בין שנשכו בשניו, כלן בכלל נגיפה הם, שאין נגיפה אלא לשון מכה: **שור איש.** שור של איש: **ומכרו את השור** וגו' **.** בשוים הכתוב מדבר, שור שוה מאתים שהמית שור שוה מאתים, בין שהנבלה שוה הרבה, בין שהיא שוה מעט, כשנוטל זה חצי החי וחצי המת, וזה חצי החי וחצי המת, נמצא כל אחד מפסיד חצי נזק שהזיקה המיתה, למדנו שהתם משלם חצי נזק, שמן השוין אתה למד לשאינן שוין, כי דין התם לשלם חצי נזק לא פחות ולא יותר. או יכול אף בשאינן שוין בדמיהן כשהן חיים, אמר הכתוב וחצו את שניהם, אם אמרת כן, פעמים שמזיק משתכר הרבה, כשהנבלה שוה למכר לנכרים הרבה יותר מדמי שור המזיק, ואי אפשר שיאמר הכתוב, שיהא המזיק נשכר. או פעמים שהנזק נוטל הרבה יותר מדמי נזק שלם, שחצי דמי שור המזיק שוין יותר מכל דמי שור הנזק, ואם אמרת כן, הרי תם חמור ממועד, על כרחך לא דבר הכתוב אלא בשוין. ולמדך שהתם משלם חצי נזק, ומן השוין תלמד לשאינן שוין, שהמשתלם חצי נזקו שמין לו את הנבלה, ומה שפחתו דמיו בשביל המיתה, נוטל חצי הפחת והולך, ולמה אמר הכתוב בלשון הזה ולא אמר ישלם חציו, ללמד שאין התם משלם אלא מגופו, ואם נגח ומת, אין הנזק נוטל אלא הנבלה, ואם אינה מגעת לחצי נזקו, יפסיד. או שור שוה מנה שנגח שור שוה חמש מאות זוז, אינו נוטל אלא את השור, שלא נתחיב התם לחיב את בעליו לשלם מן העליה:
@36 **או נודע.** או לא היה תם, אלא נודע כי שור נגח הוא היום, ומתמול שלשום, הרי שלש נגיחות: **שלם ישלם שור.** נזק שלם: **והמת יהיה לו.** לנזק, ועליו ישלים המזיק עד שישתלם נזק כל נזקו:
@37 **חמשה בקר** וגו' **.** אמר רבן יוחנן בן זכאי חס המקום על כבודן של בריות, שור שהולך ברגליו ולא נתבזה בו הגנב לנשאו על כתפו, משלם חמשה, שה שנשאו על כתפו, משלם ארבעה הואיל ונתבזה בו. אמר רבי מאיר בא וראה כמה גדולה כחה של מלאכה, שור שבטלו ממלאכתו משלם חמשה, שה שלא בטלו ממלאכתו ארבעה: **תחת השור' תחת השה.** שנאן הכתוב לומר, שאין מדת תשלומי ארבעה וחמשה נוהגת אלא בשור ושה בלבד:
@38 **אם במחתרת.** כשהיה חותר את הבית: **אין לו דמים.** אין זו רציחה, הרי הוא כמת מעיקרו. כאן למדתך תורה אם בא להרגך, השכם להרגו, וזה להרגך בא שהרי יודע הוא, שאין אדם מעמיד עצמו ורואה שנוטלין ממונו בפניו ושותק, לפיכך על מנת כן בא, שאם יעמוד בעל הממון כנגדו יהרגנו:
@39 **אם זרחה השמש עליו.** אין זה אלא כמן משל אם ברור לך הדבר שיש לו שלום עמך, כשמש הזה שהוא שלום בעולם, כך פשוט לך שאינו בא להרוג, אפילו יעמוד בעל הממון כנגדו, כגון אב החותר לגנוב ממון הבן, בידוע שרחמי האב על הבן, ואינו בא על עסקי נפשות: **דמים לו.** כחי הוא חשוב ורציחה היא, אם יהרגהו בעל הבית: **שלם ישלם.** הגנב ממון שגנב, ואינו חיב מיתה. ואונקלוס שתרגם אם עינא דסהדיא נפלת עלוהי, לקח לו שטה אחרת, לומר שאם מצאוהו עדים קדם שבא בעל הבית, וכשבא בעל הבית נגדו, התרו בו, שלא יהרגהו, דמים לו, חיב עליו אם הרגו, שאחר שיש רואים לו, אין הגנב הזה בא על עסקי נפשות, ולא יהרוג את בעל הממון:
@40 **אם המצא תמצא בידו.** ברשותו, שלא טבח ולא מכר: **משור עד חמור.** כל דבר בכלל תשלומי כפל בין שיש בו רוח חיים בין שאין בו רוח חיים, שהרי נאמר במקום אחר (פסוק ח) על שה על שלמה על כל אבדה וגו' ישלם שנים לרעהו: **חיים שנים ישלם.** ולא ישלם לו מתים, אלא חיים או דמי חיים:
@41 **כי יבער. את בעירה ובער.** כלם לשון בהמה, כמו (במדבר כ ד) אנחנו ובעירנו: **כי יבער.** יוליך בהמותיו בשדה וכרם של חברו ויזיק אתו באחת משתי אלה או בשלוח בעירה, או בבעור. ופירשו רבותינו שלוח הוא נזקי מדרך כף רגל, ובער הוא נזקי השן האוכלת ומבערת: **בשדה אחר.** בשדה של איש אחר: **מיטב שדהו ישלם.** שמין את הנזק, ואם בא לשלם לו קרקע דמי נזקו, ישלם לו ממיטב שדותיו אם היה נזקו סלע יתן לו שוה סלע מעדית שיש לו. למדך הכתוב, שהנזקין שמין להם בעדית:
@42 **כי תצא אש.** אפילו מעצמה: **ומצאה קוצים.** קרדונ''ש בלעז : **ונאכל גדיש.** שליחכה בקוצים עד שהגיעה לגדיש או לקמה המחברת לקרקע: **או השדה.** שליחכה את נירו וצריך לניר אותה פעם שניה: **שלם ישלם המבעיר.** אף על פי שהדליק בתוך שלו והיא יצאה מעצמה על ידי קוצים שמצאה, חיב לשלם, לפי שלא שמר את גחלתו שלא תצא ותזיק:
@43 **וגנב מבית האיש.** לפי דבריו: **אם ימצא הגנב.** ישלם הגנב שנים לבעלים:
@44 **אם לא ימצא הגנב.** ובא השומר הזה שהוא בעל הבית: **ונקרב.** אל הדינין לדון עם זה ולשבע לו שלא שלח ידו בשלו:
@45 **על כל דבר פשע.** שימצא שקרן בשבועתו, שיעידו עדים שהוא עצמו גנבו, וירשיעוהו אלהים על פי העדים: **ישלם שנים לרעהו.** למדך הכתוב, שהטוען בפקדון לומר נגנב המנו, ונמצא שהוא עצמו גנבו, משלם תשלומי כפל. ואימתי בזמן שנשבע ואחר כך באו עדים, שכך דרשו רבותינו זכרונם לברכה ונקרב בעל הבית אל האלהים, קריבה זו שבועה היא. אתה אומר לשבועה, או אינו אלא לדין, שכיון שבא לדין וכפר לומר נגנבה, מיד יתחיב כפל, אם באו עדים שהוא בידו. נאמר כאן שליחות יד, ונאמר למטה שליחות יד (פסוק י) שבועת ה' תהיה בין שניהם אם לא שלח ידו, מה להלן שבועה אף כאן שבועה: **אשר יאמר כי הוא זה.** לפי פשוטו אשר יאמר העד כי הוא זה שנשבעת עליו הרי הוא אצלך. עד הדינין יבא דבר שניהם ויחקרו את העדים, ואם כשרים הם וירשיעוהו לשומר זה, ישלם שנים, ואם ירשיעו את העדים, שנמצאו זוממין, ישלמו הם שנים לשומר. ורבותינו זכרונם לברכה דרשו כי הוא זה, ללמד שאין מחייבין אותו שבועה אלא אם כן הודה במקצת לומר כך וכך אני חיב לך, והמותר נגנב ממני:
@46 **כי יתן איש אל רעהו חמור או שור.** פרשה ראשונה נאמרה בשומר חנם, לפיכך פטר בו את הגנבה, כמו שנאמר (פסוק ו) וגנב מבית האיש, אם לא ימצא הגנב ונקרב בעל הבית לשבועה, למדת שפוטר עצמו בשבועה זו. ופרשה זו אמורה בשומר שכר, לפיכך אינו פטור אם נגנבה, כמו שכתוב (פסוק יא) אם גנב יגנב מעמו ישלם, אבל על האונס, כגון מת מעצמו, או נשבר או נשבה בחזקה על ידי לסטים, ואין רואה שיעיד בדבר:
@47 **שבועת ה' תהיה.** ישבע שכן הא כדבריו, והוא לא שלח בה יד להשתמש בה לעצמו, שאם שלח בה יד, ואחר כך נאנסה, חיב באנסים: **ולקח בעליו.** השבועה: **ולא ישלם.** לו השומר כלום:
@49 **אם טרף יטרף.** על ידי חיה רעה: **יבאהו עד.** יביא עדים שנטרפה באונס, ופטור: **הטרפה לא ישלם.** אינו אומר טרפה לא ישלם, אלא הטרפה, יש טרפה שהוא משלם ויש טרפה שאינו משלם. טרפת חתול ושועל ונמיה משלם. טרפת זאב, ארי ודב ונחש אינו משלם. ומי לחשך לדון כן, שהרי כתיב ומת או נשבר או נשבה, מה מיתה שאין יכול להציל, אף שבר ושביה שאין יכול להציל:
@50 **וכי ישאל.** בא ללמדך על השואל שחיב באונסין: **בעליו אין עמו.** אם בעליו שלשור אינו עם השואל במלאכתו:
@51 **אם בעליו עמו.** בין שהוא באותה מלאכה, בין שהוא במלאכה אחרת, היה עמו בשעת שאלה, אינו צריך להיות עמו בשעת שבירה ומיתה: **אם שכיר הוא.** אם השור אינו שאול אלא שכור, **בא בשכרו.** ליד השוכר הזה ולא בשאלה, ואין כל הנאה שלו, שהרי על ידי שכרו נשתמש, ואין לו משפט שואל להתחיב באנסין. ולא פרש מה דינו, אם כשומר חנם או כשומר שכר, לפיכך נחלקו בו חכמי ישראל, שוכר כיצד משלם, רבי מאיר אומר כשומר חנם. רבי יוחנן אומר כשומר שכר:
@52 **וכי יפתה.** מדבר על לבה עד ששומעת לו, וכן תרגומו וארי ישדל. שדול בלשון ארמי כפתוי בלשון עברי: **מהר ימהרנה.** יפסוק לה מהר כמשפט איש לאשתו, שכותב לה כתבה וישאנה:
@53 **כמהר הבתולות.** שהוא קצוב חמשים כסף אצל התופס את הבתולה ושוכב עמה באונס שנאמר (דברים כב כט) ונתן האיש השוכב עמה לאבי הנער חמשים כסף:
@54 **מכשפה לא תחיה.** אלא תומת בבית דין, ואחד זכרים ואחד נקבות, אלא שדבר הכתוב בהוה שהנשים מצויות מכשפות:
@55 **כל שוכב עם בהמה מות יומת.** בסקילה, רובע כנרבעת, שכתוב בהן (ויקרא כ טז) דמיהם בם:
@56 **לאלהים.** לעבודה זרה. אלו היה נקוד לאלהים היה צריך לפרש ולכתב אחרים, עכשיו שאמר לאלהים, אין צריך לפרש אחרים, שכל למד ובית המשמשות בראש התבה אם נקודה בחטף, כגון למלך, למדבר, לעיר, צריך לפרש לאיזה מלך, לאיזה מדבר, לאיזה עיר, וכן למלכים, לרגלים צריך לפרש לאיזה, ואם אינו מפרש, כל מלכים במשמע, וכן לאלהים כל אלהים משמע, אפלו קדש, אבל כשהיא נקודה פת''ח, כמו למלך, למדבר, לעיר נודע באיזה מלך, באיזו מדבר ובאיזה עיר מדבר, וכן לאלהים, לאותן שהזהרתם עליהם במקום אחר, כיוצא בו (תהלים פו ח) אין כמוך באלהים, לפי שלא פרש הצרך לנקד פתח: **יחרם.** יומת. ולמה נאמר יחרם, והלא כבר נאמר בו מיתה במקום אחר (דברים יז ה) והוצאת את האיש ההוא או את האשה ההיא וגו' , אלא לפי שלא פרש על איזו עבודה חיב מיתה, שלא תאמר כל עבודות במיתה, בא ופרש לך כאן זובח לאלהים יחרם, לומר לך, מה זביחה עבודה הנעשית בפנים לשמים, אף אני מרבה המקטיר והמנסך והמשתחוה, שהן עבודת בפנים וחיבים עליהם לכל עבודה זרה בין שדרכה לעבדה בכך, בין שאין דרכה לעבדה בכך, אבל שאר עבודות, כגון המכבד והמרבץ והמגפף והמנשק, אינו במיתה, אלא באזהרה:
@57 **וגר לא תונה.** אונאת דברים, קונטרליי''ר בלעז [לקנטר] , כמו (ישעיה מט כו) והאכלתי את מוניך את בשרם: **ולא תלחצנו.** בגזלת ממון: **כי גרים הייתם.** אם הוניתו, אף הוא יכול להונותך ולומר לך אף אתה מגרים באת, מום שבך אל תאמר לחברך. כל לשון גר, אדם שלא נולד באותה מדינה, אלא בא ממדינה אחרת לגור שם:
@58 **כל אלמנה ויתום לא תענון.** הוא הדין לכל אדם, אלא שדבר הכתוב בהווה, לפי שהם תשושי כח ודבר מצוי לענותם:
@59 **אם ענה תענה אתו.** הרי זה מקרא קצר, גזם ולא פרש ענשו, כמו (בראשית ד טו) לכן כל הרג קין גזם ולא פרש ענשו אף כאן אם ענה תענה אתו, לשון גזום, כלומר סופך לטול את שלך, למה, כי אם צעק יצעק אלי וגו' :
@60 **והיו נשיכם אלמנות.** ממשמע שנאמר והרגתי אתכם, איני יודע שנשיכם אלמנות ובניכם יתומים, אלא הרי זו קללה אחרת, שיהיו הנשים צרורות כאלמנות חיות, שלא יהיו עדים למיתת בעליהן ותהיינה אסורות להנשא והבנים יהיו יתומים, שלא יניחום בית דין לירד לנכסי אביהם לפי שאין יודעים אם מתו אם נשבו:
@61 **אם כסף תלוה את עמי.** רבי ישמעאל אומר כל אם ואם שבתורה רשות, חוץ משלשה וזה אחד מהן: **את עמי.** עמי וגוי, עמי קדם. עני ועשיר, עני קדם. עניי עירך ועניי עיר אחרת, עניי עירך קודמין. וזה משמעו אם כסף תלוה, את עמי תלוהו, ולא לגוי ולאיזה מעמי, את העני, ולאיזה עני לאותו שעמך. דבר אחר את העני, שלא תנהג בו מנהג בזיון בהלואה, שהוא עמי: **את העני עמך.** הוי מסתכל בעצמך כאלו אתה העני: **לא תהיה לו כנשה.** לא תתבענו בחזקה, אם אתה יודע שאין לו, אל תהי דומה עליו כאלו הלויתו, אלא כאלו לא הלויתו, כלומר לא תכלימהו: **נשך.** רבית שהוא כנשיכת נחש, שנושך חבורה קטנה ברגלו ואינו מרגיש, ופתאום הוא מבצבץ ונופח עד קדקדו, כך רבית, אינו מרגיש ואינו נכר עד שהרבית עולה ומחסרו ממון הרבה:
@62 **אם חבל תחבל.** כל לשון חבלה אינו משכון בשעת הלואה, אלא שממשכנין את הלוה, כשמגיע הזמן ואינו פורע. חבל תחבול כפל לך בחבלה, עד כמה פעמים, אמר הקדוש ברוך הוא כמה אתה חיב לי, והרי נפשך עולה אצלי כל אמש ואמש ונותנת דין וחשבון ומתחיבת לפני, ואני מחזירה לך, אף אתה טול והשב טול והשב: **עד בא השמש תשיבנו לו.** כל היום תשיבנו לו עד בא השמש, וכבוא השמש תחזור ותטלנו, עד שיבא בקר של מחר, ובכסות יום הכתוב מדבר, שאין צריך לה בלילה:
@63 **כי הוא כסותה.** זו טלית: **שמלתו.** זו חלוק: **במה ישכב.** לרבות את המצע:
@64 **אלהים לא תקלל.** הרי זו אזהרה לברכת השם, ואזהרה לקללת דין:
@65 **מלאתך.** חובה המטלת עליך כשתתמלא תבואתך להתבשל, והם בכורים: **ודמעך.** התרומה, ואיני יודע מהו לשון דמע: **לא תאחר.** לא תשנה סדר הפרשתן, לאחר את המקדם ולהקדים את המאחר, שלא יקדים תרומה לבכורים ומעשר לתרומה: **בכור בניך תתן לי.** לפדותו בחמש סלעים מן הכהן. והלא כבר צוה עליו במקום אחר, אלא כדי לסמוך לו כט **כן תעשה לשורך.** מה בכור אדם לאחר שלשים יום פודהו שנאמר (במדבר יח טז) ופדויו מבן חדש תפדה, אף בכור בהמה דקה [גסה] מטפל בו שלשים יום ואחר כך נותנו לכהן: **שבעת ימים יהיה עם אמו.** זו אזהרה לכהן, שאם בא למהר את הקרבתו, לא ימהר קדם שמונה, לפי שהוא מחסר זמן: **ביום השמיני תתנו לי.** יכול יהא חובה לבו ביום, נאמר כאן שמיני, ונאמר להלן (ויקרא כב כז) ומיום השמיני והלאה ירצה, מה שמיני האמור להלן להכשיר משמיני ולהלן, אף שמיני האמור כאן להכשיר משמיני ולהלן, וכן משמעו וביום השמיני אתה רשאי לתנו לי:
@67 **ואנשי קדש תהיון לי.** אם אתם קדושים ופרושים משקוצי נבלות וטרפות הרי אתם שלי, ואם לאו אינכם שלי: **ובשר בשדה טרפה.** אף בבית כן, אלא שדבר הכתוב בהוה, מקום שדרך בהמות לטרף, וכן (דבר' כב כז) כי בשדה מצאה, וכן (שם כג יא) אשר לא יהיה טהור מקרה לילה, הוא הדין מקרה יום, אלא שדבר הכתוב בהוה. ואונקלוס תרגם ובשר תליש מן חיוא חיא, בשר שנתלש על ידי טרפת זאב או ארי, מן חיה כשרה או מבהמה כשרה בחייה: **לכלב תשלכון אתו.** אף הגוי ככלב, או אינו אלא כלב כמשמעו, תלמוד לומר בנבלה (דב' יד כא) או מכר לנכרי, קל וחמר לטרפה שמתרת בכל הנאות. אם כן מה תלמוד לומר לכלב, למדך הכתוב שאין הקדוש ברוך הוא מקפח שכר כל בריה, שנאמר (שמות יא ז) ולכל בני ישראל לא יחרץ כלב לשונו, אמר הקדוש ברוך הוא תנו לו שכרו:
@68 **לא תשא שמע שוא.** כתרגומו לא תקבל שמע דשקר, אזהרה למקבל לשון הרע, ולדין, שלא ישמע דברי בעל דין עד שיבא בעל דין חברו: **אל תשת ידך עם רשע.** הטוען את חברו תביעת שקר, שהבטיחהו להיות לו עד חמס:
@69 **לא תהיה אחרי רבים לרעת.** יש במקרא זה מדרשי חכמי ישראל, אבל אין לשון המקרא מישב בהן על אפניו. מכאן דרשו שאין מטין לחובה בהכרעת דין אחד, וסוף המקרא דרשו אחרי רבים להטות, שאם יש שנים במחיבין יותר על המזכין, הטה הדין על פיהם לחובה ובדיני נפשות הכתוב מדבר, ואמצע המקרא דרשו ולא תענה על רב, על רב, שאין חולקין על מפלא שבבית דין, לפיכך מתחילין בדיני נפשות מן הצד, לקטנים שבהן שואלין תחלה, שיאמרו את דעתם. לפי דברי רבותינו כך פתרון המקרא לא תהיה אחרי רבים לרעות לחייב מיתה בשביל דין אחד, שירבו המחיבין על המזכין ולא תענה על הרב לנטות מדבריו, ולפי שהוא חסר יו''ד דרשו בו כן. אחרי רבים להטת ויש רבים שאתה נוטה אחריהם, ואימתי, בזמן שהן שנים המכריעין במחיבין יותר מן המזכין, וממשמע שנאמר לא תהיה אחרי רבים לרעות שומע אני אבל היה עמהם לטובה, מכאן אמרו דיני נפשות מטין על פי אחד לזכות ועל פי שנים לחובה. ואונקלוס תרגם לא תתמנע מלאלפא מה דבעינך על דינא, ולשון העברי, לפי התרגום, כך הוא נדרש לא תענה על ריב לנטת אם ישאלך דבר למשפט, לא תענה לנטות לצד אחד ולסלק עצמך מן הריב, אלא הוי דן אותו לאמתו. ואני אומר לישבו על אפניו כפשוטו, כך פתרונו: **לא תהיה אחרי רבים לרעת.** אם ראית רשעים מטין משפט, לא תאמר הואיל ורבים הם, הנני נוטה אחריהם: **ולא תענה על רב לנטת** וגו' **.** ואם ישאל הנדון על אותו המשפט אל תעננו על הריב דבר הנוטה אחרי אותן רבים להטות את המשפט מאמתו אלא אמור את המשפט כאשר הוא, וקלר יהא תלוי בצואר הרבים:
@70 **לא תהדר.** לא תחלוק לו כבוד לזכותו בדין ולומר דל הוא, אזכנו ואכבדנו:
@72 **כי תראה חמור שנאך** וגו' **.** הרי כי משמש בלשון דלמא, שהוא מארבע לשונות של שמושי כי וכה פתרונו שמא תראה חמורו רובץ תחת משאו: **וחדלת מעזב לו.** בתמיהה: **עזב תעזב עמו.** עזיבה זו לשון עזרה, וכן (דברים לב לו) עצור ועזוב, וכן (נחמיה ג ח) ויעזבו ירושל ם עד החומה, מלאוה עפר לעזוב ולסיע את חוזק החומה. כיוצא בו (דברים ז יז) כי תאמר בלבבך רבים הגוים האלה ממני וגו' , שמא תאמר כן, בתמיהה, לא תירא מהם. ומדרשו, כך דרשו רבותינו כי תראה וחדלת פעמים שאתה חדל ופעמים שאתה עוזר. הא כיצד, זקן ואינו לפי כבודו, וחדלת, או בהמת נכרי ומשאוי ישראל, וחדלת: **עזב תעזב עמו.** לפרק המשא. מלמשקל ליה, מלטול משאוי ממנו:
@73 **אבינך.** לשון אובה, שהוא מדולדל ותאב לכל טובה:
@74 **ונקי וצדיק אל תהרג.** מנין ליוצא מבית דין חיב ואמר אחד יש לי ללמד עליו זכות, שמחזירין אותו, תלמוד לומר ונקי אל תהרג וזה אף על פי שאינו צדיק, שלא נצטדק בבית דין, מכל מקום נקי הוא מדין מיתה, שהרי יש לך לזכותו. ומנין ליוצא מבית דין זכאי ואמר אחד יש לי ללמד עליו חובה, שאין מחזירין אותו לבית דין לחיבו תלמוד לומר וצדיק אל תהרוג, וזה צדיק הוא, שנצטדק בבית דין: **כי לא אצדיק רשע.** אין עליך להחזירו, כי אני לא אצדיקנו בדיני, אם יצא מידך זכאי, יש לי שלוחים הרבה להמיתו במיתה שנתחייב בה:
@75 **ושחד לא תקח.** אפלו לשפוט אמת, וכל שכן כדי להטות הדין, שהרי כדי להטות את הדין נאמר כבר לעיל לא תטה משפט: **יעור פקחים.** אפלו חכם בתורה ונוטל שחד, סוף שתטרף דעתו עליו, וישתכח תלמודו, ויכהה מאור עיניו: **ויסלף.** כתרגומו ומקלקל: **דברי צדיקים.** דברים המצדקים, משפטי אמת, וכן תרגומו פתגמין תריצין. ישרים:
@76 **וגר לא תלחץ.** בהרבה מקומות הזהירה תורה על הגר מפני שסורו רע: **את נפש הגר.** כמה קשה לו כשלוחצים אותו:
@77 **ואספת את תבואתה.** לשון הכנסה לבית, כמו (דברים כב ב) ואספתו אל תוך ביתך:
@78 **תשמטנה.** מעבודה: **ונטשתה.** מאכילה אחר זמן הבעור. דבר אחר תשמטנה מעבודה גמורה, כגון חרישה וזריעה. ונטשתה מלזבל ומלקשקש: **ויתרם תאכל חית השדה.** להקיש מאכל אביון למאכל חיה מה חיה אוכלת בלא מעשר, אף אביונים אוכלים בלא מעשר, מכאן אמרו אין מעשר בשביעית: **כן תעשה לכרמך.** ותחלת המקרא בשדה הלבן, כמו שאמר למעלה המנו תזרע את ארצך:
@79 **וביום השביעי תשבת.** אף בשנה השביעית לא תעקר שבת בראשית ממקומה, שלא תאמר הואיל וכל השנה קרויה שבת, לא תנהג בה שבת בראשית: **למען ינוח שורך וחמרך.** תן לו ניח להתיר שיהא תולש ואוכל עשבים מן הקרקע. או אינו אלא יחבשנו בתוך הבית, אמרת אין זה ניח אלא צער: **בן אמתך.** בעבד הערל הכתוב מדבר: **והגר.** גר תושב:
@80 **ובכל אשר אמרתי אליכם תשמרו.** לעשות כל מצות עשה באזהרה, שכל שמירה שבתורה אזהרה היא במקום לאו: **לא תזכירו.** שלא יאמר לו שמור לי בצד עבודה זרה פלונית או תעמוד עמי ביום עבודה זרה פלונית. דבר אחר ובכל אשר אמרתי אליכם תשמרו ושם אלהים אחרים לא תזכירו ללמדך ששקולה עבודה זרה כנגד כל המצות כלן, והנזהר בה כשומר את כלן: **לא ישמע.** מן הגוי: **על פיך.** שלא תעשה שתפות עם נכרי וישבע לך בעבודה זרה שלו נמצאת שאתה גורם שיזכר על ידך:
@81 **רגלים.** פעמים וכן (במדבר כב כח) כי הכיתני זה שלש רגלים:
@82 **חדש האביב.** שהתבואה מתמלאת בו באביה. לשון אחר אביב, לשון אב, בכור וראשון לבשל פרות: **ולא יראו פני ריקם.** כשתבאו לראות פני ברגלים, הביאו לי עולות:
@83 **וחג הקציר.** הוא חג שבועות: **בכורי מעשיך.** שהוא זמן הבאת בכורים, ששתי הלחם הבאים בעצרת היו מתירין החדש למנחות ולהביא בכורים למקדש, שנאמר (במדבר כח כו) וביום הבכורים וגו' : **וחג האסיף.** הוא חג הסכות: **באספך את מעשיך.** שכל ימות החמה התבואה מתיבשת בשדות ובחג אוספים אותה אל הבית מפני הגשמים:
@84 **שלש פעמים** וגו' **.** לפי שהענין מדבר בשביעית הצרך לומר שלא יסתרסו רגלים ממקומן: **כל זכורך.** הזכרים שבך:
@85 **לא תזבח על חמץ** וגו' **.** לא תשחט את הפסח בארבעה עשר בניסן עד שתבער החמץ: **ולא ילין חלב חגי** וגו' **.** חוץ למזבח: **עד בקר.** יכול אף על המערכה יפסל בלינה, תלמוד לומר (ויקרא ו ב) על מוקדה על המזבח כל הלילה: **ולא ילין.** אין לינה אלא בעמוד השחר שנאמר עד בקר, אבל כל הלילה יכול להעלותו מן הרצפה למזבח:
@86 **ראשית בכורי אדמתך.** אף השביעית חיבת בבכורים, לכך נאמר אף כאן בכורי אדמתך. כיצד, אדם נכנס לתוך שדהו, וראה תאנה שבכרה, כורך עליה גמי לסימן ומקדישה. ואין בכורים אלא משבעת המינין האמורין במקרא (דברים ח ח) ארץ חטה ושעורה וגו' : **לא תבשל גדי.** אף עגל וכבש בכלל גדי, שאין גדי אלא לשון ולד רך, ממה שאתה מוצא בכמה מקומות בתורה שכתוב גדי, והוצרך לפרש אחריו עזים, כגון (בראשית לח יז) אנכי אשלח גדי עזים, (שם שם כ) את גדי העזים, (שם כז ט) שני גדיי עזים, ללמדך, שכל מקום שנאמר גדי סתם, אף עגל וכבש במשמע. ובשלושה מקומות נכתב בתורה אחד לאסור אכילה, ואחד לאסור הנאה, ואחד לאסור בשול:
@87 **הנה אנכי שלח מלאך.** כאן נתבשרו שעתידין לחטוא, ושכינה אומרת להם (שמות לג ג) כי לא אעלה בקרבך: **אשר הכנתי.** אשר זמנתי לתת לכם, זהו פשוטו ומדרשו אל המקום אשר הכינותי כבר מקומי נכר כנגדו, וזה אחד מן המקראות שאומרים, שבית המקדש של מעלה מכון כנגד בית המקדש של מטה:
@88 **אל תמר בו.** לשון המראה, כמו (יהושע א יח) אשר ימרה את פיך: **כי לא ישא לפשעכם.** אינו מלמד בכך, שהוא מן הכת שאין חוטאין, ועוד שהוא שליח ואינו עושה אלא שליחותו: **כי שמי בקרבו.** מחבר לראש המקרא, השמר מפניו כי שמי משתף בו, ורבותינו אמרו זה מטטרו''ן ששמו כשם רבו. מטטרו''ן בגימטריא שדי:
@89 **וצרתי.** כתרגומו ואעיק:
@91 **הרס תהרסם.** לאותם אלהות: **מצבותיהם.** אבנים שהם מציבין להשתחוות להם:
@93 **לא תהיה משכלה.** אם תעשה רצוני: **משכלה.** מפלת נפלים או קוברת את בניה, קרויה משכלה:
@94 **והמתי.** כמו והממתי ותרגומו ואשגש. וכן כל תבה שפעל שלה בכפל האות האחרונה, כשתהפוך לדבר בלשון פעלתי, יש מקומות שנוטל אות הכפולה ומדגיש את האות ונוקדו במלאפום, כגון והמותי, מגזרת (ישעיה כח כח) והמם גלגל עגלתו, (קהלת ב כ) וסבותי, מגזרת (שמו''א ז טז) וסבב בית אל, (תהלים קטז ו) דלותי, מגזרת (ישעיה יט ו) דללו וחרבו, (שם מט טז) על כפים חקותיך, מגזרת (שופטים ה טו) חקקי לב, (שמו''א יב ג) את מי רצותי, מגזרת (איוב כ יט) רצץ עזב דלים. והמתרגם והמותי ואקטל, טועה הוא, שאלו מגזרת מיתה היה, אין ה''א שלה בפת''ח, ולא מ''ם שלו מדגשת, ולא נקודה מלאפום, אלא והמתי, כגון (במד' יד טו) והמתה את העם הזה, והתי''ו מדגשת, לפי שתבא במקום ב' תוי''ן, האחת נשרשת, לפי שאין מיתה בלא ת''ו, והאחרת משמשת, כמו אמרתי, חטאתי, עשיתי, וכן ונתתי, הת''ו מדגשת, שהיא באה במקום שתים, לפי שהיה צריך שלש תוי''ן, שתים ליסוד, כמו (יהושע י יב) ביום תת ה', (קהלת ג יג) מתת אלהים היא, והשלישית לשמוש: **ערף.** שינוסו מפניך ויהפכו לך ערפם:
@95 **הצרעה.** מן שרץ העוף, והיתה מכה אותם בעיניהם ומטילה בהם ארס והם מתים, והצרעה לא עברה את הירדן, והחתי והכנעני הם ארץ סיחון ועוג, לפיכך מכל שבע אמות לא מנה כאן אלא אלו. וחוי אף על פי שהוא מעבר הירדן והלאה, שנו רבותינו במסכת סוטה (סוטה לו א) על שפת הירדן עמדה וזרקה בהם מרה:
@96 **שממה.** ריקנית מבני אדם, לפי שאתם מעט ואין בכם כדי למלאות אותה: **ורבה עליך.** ותרבה עליך:
@97 **עד אשר תפרה.** תרבה, לשון פרי, כמו פרו ורבו:
@98 **ושתי.** לשון השתה, והת''ו מדגשת מפני שבאה תחת שתים, שאין שיתה בלא ת''ו, והאחת לשמוש: **עד הנהר.** פרת: **וגרשתמו.** ותגרשם:
@100 **כי תעבד וגו' כי יהיה לך למקש.** הרי אלו כי משמשין במקום אשר, וכן בכמה מקומות, וזהו לשון אי, שהוא אחד מארבע לשונות שהכי משמש. וגם מצינו בהרבה מקומות אם משמש בלשון אשר, כמו (ויקרא ב יד) ואם תקריב מנחת בכורים, שהיא חובה:
@101 **ואל משה אמר עלה.** פרשה זו נאמרה קדם עשרת הדברות, ובארבעה בסיון נאמר לו עלה:
@102 **ונגש משה לבדו.** אל הערפל:
@103 **ויבא משה ויספר לעם.** בו ביום: **את כל דברי ה'.** מצות פרישה והגבלה: **ואת כל המשפטים.** שבע מצות שנצטוו בני נח. ושבת וכבוד אב ואם ופרה אדמה ודינין שנתנו להם במרה:
@104 **ויכתב משה.** מבראשית ועד מתן תורה, וכתב מצות שנצטוו במרה: **וישכם בבקר.** בחמשה בסיון:
@105 **את נערי.** הבכורות:
@106 **ויקח משה חצי הדם.** מי חלקו, מלאך בא וחלקו: **באגנות.** שני אגנות אחד לחצי דם עולה ואחד לחצי דם שלמים להזות אותם על העם. ומכאן למדו רבותינו שנכנסו אבותינו לברית במילה וטבילה והרצאת דמים שאין הזאה בלא טבילה:
@107 **ספר הברית.** מבראשית ועד מתן תורה ומצות שנצטוו במרה:
@108 **ויזרק.** ענין הזאה, ותרגומו וזרק על מדבחא לכפרא על עמא:
@110 **ויראו את אלהי ישראל.** נסתכלו והציצו ונתחייבו מיתה, אלא שלא רצה הקדוש ברוך הוא לערבב שמחת התורה, והמתין לנדב ואביהוא עד יום חנכת המשכן, ולזקנים עד, (במדבר יא א) ויהי העם כמתאוננים וגו' ותבער בם אש ה' ותאכל בקצה המחנה, בקצינים שבמחנה: **כמעשה לבנת הספיר.** היא היתה לפניו בשעת השעבוד לזכור צרתן של ישראל, שהיו משעבדים במעשה לבנים: **וכעצם השמים לטהר.** משנגאלו היה אור וחדוה לפניו: **וכעצם.** כתרגומו, לשון מראה: **לטהר.** לשון ברור וצלול:
@111 **ואל אצילי.** הם נדב ואביהוא והזקנים: **לא שלח ידו.** מכלל שהיו ראוים להשתלח בהם יד: **ויחזו את האלהים.** היו מסתכלין בו בלב גס מתוך אכילה ושתיה, כך מדרש תנחומא. ואונקלוס לא תרגם כן. אצילי לשון גדולים, כמו (ישעיה מא ט) ומאציליה קראתיך, (במדבר יא כה) ויאצל מן הרוח, (יחזקאל מא ח) שש אמות אצילה:
@112 **ויאמר ה' אל משה.** לאחר מתן תורה: **עלה אלי ההרה והיה שם.** ארבעים יום: **את לחת האבן והתורה והמצוה אשר כתבתי להורתם.** כל שש מאות ושלש עשרה מצות בכלל עשרת הדברות הן, ורבנו סעדיה פרש באזהרות שיסד לכל דבור ודבור מצוות התלויות בו:
@113 **ויקם משה ויהושע משרתו.** לא ידעתי מה טיבו של יהושע כאן. ואומר אני, שהיה התלמיד מלוה לרב עד מקום הגבלת תחומי ההר, שאינו רשאי לילך משם והלאה, ומשם ויעל משה לבדו אל הר האלהים, ויהושע נטה שם אהלו ונתעכב שם כל ארבעים יום, שכן מצינו, כשירד משה (לקמן לב יז) וישמע יהושע את קול העם ברעה, למדנו שלא היה יהושע עמהם:
@114 **ואל הזקנים אמר.** בצאתו מן המחנה: **שבו לנו בזה.** והתעכבו כאן עם שאר העם במחנה להיות נכונים לשפוט לכל איש ריבו: **חור.** בנה של מרים היה, ואביו כלב בן יפנה, שנאמר ויקח לו כלב את אפרת ותלד לו את חור (דברי הימים א' ב יט) . אפרת זו מרים, כדאיתא בסוטה (יא ב) : **מי בעל דברים.** מי שיש לו דין:
@116 **ויכסהו הענן.** רבותינו חולקין בדבר. יש מהם אומרים אלו ששה ימים שמראש חדש עד עצרת יום מתן תורה: **ויכסהו הענן.** להר: **ויקרא אל משה ביום השביעי.** לומר עשרת הדברות, ומשה וכל בני ישראל עומדים, אלא שחלק הכתוב כבוד למשה, ויש אומרים ויכסהו הענן למשה ששה ימים לאחר עשרת הדברות, והם היו בתחלת ארבעים יום שעלה משה לקבל הלוחות, ולמדך, שכל הנכנס למחנה שכינה טעון פרישה ששה ימים:
@118 **בתוך הענן.** ענן זה כמין עשן הוא, ועשה לו הקדוש ברוך הוא למשה שביל [ נ''א : חפה] בתוכו:

@1 **ואלה המשפטים**. צריך לדעת טעם אומרו **ואלה** והנה נחלקו במכילתא רבי ישמעאל ורבי עקיבא רבי ישמעאל אומר לומר לך מה עליונים מסיני אף תחתונים מסיני רבי עקיבא אומר ואלה יכול שונין ולא יודעים תלמוד לומר ואלה וגו' ערכן לפניהם כשולחן הערוך עד כאן. והנה לרבי ישמעאל שמפרש ואלה שבא לומר שנאמרו בסיני בהכרח לפרש שטעם שהוצרך הכתוב להודיע זה הוא ללמד על פרטי מצוה זו שנאמרו מסיני, שאם על כללותיה הרי אמר רבי ישמעאל בפרק בתרא דזבחים (קט''ו:) שכל המצות נאמרו כללותיהם בסיני ופרטיהם באוהל מועד עד כאן, ואם כן גם אלה המשפטים בכלל ולא היה צריך לומר ואלה ללמד על דבר זה. ולרבי עקיבא שחלק עם ר' ישמעאל שם בבריתא השנויה בזבחים כי כל המצות נאמרו כללותיהם ופרטיהן בסיני אינו יכול לפרש ואלה המשפטים שבא ללמד שנאמרו בסיני כי אינו צריך להשמיענו זה והוצרך לפרש באופן אחר. וצריך עיון לדברי רש''י שפירש כאן כסברת רבי ישמעאל ובפרשת בהר סיני פירש כרבי עקיבא שאמר מה שמיטה נאמרו כללותיה ופרטותיה בסיני אף כל התורה כולה וכו', והם ב' פירושים חלוקים, והיה לו לפרש כאן ואלה המשפטים מוסיף על ענין ראשון מה שצוה בענין שני שצריך לשום לפניהם כשלחן הערוך בין משפטים תחתונים בין משפטים שקדמו להם:
@1 **ומה** שראיתי שכתב הרא''ם שלימוד רבי ישמעאל הוא שנאמרו המשפטים בקולות וברקים, אין דבריו נראים ולא מתקבלים לומר כי דיבר ה' יותר מעשרת הדברות הגם שהיה ר' ישמעאל אומר בפירוש כן היה צריך כח וראיה לדבריו ומכל שכן שלא אמר רבי ישמעאל אלא מה עליונים מסיני ולא אמר מה עליונים בקולות וברקים, ודברים אלו אין לשמוע להם, ואם מחמת הקושיא שהקשינו, כבר ישבנו אותה ישוב נכון שבא הכתוב על הדקדוקים כמו שבא בדין השמיטה שאמר הכתוב בהר סיני, ובהכרח לר' ישמעאל שיודה בשמיטה שנאמרו כללותיה ופרטיה בסיני כמבואר בתורה בפירוש, אלא שלא סבר ללמוד ממנה לכל התורה כולה, ואולי כי טעמו ממה שבאה הזכרת הר סיני בד' מצות לא רצה ללמוד מהם על כל התורה, והעיקר כמו שכתבנו. ויותר נכון להניח הדבר בצריך עיון לדברי רש''י מלפרש בו כי הבין בדברי רבי ישמעאל שאמר ה' אלה המשפטים כדרך שאמר עשרת הדברים, ואם כונת הרב רא''ם לומר שנאמרו בקולות לבד ולא כסדר עשרת הדברות, גם זה אינו כי זה יהיה בנין ג' בסדר הדבור, הא' הוא סדר אשר דיבר ה' בו עשרת הדברות, ב' סדר שהיה רגיל לדבר עמו כל המ' יום כל מצות התורה, ג' סדר דבור אלה המשפטים, ומי יטה אזנו לשמוע דברים אלו לבנות מציאות שלא מצינו לו כיוצא בו בתורה, ועוד יש להקשות אלא שהדברים פשוטים. עוד נראה לומר כי טעם אומרו **ואלה** לרמוז דבריהם ז''ל (סנהדרין פ''ו:) כי צריך לשום דיינים לפני המקדש, לזה אמר **ואלה** מוסיף על ענין ראשון שהזכיר בסמוך מקום שכונת הקודש שכולם במקום אחד:
@1 **אשר תשים לפניהם**. טעם אומרו בלשון זה, הגם שרבותינו ז''ל דרשו דרשות (שם ז') צריך לדעת פשטן של דברים. ואולי כי להיות שיש חלקים בתורה שהם חובת גברא לדעת את אשר יעבודו וזולת זה אינם בני ברית התורה, המשל בזה אם לא ידע שאסור לאכול טריפה הרי הוא אוכלה וכן הדם וחלב, ובמצות עשה פסח מצה ומרור שביתת ימים המקודשים הן אלה יתחייב לדעתם, ויש בחינה אחרת כמו שתאמר דיני טוען ונטען הלכות קידוש החודש הלכות קרבנות וכדומה, האמת כי חובת ידיעת התורה לכל איש ישראל אבל לא יגרע מצדיק עינו אם יחסר ידיעתם כל שיש בישראל גדולים שישפטו ויקדשו ויורו משפטים לישראל, ונתחכם ה' לומר כאן **אשר תשים לפניהם** לומר כי דינים אלו יתחייבו בשמיעתם כל איש ישראל שזולת זה אין הקונה מכיר בשעת הקנין לדעת את אשר יקנה, וגם אין הנקנה יודע כי ה' שחררו אחר שש שנים לתבוע התובע, וגם השופטים לא ידעו כל קונה עבד להודיעו כי חייב לשלחו, ולזה אמר **אשר תשים לפניהם** כי משפט זה הוא מהמשפטים אשר צריכין לשום לפני כולם, ולזה תמצא שדבר הכתוב בדרך נוכח **כי תקנה** וגו' כי יודיע הדבר לכל קונה:
@1 **עוד** ירצה להסביר המצות שתתקבל לכל, ולזה אמר **אשר תשים לפניהם** פירוש הגם כי דבר זה יש בו חסרון הרצון שהקונה עבדו ימהר לשלחו אחר ו' שנים תשים הדברים לפניהם כי מצוה זו לזכות כל אחד מהם היא כשיהיה עבד לא יעבוד בו לעולם ובזה יתרצה בדבר, כי כל אחד יעריך הדבר שהוא לזכותו לצד כי כל עברי הנמכר אינו אלא לצד דוחקו או גנב ומכרוהו בית דין וזה יסובבו העוני ובאותו מצב כולם עשירים היו ואין זה אלא לדבר המתגלגל וכל אחד ישים לפניו שאליו נוגע החסד דלמא יתגלגל עליו הגלגל וזה זכות הוא לו:
@2 **כי תקנה עבד עברי**. אולי שיכוין לומר שאם יהיה לפניו לקנות עבד כנעני ועבד עברי יקדים העברי, וזה שיעור הכתוב כי תרצה לקנות עבד תקדים לקנות עברי ולא תאמר אקנה עבד שאעבוד בו עד עולם ולא אקנה עבד שאחר שש שנים אשלחנו. וטעם שקראו **עברי** כי חש הכתוב ליחס שם עבדות על ישראל, לזה כינה אותו בשם זה. עוד רמז כי שם עבדות על ישראל הוא עובר ואינו קבוע מטעם כי לה' הם עבדים ויצא מתחת ידו בשנה הז'. עוד ירמוז שלא בא לידי מדה זו עד שעבר על התורה ומצות, ומכוון לדבריהם ז''ל (קידושין י''ד:) כי במכרוהו בית דין בגניבתו הכתוב מדבר, וגם במוכר עצמו מחמת דוחקו שמצינו שאמר הכתוב (דברים טו יב) כי ימכר לך אחיך העברי, גם הוא לא בא לידי זו עד שכבר קדמו לו עבירות, וכמאמר ר' אמי (שבת נ''ה.) אין יסורין בלא עון. עוד דקדק לומר **כי תקנה עבד עברי** ולא אמר עברי עבד, לרמוז כי קודם שתקנהו עבד הוא, וכאומרם ז''ל (קידושין שם) כי במוכרים אותו בית דין הכתוב מדבר וכבר נתחייב מהשמים. ובזה לא קשיא למה הוצרך לומר תיבת עבד שמזה יצא לנו לטעות עבד של עברי (מכילתא) עד שהוצרך לפרש פסוק אחר תלמוד לומר כי ימכר לך אחיך העברי:
@2 **עוד** נראה כי טעם שהוצרך לומר עבד לתת טעם למה שצוה שש שנים לזה הקדים לומר כי זה שאתה קונה כבר הוא עבד על דרך שאמר (ויקרא כה נה) כי לי בני ישראל עבדים:
@2 **שש שנים יעבוד**. טעם אומר כן לדרוש שעל כל פנים יעבוד שש ואפילו ברח, ואומרו **יעבוד** ולא פירש יעבדך נתכוון לרבות שיעבוד גם במות הקונה לבנו:
@2 **ובשביעית וגו'**. פירוש ולפעמים יעבוד גם בשביעית כשימכר באמצע שנת עולם לתשלום שנה שנמכר בה כדי שיהיו שש שנים שלמים מיום ליום. עוד ירצה כי יעבוד גם בשביעית פירוש שביעית לשנים אם תפגע בתוך שש שניו. שוב מצאתי דיוק זה בדברי רמב''ם בפירוש המשנה (קידושין פ''א מ''ב):
@3 **אם בגפו יבא וגו'**. רבותינו ז''ל בקידושין (כ'.) אמרו יחידי נכנם יחידי יצא מכאן שאין רבו רשאי למסור לו שפחה כנענית אלא אם הוא נשוי. ונראה כי הוקשה להם יתור הכתוב למה הוצרך לומר כן ממה נפשך אם לומר כי דווקא כשיכנס בגפו הוא שיצא בגפו אבל כשיכנס עם אשתו לא יצא בגפו פשיטא כי מי הכניסה שצריך לומר כן, ותמצא שדקדקו רבותינו ז''ל (קידושין כ''ב.) במאמר ויצאה אשתו כי לא היה צריך לאומרה ופירשוה לחייב מזון אשתו ובניו, ואם על שפחה הנותן לו רבו איגו צריך הרי הוא אומר בסמוך האשה וילדיה תהיה לאדוניה והוא יצא בגפו, אלא ודאי לדרשה בא לומר אם בגפו פירוש בלא אשה ישראלית ממה שגילה בסוף דבריו אם בעל אשה וגו', **בגפו יצא** פירוש יחידי יצא פירוש ישאר בכמות שהוא יחידי עד יציאתו. או על זה הדרך מקיש יציאה להכנסה כשם שכשנכנס נכנס יחידי ממש בלא אשה ובנים בין היוצאים עמו בין הנשארים בבית האדון כמו כן ביציאתו. ואם היתה לו אשה ולא היו לו בנים גם כן אין רבו מוסר לו שפחה שאנו קוראים בו בגפו, ואין צריך לומר היו לו בנים ולא היתה לו אשה:
@3 **וראיתי** להרא''ם שדייק שהיה לו לומר אם בגפו וגו' כן יצא. ואין דבריו נראים כי אדרבה אם היה אומר כן יהיה נשמע יותר שלא יתן לו שפחה וישאר כמות שהוא. והאמת כי טעם שלא אמר כן כי יש לחוש לדרשות אחרים הנשמעים ממנה והמשכיל יבין. ואם תאמר מנין להם לרבותינו ז''ל (שם כ'.) שהוסיפו הבנים, והגם כי דברים אלו הלכה הם, יש לומר כי אם יכנס באשה בלא בנים הרי אני קורא עליו בגפו יצא שלא יתן לו שפחה ויהיו לו בנים ממנה שאז אינו דומה גפו של יציאה לגפו של הכנסה כי אז לא היו לו בנים ועתה יש לו בנים. ואם בשעה שנכנס היתה לו אשה ולא בנים ואחר כך היו לו בנים נכנס בגדר היתר. ואולי כי לזה תלתה התורה הדבר באשה שהיא צריכה להיות בשעת ביאתו לעבדות אבל הבנים הגם שיהיו אחר כך. ואם היתה לו אשה כשקנאו ומתה משמע שמותר כי לא הקפיד הכתוב אלא על שעת ביאה בגפו יבא. וזולת דבריהם ז''ל הייתי אומר כי הכתוב שלל דין זה מאומרו אם בעל אשה הוא צריך שתהיה אשתו עמו עד שעת יציאה ובזה אני מתיר לך אם אדוניו יתן לו אשה:
@3 **אם בעל אשה וגו'**. פירוש על דרך אומרם ז''ל (מכילתא אחריתי דר''ש) שאין האדון חייב במזונות אשתו של עבד אלא אם תהיה אשה הראויה לו לעמוד עמו ולא אשה האסורה לו מאיסורי לאוין, והנה בדין מסירת שפחה כנענית משמע מהש''ס והובא בדברי רמב''ם (הל' עבדים פ''ג ה''ד) שכל שיש לו אשה ובנים ואפילו האשה מאיסורי לאוין יכול ליתן לו וכו', והוא אומרו **אם בעל אשה הוא** פירוש אין צריך שתהיה אשתו הראויה לו לגבי מה שאסרתי לך בסמוך אם בגפו שאין רבו מוסר לו אבל לגבי מזונות **ויצאה אשתו** פירוש הראויה לו הוא שחייב האדון במזונותיה:
@3 **עוד** יתבאר על דרך אומרם ז''ל (מכילתא) וזה לשונם יכול יהיה חייב במזונות ארוסה ושומרת יבם תלמוד לומר אשתו להוציא שומרת יבם, עמו להוציא ארוסתו. והנה עבד שהיתה לו אשה שומרת יבם או ארוסה מותר לתת לו שפחה כנענית, והוא אומרו **אם בעל אשה הוא** פירוש בלא תנאי הגם שתהיה ארוסה או שומרת יבם יצא מכלל בגפו שאסרתי לך נתינת שפחה. ולדברי הש''ס (קידושין כ'.) שדקדקו הבנים גם כן יהיה הדין בהיכא שהיו לו בנים מאשה אחרת ומתה וארם אשה ישנו במסירת שפחה:
@3 **ויצאה**. אומרו בתוספת וא''ו כי לצד שיצו ה' על מזונות האשה יוצדק לומר וא''ו כי מלבד שחייב במזונותיו גם כו':
@4 **אם אדוניו וגו'**. קשה למה התחיל לדבר לנוכח כי תקנה ותוך כדי דבור חזר לדבר דרך נסתר אם אדוניו יתן לו, תהיה לאדוניה, והגישו אדוניו, כל הפרשה בדרך נסתר ומן הראוי היה לו להשלים הדבור כדרך שהתחיל אם תתן לו, תהיה לך וגו', והגשת אותו. והיה נראה לומר כי לא כינה הזווג לקונהו על דרך אומרם ז''ל (ב''ר פס''ח) כי הקב''ה מזווג זיווגים לזה אמר **אם אדוניו** האמיתי כי לו בני ישראל עבדים יתן לו אשה, אלא שלא יצדיק פירוש זה אומרו האשה וילדיה תהיה לאדוניה. עוד צריך לדעת למה הוצרך לומר **והוא יצא בגפו** והלא הדבר מובן שיצא בגפו מאומרו האשה וילדיה תהיה לאדוניה. עוד צריך לדעת למה כפל לומר **אמר יאמר**:
@4 **אכן** כוונת הכתובים הוא לצד כי יצו האל השתנות הדין אם בגפו יבא בגפו יצא פירוש שאין רבו יכול למסור לו שפחה כנענית אלא אם היה נשוי כאומרם בקידושין (כ'.) ויאמר האומר מדוע חקק ה' חוקה זו להשתנות הדין מה לי היה נשוי או לא, לזה בא הכתוב בחכמה לתת טעם ואמר הטעם הוא **אם אדוניו יתן לו אשה** שהיא שפחה כנענית כמובן מהענין המשפט הוא שהאשה וילדיה תהיה לאדוניה והוא העבד יצא בגפו פירוש בלא אשה כל עיקר ולהיות כן אם יתן לו רבו אשה והוא פנוי מעולם לא ירצה לצאת מעבדות לצד ב' סיבות, האחד אהבת אשתו ובניו, והב' שבצאתו נשאר פנוי ושתים רעות יש לו ביציאתו ולצד זה כל עבד איש לא יחפוץ לצאת מאת רבו מה שאין רצונו יתברך כן, אשר על כן גזר אומר שלא יתן לו רבו אשה אלא אם הוא נשוי כי בזה יקל מעליו הפרדת אשתו ובניו כיון שיש לו אשה ישראלית בת חורין יהיה בעיניו קל לצאת, וכפי פסוק אם אדוניו וגו' נתכוון ה' לומר בסדר הדברים לתת טעם במתק לשון למה שינה הדין, ואומרו **ואם אמר יאמר** פירוש מלבד אמירה א' שעשה ה' לו תיקון כנזכר עוד יאמר **אהבתי** וגו' **והגישו** וגו' **ורצע** וגו' כי זה מעיד שאינו חושש לעולו ית' וקונה אדון לעצמו:
@4 **עוד** נראה לפרש הפרשה דרך רמז כי תצוה התורה להאדם לשום לפניו בתמידות כל הדברים האלה בין עיניו והוא אומרו **אשר תשים לפניהם** שתמיד ישים האדם ענין זה לפניו. והוא **כי תקנה עבד עברי** הלא ידעת כי האדם נחלק לשנים חלק אחד רוחני והוא העיקר וחלק אחד גשמי שברא ה' לנשמה לשמשה שבאמצעותו מקיים כמה מצות אשר צוה ה' ולו יקרא שם עבד כי אינו אלא שמש לנפש שבשבילה יקרא אדם כמו שאמר הכתוב (לקמן ל') על בשר אדם לא וגו' שזה יגיד כי לא הבשר יקרא אדם, וכן אמר (יחזקאל ל''ד) אדם אתם אתם קרויים אדם ולא אומות העולם (ב''מ קי''ד.) שאין להם נפש רוחנית, ולזה תצוה התורה להאדם **כי תקנה עבד עברי** פירוש עברי עובר כי אינו קיים לעד כי מי גבר יחיה ולא יראה מות על דרך (תהלים קמד) כצל עובר, וזמן קביעתו הוא עד ס' שנה על דרך אומרו (איוב ה') תבא בכלח אלי קבר, ואמרו בש''ם (מוע''ק כ''ח.) כי בן ס' שנה הוא זמנו של אדם ללכת כחושבן בכלח שאז הוא כעלות גדיש, וזה הוא אומרו **שש שנים** פירוש כל ימיו הם ששים, והגם שאמר שש יש חשבון שיכלול כללות א' וכאן כולל העשירי, **ובשביעית** פירוש בעשר שנים השביעית יצא לחפשי העבד על דרך אומרו (תהלים פ''ח) במתים חפשי, ואומרו תיבת **חנם** לרמוז על יד מי תהיה היציאה על ידי חנם שהוא ס''מ וחילותיו שהם נרמזים בתיבת חנם כאומרם בספר הזוהר הקדוש (ח''ב קכ''ח.) כי במילי דמגנא הוא זינייהו דההיא סטרא ולזה לא שלטי בדבר מצוה שעושה האדם בדמים יקרים, וכן תמצא שכל דבר טומאה בא בחנם מה שאין כן דבר מצוה וקדושה צריך להם טורח גדול ודמים יקרים:
@4 **ואומרו אם בגפו יבא** צריך לדקדק למה אמר לשון זה ולא אמר לשון הרגיל בלשון הקודש אם לבדו כאומרו (וישלח לב כה) ויותר יעקב לבדו:
@4 **אכן** יש לדעת כי אם סיגל מצות ומעשים טובים וקנה לעצמו כח ימצא כח לעלות ביום התחייה על דרך אומרו (תהילים עב) ויציצו מעיר כעשב הארץ (כתובות קי''א.) וזהו שאמר כאן **אם בגפו** פירוש לשון גף על דרך אומרו (משלי ט') על גפי מרומי שרומז אל המצות ומעשים טובים כאומרם ז''ל (שבת מ''ט.) נמשלו ישראל ליונה וכו', ואומרו **יבא** פירוש על דרך אומרו (אונקלוס בראשית כח כא) כי בא השמש עאל שמשא, **בגפו יצא** פירוש באותו כנף יצא מן הארץ בעת התחייה ואחרי נפלו קימה תהיה לו וידיעת ההפכי' שוה היא שאם בעולם הזה לא ישתדל בסגל הטוב אין כח בו לעלות, והוא מאמרם ז''ל (כתובות קי''א:) בפסוק (משלי ג) עץ חיים וגו' שאין גופות עמי הארץ עומדים זולת למחזיקים בה:
@4 **ואומרו אם בעל אשה הוא ויצאה אשתו עמו** כאן רמזה התורה סוד גדול והוא כי יש לך אדם שקנה נשמתו באמצעות חוזק מעשיו הטובים ונעשה הוא בעלה של נשמה הקדושה, וצריך אתה לדעת מה שאמרו בספר הזוהר (ח''ג צ''א,) במה שאמר הכתוב שור או כשב או עז כי יולד וגו' כי הבהמות מעת לידתם קונים שכל שיש לשור מה שאין כן האדם כפי מעשיו זכה נותנים לו נפש זכה יתיר וכו' זכה יתיר וכו' עד כאן, הנה שבאמצעות מעשיו קונה הנשמה הנקראת אשה וכמו כן מצינו שקראוה חכמי אמת (תקו''ז תיקון ו') ולזה אמר **אם בעל אשה** הוא שקנאה כנזכר **ויצאה אשתו** פירוש אפילו אחר יציאת אשתו אף על פי כן עודנה עמו ונשאר חי אפילו אחר מותו, וצא ולמד ממעשה שהובא במסכת שבת (קנ''ב:) של הנהו קפולאי וכו' נחר בהו גברא וכו' שהיה מדבר לאחר מותו, וזה הוא אומרם ז''ל (ברכות י''ח.) צדיקים במיתתן קרויים חיים:
@4 **עוד** יכוין באומרו **אם בעל אשה הוא** לומר אם הוא אדם אשר כל מחשבותיו ויגיעותיו וטרחו בעולם הזה ואפילו מאכלו ומשקהו אינו אלא בשביל הנשמה על דרך אומרו (משלי יג) צדיק אוכל לשובע נפשו להגדיל הרוחניות אדם כזה לו יקרא בעל אשה כבעל הזה שטורח בשביל אשתו לזון ולפרנם ולכלכל ולמלאות רצונה כן זה האיש עושה לנפשו אדם כזה שהחומר נזדכך ונעשה מעין הצורה במציאות זה תוכל נפשו לסבול לדור עמו במחיצתו אפילו אחר יציאתה:
@4 **ואומרו אם אדוניו יתן לו אשה** וגו'. פירוש אם אינו בעל אשה על אופן האמור אבל אשה הקנו לו מן השמים כי תמצא כמה בני אדם שזוכים לנשמה טהורה בסוד הזיווג בשעת יצירה מצד אביו הצדיק, וילדה לו בנים או בנות פירושו על דרך אומרם (ב''ר פ''ל) עיקר תולדותיהם של צדיקים וכו', גם כי על ידי מעשים טובים יהיה נולד מלאך טוב כאומרם ז''ל (אבות פ''ד) העושה מצוה אחת קנה לו פרקליט אחד כו', וכן הוא מפורש באר היטב בספר הזהר הקדוש לזה אמר וילדה לו בנים או בנות בחינת הבנים הם מצות הנעשים בהתעצמות גדול, ובחינת הבנות היא מדרגה למטה מבנים, אדם כזה האשה וילדיה תהיה לאדוניה לשלול מה שזכה האיש אשר קנה האשה באמצעות התעצמותו ונעשה בעל האשה להיות עמו תמיד לא כן הוא זה אלא תהיה לאדוניה כי אדם כזה לא קנאה להיות בעלה שבזה לא תפרד ממנו. גם לפירוש ב' זה לא זיכך גופו כדי שיהיה ראוי שלא תפרד ממנו הנשמה ולזה תהיה לאדוניה, והוא יצא וגו' פירוש ובעת יציאתו מהקבר בעת התחייה יצא בגפו פירוש זכיותיו שיש לו ולא תושלל ממנו התחיה בהעדר הדבר האמור:
@4 **ואומרו** ואם אמר יאמר העבד וגו'. כאן הודיע הכתוב עבודת העבד ישראל המתלהב לעבודת קונו ואף אחר שאפסו כוחותיו מתאוה תאוה לעבוד האדון, וזהו אומרו **אהבתי את אדוני את אשתי ואת בני** שהם הנשמה והמצות שעושה בעולם הזה ואינו רוצה לצאת מהעולם הזה לחפשי כמתים וזה יורה על החשק והתאוה בהאדון, לאיש כזה מבטיח האדון כי לו יקרא עבד ה' וימלא תאותו תאות לבו נתת לו אך לא עתה כי עתה אין לו עוד בעולם אלא **ועבדו לעולם** לעולם הבא יבחר בו ה' מהמלאכים להיות לו לעבד נאמן ומצינו שכן היה למשה שקראו ה' (דברים לד ה) עבד ה' שנתאוה לחיות ליכנס לארץ ישראל לעבוד ה' ולקיים מצותיו (סוטה י''ד.) ומה שאמר הכתוב **ורצע** וגו' **במרצע** תמצא בחשבון מרצע ד' מאות עולמות הכיסוף ככתוב בספר הזוהר (ח''א קכ''ג:) ואומרו **ועבדו לעולם** פירוש יחשוב עליו כאילו חי כל ימי עולם ועבד בה עבודת הקודש מחשבה טובה וכו'. עוד רמז **לעולם** סוד ידוע ליודעי דעת קדוש:
@7 **וכי ימכור**. הלביש הדבר במוכר ולא בקונה, לומר כי זו אין מציאות לקנותה אלא מאביה כי אינה נמכרת על ידי עצמה גם אין בית דין מוכרין אותה (מכילתא), ואומרו בתוס' וא''ו לומר כי מלבד רשות הנתונה לו לזכות בקדושיה שהיא נקנית בהם עוד זוכה הוא בה למכרה לאמה:
@7 **איש את בתו**. אמרו ז''ל (מכילתא סוטה כ''ג.) איש להוציא אשה שלא תמכור בתה. ואומרו תיבת **את** תתפרש על דרך אומרם ז''ל (מכילתא) האיש רשאי למכור עצמו ולא האשה. והוא אומרו **וכי ימכור איש** פירוש את עצמו ועוד בתו, ואם היה אומר כי ימכור איש בתו לא היה נשמע אלא מכר בתו ולא כנזכר:
@7 **לאמה**. יתבאר על דרך אומרם במס' קידושין (ד'.) שאפילו הבת איילונית יש לאביה רשות למוכרה. והוא אומרו **לאמה** פירוש הגם שאינה ראויה להנשא כל שראויה לאמה. או ירצה על דרך אומרם ז''ל (תוספתא דבכורים פ''ד) כי הטומטום והאנדרוגינוס לא ימכרו לא ממכרת עבד עברי ולא אמה העבריה. ולזה אמר **לאמה** פירוש אם היא ברורה אמה ולא טומטום ואנדרוגינוס:
@7 **לא תצא כצאת העבדים**. רבותינו ז''ל (קידושין ט''ז.) פירשו כיציאת עבד כנעני בשן ועין עד כאן. וטעמם כי לא יקרא הכתוב עבד סתם אלא לכנעני כי ישראל אין לו שם עבדות סתם. ופשט הכתוב נראה לי שהכוונה היא **לא תצא כצאת העבדים** שאינם יוצאים עד שיעבדו שש שנים ואם מת האב יעבדו לפני הבן אלא מת האדון הרי זו יוצאה לחרות אפילו לא שהתה שש:
@7 **או** יכוין לומר **לא תצא כצאת העבדים** האמורים בסמוך שבשנה הז' יצא אלא שם קנתה מקומה שישאנה האדון (שם י''ד:) ולא תצא אפילו אחר מאה שנה אלא במיתת האדון או בגט ולזה גמר אומר אם רעה וגו', וקשה עד שיזכיר הכתוב יעודיה ואז יוצדק לומר אם רעה אשר לא יעדה. ולדברינו יבא על נכון כי באומרו **לא תצא** שם רמז היעוד ועל זה אמר **אם רעה** וגו' גם לא חש לטעות ששלל זכיות אשר רשם ה' בעבדים שהם יציאת שנת שביעית ושנת היובל, כי ממה שגמר אומר אם רעה וגו' בזה הראה באצבע כי ליעודי הבעל אמר שקנתה מקומה. והוסיף להסיר הטעות במה שאמר הכתוב (דברים טו יב) אחיך העברי או העבריה הרי השוה האמה העבריה לעבד העברי ליתן את האמור בעברי בעבריה. ואין בפירוש זה הכחשה לדברי רבותינו לענין הלכה זולת בישוב הכתוב רשות נתונה לנו מהם למסבר קראי באופן שיהיה לבד מהכחשת ההלכות כי כולן מסיני באו להם, וכאן באה ההלכה כי דין שן ועין אינו אלא בכנעני ולא בישראל, והטעם נראה כי זכות יש לעבד עברי שלא יצא בשן ועין כי חייב לשלם לו אדונו דמי עינו ושינו ושאר הדברים ויעלה ביותר ומה גם כשיהיה הדבר אחר עבור שנים משש שנים של עבודתו ולפעמים יהיה הדבר בסוף, לזה קבע ה' שיטול עבד עברי דמי עינו מה שאין כן עבד כנעני שגופו קנוי לו עשה בו האדון מנהג הותרנות הידועה לבחינת הקדושה, והדברים עתיקין:
@8 **אשר לא יעדה וגו'**. טעם **לא** באל''ף וקרי בוא''ו, יתבאר על דרך אומרם ז''ל (קידושין י''ט.) שאין יעוד אלא לרצונה ודרשוה בקידושין מתיבת יעדה שצריך לרצונה, ולזה כנגד עיכוב הבא ממנו אמר **אם רעה בעיני אדוניה**, וכנגד עיכוב הבא מצדה אם לא תתרצה בדבר אמר **אשר לא יעדה** כי לא היה הדבר מדעתה, אחת מהנה מעכבת. ואומרו **והפדה** פירוש אז הוא שישנה בפדיון ומגרעת מפדיונה אבל זולת זה אם יעדה אין מציאות לצאת כנזכר:
@8 **לעם נכרי**. פירוש הגם שאמרתי לך כי יכול איש למכור בתו לא לעם נכרי יכול למכרה הגם שכבר עשה הדבר ובגד בה ומכרה אין ממכרו ממכר, והוא אומרו **לא ימשול** וגו' **בבגדו** וגו' ופקע זכות קונה ומקנה. עוד ירצה על דרך אומרם (שם י''ט:) שיש לאב למכור בתו לפסולים אלמנה לכהן גדול כו', והוא אומרו **לעם נכרי** פירוש לעם נכרי הוא שלא ימשול אבל איש נכרי לה והוא מעם שאינו נכרי רשאי:
@9 **ואם לבנו**. פירוש לא יעדה הוא ויחפוץ בה לבנו מודיע הכתוב כי יכול ליעדה, והוא אומר **ייעדנה** פירוש בכסף קנייתה בו יהיה יעודיה או לו או לבנו ואין צריך כסף קדושין, ואומרו **כמשפט הבנות** פירוש בין אם יעדה לו או לבנו צריך לעשות כמשפט הבנות שהוא מה שאמר בסמוך שארה וגו':
@11 **ואם שלש אלה**. הם שארה כסותה ועונתה, ולזה דקדק לומר **אלה** ולא הקודמים להם שהם יעוד וגו'. ואמר **ויצאה חנם** פי' פקע זכותם ממנה שאינם יכולים לכובשה עד זמן שש שנים או שאר סימנים אלא או יקיים ג' דברים או יוציאנה בגט, ולזה גמר אומר **אין כסף** לומר כסף הוא שאין אבל גט צריך כי ארוסתו היא. ורבותינו ז''ל (מכילתא) אמרו ג' אלה יעוד לו ולבנו וגרעון כסף ויצאה חנם בהבאת סימנים, ואלו מן ההלכות שנאמרו בהר סיני וסמכום:
@11 **ונראה** לפרש פרשה זו דרך רמז על פי דבריהם שאמרו (סוטה מ''ב:) אין איש סתם אלא הקדוש ברוך הוא דכתיב (לעיל ט''ו ג') ה' איש מלחמה, ואמרו עוד (שהש''ד פ''ג) לא זז ה' מחבב לכנסת ישראל עד שקראה בתו, ומצינו שכינה הכתוב ענין הגלות בשם מכירה דכתיב (ש''א י''ב) וימכור אותם ביד וגו', והנה לפי מה שקדם וצוה הכתוב על הקונה עבד עברי שלא יעבוד אלא שש שנים לזה קובל הכתוב בעד עם בני ישראל למה נשתנה דינו מדין העבדים היוצאים בשש, והוא אומרו **וכי ימכור איש את בתו לאמה** למה תגרע מדין העבדים אשר צוית שש שנים וגו', והוא אומרו **לא תצא כצאת העבדים** בשביעית. ולמה נמכרה בגלות המר הזה זה לנו אלף ותרע''ב ואנחנו לא נושענו ותן לנו משפט עבד עברי הרשום בכתב. וחזר הכתוב וטען **אם רעה** וגו' פירוש אם עודנה במדרגת רשע שבשבילו נמכרה דכתיב (ישעי' נ') הן בעונותיכם נמכרתם וגו', ואומרו **בעיני אדוניה אשר** וגו' פירוש כי הבת היקרה ישנה גם במדרגת כלה כמאמר ספר קודש הקדשים שיר השירים (ד' ח') והוא אומרו **אדוניה אשר לו יעדה** כי אותה יעד לכלה וכתיב באל''ף אשר לא יעדה פירוש הן עתה לא יעדה לצד מעשיה המכוערים, וטען הכתוב על זה **והפדה** פירוש כי לא יוכר לה בחינת הרע בעודה מכורה ובועליה אדונים זרים כי הם ימנעוה מעשות טוב ויכריחוה לעשות רעה בעיני אדוניה ואין תשובת היותה רעה בגלות תשובה עד שתהיה גאולה אז יוכר בה אם רעה אם לא, ומעתה אינו מן הדין שימכרנה לעם נכרי על אשר תהיה רעה בעיניו כל זמן שהוא בוגד בה פירוש כל זמן מכירתה אלא על אשר עשתה בימי שלותה כשלא היה עליה יד מושל נכרי:
@11 **ואומרו ואם לבנו** טען וחזר וטען כי מצינו שהקדוש ברוך הוא קרא לישראל בנים בהכרזה לעיני העמים כולם וידעו כי ישראל הם אומה המיועדת בשם בן לה' והן עתה אם עדיין אומה זו מיועדת לבחינת בנו מן הראוי היה לפחות שלא תהיה גרועה מהאומות כאשר עינינו רואות רום מעלות האומות וישובן מה שאין כן ישראל ומן הראוי לא תהיה גרועה מהם ודי לה השפלה זו שלא יהיה לישראל מדרגה גדולה מהם, והוא אומרו **כמשפט הבנות** כי גם הם יקראו בנות אלא שלא יתכנו במעלה זו ליקראות בתו של הקדוש ברוך הוא. ואומרו **אם אחרת** דע כי אמרו ז''ל (זהר ח''ב קנ''ב:) כי בזמן החורבן כל כלי השפע משפיעין חוץ למקומן בשאר האומות ולא בישראל כי מתקלקלים הצינורות ומריקים במקום לא קדוש. והוא אומרו **אם אחרת יקח לו** לתת מדת טובו כאשר עיני כל ישראל רואות הפלגת הטוב ביד לא מבני ישראל המה טען הכתוב עוד לו יהיה שכעס עוד עליה שלא תהיה בהדרגת הטוב וההשקט כבנות העולם ונותן ה' מדת טובו לאומה אחרת לפחות שארה כסותה ועונתה לא יגרע, שארה אלו מזונותיה כמאמר ר' יאשיה (מכילתא), כסותה כמשמעו, ועונתה היא שיהיה עונה אותה בצר, וג' דברים אלו הם דברים המוכרחים ואיך יכולה לחיות זולתם. ואמר עוד **ואם שלש אלה** פירוש שארה כסותה ועונתה לא יעשה לה ותהיה גרועה מהם.
@11 **ויצאה חנם** פירוש הגם שלא יהיה בידם לא תורה ולא מצות ואפילו לא יכספו לדבר הגאולה והוא אומרו **איז כסף**, כי יסוריה יספיקו לפדיונה:
@11 **או** תרמוז הפרשה על זה הדרך **וכי ימכור איש** זה הקדוש ברוך הוא **את בתו** אומה הקדושה, **לאמה** פירוש להיות שכבר עברו גליות על ישראל גלות מצרים גלות בבל כו' וכולם לא נשתעבדו ישראל אלא לאומה אחת ואין דבר זה סובב קריאת שם עבדות על ישראל, אבל בגלות החל שאנו בו עתה משתעבדים ישראל לכל ע' אומות בכל מקום אשר שם עברי בזוי הוא ושפל וכל אחד בוזז וחוזר ליקוטי בתר ליקוטי ודבר זה ינסה ויסמן בהם בנסיון גדול וסימן מובהק והוא אומרו **לאמה** כי אומתינו בגלות זה קנתה שם אמה ומעתה גם בבוא גאולתינו ופדיון נפשינו כבר קנתה האומה שם עבדות, לזה אמר הקדוש ברוך הוא הבטחה כי גאולת האומה הלז לא תהיה כדרך אשר הוציאנו ה' ממצרים מבית עבדים אלא בנסים מופלגים בפרסום בכל העולם, והוא אומרו **לא תצא כצאת העבדים** הרמוזים בתורה (לעיל כ' ב') מבית עבדים וגו' שאז לא הפליא ה' פלאיו אלא באומה אחת, ואז בכל העולם והיו מלכים אומניך ושרותיהם וגו' וישתחוו כל מלכי ארץ ככתוב בספר ישעיה (מ''ט.) ואומרו **אם רעה** וגו' יתבאר על פי מאמר הזוהר כי תשתנה גאולת ישראל אם תהיה באמצעות מעשיהם הטובים לאם תהיה לצד השלמת קץ הסתום, כי אם תהיה באמצעות הכנת ישראל יבא הגואל מלאך ה' בעמוד אש מוצב ארצה וראשו בשמימה, ואם לצד הקץ וישראל לא ראוים לו עליו נאמר (זכרי' ט') עני ורוכב על חמור, והוא אומרו כנגד ביאת הגואל לצד הקץ הגם שאין ישראל ראוים לו **אם רעה** וגו' פידוש אפילו אם תהיה רעה בעיני אדוניה כשיגיע הקץ אשר קצב ליעדה **ולא** באל''ף ירצה שאינה ראויה ליעודיו כי היא רעה אף על פי כן **והפדה** פירוש פדיון יושג לה על כל פנים אבל לא יהיה הדבר כדרך אם לא תהיה רעה בעת הגאולה. ואמר **לעם נכרי** וגו' פירוש כי לא לצמיתות יהיה המכר לעם נכרי הגם שיבגוד בה כמאמר הכתוב (איוב כ''ח) קץ שם לחושך. וכנגד ביאת הגאולה לצד מעשיהם הטובים והכשרתם אמר **ואם לבנו ייעדנה** על דרך אומרם (ב''ב י'.) כשישראל עושים רצונו של מקום נקראו בנים, הכוונה אם יעודים אשר ייעדנה ה' בעת הגאולה תהיה לצד היותם במדרגת בנים אז **כמשפט הבנות** דבר זה יגיד הפלגת שעשוע ישראל בבוא הגואל פירוש בנות הם נשמות המשתעשעים בגן עדן הנקראים בנות ירושלים ומשפט שקצב להם צרור המור דודי לי להגלות להם אורו יתברך וזה הוא מחייתם ושעשועם ותכלית מאויים אמר ה' כי כמשפט הזה יעשה להם בביאת הגואל בעודם בעולם הזה יגלה ה' אור שכינתו על כל הצדיקים ויאמרו כולם זה אלי וגו' בתמידות כמשפט הבנות:
@11 **ואומרו אם אחרת וגו'**. בא הכתוב להתנות אימתי חלקתי לך בין זמן שהיא רעה לזמן שהיא במדרגת בנו אלא בזמן שאם אחרת יקח לו על דרך שפירשנוה למעלה **שארה כסותה ועונתה** של הבת הישראלית **לא יגרע** בזה הוא שחלקתי אבל **אם שלש אלה** וגו' **ויצאה חנם** פירוש אפילו אינם צדיקים לכסוף אל יום פדות יצאו אפילו קודם זמן הגלות והרי הם יוצאים בזכות יסורין אשר קבלו במחסור ג' הדברים ושוים הם למדרגת בן:
@12 **מכה איש ומת**. פירוש אין צריך שתהיה המיתה בשעת ההכאה עצמה כמו שתאמר שישחטנו או ישרפנו או יחנקנו שמוציא נשמתו ממנו בידו ממש אלא אפילו מת אחר כך בכח ההכאה חייב אלא אם כן עמד מחוליו דכתיב (פסוק י''ט) אם יקום. וחידוש משמיענו מה שאין הדין כן בהורג בשוגג שאינו חייב לגלות אלא דוקא אם מת בידו כדתניא בפרק מי שאחזו (גטין ע'.) שחט בו שנים או רוב שנים הרי זה אינו גולה משום דחיישינן שמא הרוח בלבלתו או הוא פרכם וקירב מיתתו וכו' עד כאן, וכתבו התוספת כי דוקא בהורג בשוגג אנו דנים דין זה דבהכי תליא דכתיב ויפל עליו וימות (בדמבר לה כג) משמע ליה לאלתר אף על פי שבמזיד חייב אפילו לא מת לאלתר יש חילוק בין מיתה לגלות עד כאן, והם דברינו שדייקנו באומרו במזיד **מכה איש ומת** ולא אמר הורג איש וגו' לומר אפילו הרגו עתה ומת אחר כמה ימים ובשוגג דקדק לומר **אנה לידו** פירוש שהרגו בידו ממש, וכן משמע מדברי רמב''ם בפ''ה מהלכות רוצח, ולא כן דעת הראב''ד שאינו מחלק יעוין שם דבריהם, ואין דבריו נראים בשום אופן בעולם, ואין כאן מקום פלפול הפוסקים:
@12 **מות יומת**. טעם הכפל בדין זה ובדין מכה ומקלל יולדיו ובגניבת איש ובהכאת עבדו וכדומה. דע כי משפטי ה' הוא השופט כל העולם להמית לעושי רשעה אלא שבחר לתת קצת מהם לשופטי ארץ להמית הרשומים בתורת ה' לטעמים רבים מהם נגלו לנו מהתבוננות התורה וכהנה וכהנה ישפוט הוא האדון למעלה כבועל נדה ומחלל יום כפור וכאוכל חלב וכדומה הוא ישלח מלאכו לפגוע בו, ולזה אמר הכתוב **מות יומת** פירוש אותו שהוא בן מות יומת על ידכם כי בן מות הוא הגם שלא יומת מכם. ולזה אמרו ז''ל (כתובות ל'.) הגם שיבטלו הדיינים, דינם לא בטל וישפטהו השופט לעולם, ולזה בדין שור שנגח אדם והועד בבעליו אמר וגם בעליו יומת כי שם אין מיתה אלא בידי שמים ולא מסרו לבית דין כאומרם ז''ל (מכילתא) יומת בידי שמים. ורבותינו ז''ל (ב''מ ל''א:) אמרו עוד בזה דבר:
@13 **ואשר לא צדה והאלהים וגו'**. צריך לדעת למה כפל לא צדה והאלהים וגו'. ועוד קשה למה יאנה ה' לאדם און זה. ורבותינו ז''ל אמרו במכילתא ובהגולין (מכות י':) זה הוא שאמר הכתוב מרשעים יצא רשע וגו' הא כיצד היה יורד בסולם ונפל עליו והרגו וכו' הרי זה גולה היה עולה בסולם ונפל עליו והרגו הרי זה אינו גולה וכו' בא מזיד ונפל ביד שוגג עד כאן. וקשה הן אמת כי מזיד זה נטל שכרו מושלם כי בן מות הוא והרי הוא נהרג אלא שוגג זה שגולה גלות זה הוא על מה ששגג עתה בפעם הזאת ועל שגגתו אשר שגג בראשון אין לו פרעון עליה, ואם אשר הזמין לידו ה' לא יתחייב עליה כי ה' הזמינה לידו אם כן מוכרח לומר כי בפעם הזאת לא אנה ה' לידו והנהרג על ידו לא היה מחוייב מיתה שאם מחוייב הרי זה יכנס גם כן בגדר כי ה' אנה לידו, וזה דוחק, כי הכתוב יגיד ענין שגגת הריגת נפש בלא צדיה ולא חלק בקצת מהם. והנכון כי גם נהרג ראשון נתחייב מיתה והרגו זה במאמרו יתברך אשר אנה ליד זה ההורג בשוגג, והנה זה שנהרג נלכד בפשעו ונהרג על אשר הרג במזיד אבל היה ה' יכול להפיל עליו מפולת בלא אמצעות הורג בשוגג, אלא לצד שקדם אליו עון מזיד [שוגג] שאין עליו חיוב אלא גלות ואנה ה' לידו דבר זה, והנה אדם זה אינו גולה על ההריגה אלא על מה שקדם לה שסבב הריגה וכפי זה אפילו הרג עשרה אינו חייב אלא גלות אחת כי סבת הגלות אחת היא ואחר שישלם עונו לא יזמין ה' לידו רציחה אחרת. ותמצא שלא הגביל ה' שיעור הגלות לכל הרצחנים שיעור אחד. אלא כל אחד כפי שיעור חטא הקדום לו. וכפי זה טעם שאמר הש''ס שעון זה ההורג בשוגג הוא על אשר הרג בשוגג וכפי דברינו הוא חטא נעלם קדום להריגת הראשון, אולי שנקטו המצאה שוה בעונש שניהם שהוא על ההריגה, והמשכיל על דבר לבבו יבין יסודן של דברים:
@13 **או** אפשר כי לצד שרמזוהו מן השמים דהמתגלגל על ידו שהרג הנפש והיה לו להכנע ולקבל עליו הגלות מעצמו הרי זה הוסיף על חטאתו פשע, ולזה הזמין לו עוד שוגג אחר מלבד הראשון וצריך לגלות פי שנים כשיעור הצריך למספר רשעיותיו. ולזה תמצא שנתחכם ה' ולא גבל שיעור גלות הרוצח אלא עד מות הכהן הגדול ודבר זה הנה הוא מסור לאדון כל הארץ והוא ישפוט בצדק כמה שיעור הצריך לו אם לאחת אם לשתים. ולפי דרך זה יתיישב כוונת אומרו הענין אבל עדיין אין כדי ליישב אומרו **והאלהים** בתוספת ו':
@13 **ונראה** כי יכוין הכתוב לדקדק דין הגולה אופן שנתחייב בו על פי מה שכתב רמב''ם בפ''ו מהלכות רוצח שאין גולה אלא שוגג שאינו אונם פירוש שהמעשה הוא דבר הרגיל, גם שלא היה לו צד הזדה כל עיקר, אבל אם היה השוגג דבר שאינו מצוי, או שהיה בו צד הזדה כגון שונא שחזקתו למזיד וכדומה לו אינו גולה. וכנגד שניהם דקדק הכתוב לומר ב' דברים **ואשר** וגו' **והאלהים** וגו', כנגד שוגג בדבר שאינו מצוי אמר **לא צדה** פירוש לא צדה להורגו גם לא צדד שלא להורגו, כי כל שוגג צד חיובא הוא שהיה לו להעלות על דעתו לבל תבא תקלה על ידו, אבל במקום שהגם שיצדד הוא דבר שאינו רגיל אנום הוא ופטור, וכנגד בחינת מזיד של השונא אמר **והאלהים** וגו' פירוש למעט בא שלא בא הדבר אלא מה' ולא ממנו כי לא חפץ הוא המיתו כי לא שונא לו אלא מה' יצא הדבר, אבל אם גם יש צד שנאה ממנו שהיה שונא אינו גולה:
@14 **וכי יזיד וגו'**. בספרי (מכילתא כאן) וזה לשונם למות ולא לדון ולא ללקות ולא לגלות. וזה הוא טעמו של יואב שברח אל המזבח ויחזק וגו', הגם שלא הרגו שלמה אלא בדין וכמו שכתבו התוספת בסוף פרק נגמר הדין דף מ''ט. שהיה מורד במלכות, הוא ברח קודם הדין. ואמרו בהגולין (מכות י''ב.) כי טעותו היה שלא היה מזבח עולמים וגם שתפם בקרנותיו ואינו קולט אלא גגו:
@14 **וראיתי** לרמב''ם שכתב בפ''ה מהלכות רוצח ושמירת נפש שהמזבח קולט רוצח בשוגג לענין מיתה מגואל הדם אבל לא מגלות עד כאן, והוא ודאי שלא ראה הברייתא שמדייק למות ולא לגלות ולא וכו', והגם שיש לדחוק ביישוב אומרם ולא לגלות שהכונה היא למי שנתחייב גלות שלא יהרגנו גואל הדם, פירוש זה דחוק הוא, וגם תכחישנו מה שלפניו ולא לדון ולא ללקות והבן. ומה מאוד גדלה לי הקושיא לדעת הרב בעל משנה למלך שכתב ותמה על רמב''ם שחלק בין שוגג למזיד אפילו לענין מיתה מגואל הדם ואמר כי אין לחלק כלל בין שוגג למזיד עד כאן, ואין דבריו מחוורין אפילו בלא מתניתא כי אין לנו לומר שאין מזבח קולט אלא במה שמיעט הכתוב בפירוש:
@18 **וכי יריבון אנשים וגו' ולא ימות**. צריך לדעת למה הוצרך לומר **ולא ימות** ולא סמך להבין כי בלא ימות מדבר הכתוב בין ממה שקדם במשפט אם ימות ב. ן ממה שגמר אומר אם יקום והתהלך וגו':
@18 **אכן** הכונה היא לומר שאין חיוב לתת שבת ורפוי אלא אם לא ימות אבל אם ימות לא יתן שבת ורפוי, ולזה לא אמר הכתוב שבתו יתן וגו' אלא אחר שעמד מחליו והתהלך. ומסתפק אני אם אמדוהו למיתה ולא מת אם נאמר מעשה נסים נעשו לו שלא מת כמו שאמרו ז''ל (חולין מ''ב.) בטריפה שאינה חיה ואם חיתה מעשה נסים נעשו לה (שם מ''ג.) כמו כן במה שלפני כאן אם לא מת נס הוא זה וחיוב שבת ורפוי כיון שפקע פקע או דלמא הרי לא מת וחייב בשבת, ומדברי רמב''ם בפ''ד משמע כי כל שלא מת הגם שאמדוהו למיתה חייב בשבת וריפוי. שוב מצאתי שאמרו במכילתא וזה לשונם ולא ימות ונפל למשכב הא אם הכהו המכה מכה שיש בה כדי להמית פטור מהשבת והרפוי עד כאן. משמע אפילו לא מת ממה שתולה הטעם במכה ולא אמר הא אם ימות:
@18 **ונראה** שכוונת התנא לומר שצריך ליפטר מן השבת דוקא אם מת על ידי מכה שיש בה כדי להמית אבל אם מת במכה שאין בה כדי להמית שאז פטור המכה ממיתה יתחייב לתת שבת וריפוי אם לא נתן לו בחיים חיותו לצד איזו סיבה יתחייב לתת ליורשיו כל מה שנוגע לאביהם אם חי:
@19 **רק שבתו יתן ורפא** י **רפא**. פירוש אפילו אחר שקם והתהלך בחוץ אם הוא עדיין בטל ממלאכתו ואינו יכול לעשותה או שעדיין הוא צריך לרופא לשיורי החולי מחמת המכה הרי זה חייב לתת. ואומרו רק יתבאר על פי מה שכתב רמב''ם (פ''ב חובל ומזיק) משערין את הריפוי וכו' וכן השבת אומדין וכו' ואם וכו' וארך החולי יותר על מה שאמדוהו אינו מוסיף לו כלום וכו' במה דברים אמורים כשרצה המזיק שזו תקנה היא לו וכו' עד כאן, ולזה אמר רק וגו' פירוש למעט בא שיש זמן שלא יתן שבתו ורפואתו והוא אם קדם וקצב וכו' אבל בלא קצבה יתן עד שיתרפא לח לוטין:
@19 **ורפא ירפא**. יתבאר על דרך מה שכתב רמב''ם (הל, חובל ומזיק פ''ב הי''ד) אמר לו הניזק פסוק וכו' ואני ארפא את עצמי אין שומעין לו, והוא או' **ורפא ירפא** ולא אמר יתן כאומרו בשבתו הסמוכה שהיה לו לומר שבתו ורפואתו יתן, והרבה דרשות נאמרו בכפל זה:
@20 **בשבט**. כתב רמב''ם בפ''ב מהלכות רוצח וז''ל יראה לי דוקא בשבט אבל בסייף וסכין או אבן ואגרוף וכיוצא ואמדוהו למיתה אפילו מת לאחר שנה הרי זה נהרג עליו עד כאן. וקשה לי אם לא הרגו בדבר שאמדוהו להריגה למה אם לא יעמוד יום יתחייב הרי אפילו לאדם אחר שאינו עבדו פטור הוא אפילו לא יעמוד יום. ואולי שעל שאר אומדנות הוא אומר שהגם שאמדוהו שימות במקום המכה ושאר אומדנות. ולי נראה שאומרו **בשבט** לומר שאם מעשיו מוכיחים כי ליסרו בשבט מוסר הוא שנתן ה' זכות יום אחד וכו', אבל אם מעשיו מוכיחים שמתכוין להורגו כגון שתוחב לו סכין בבטנו ובסימניו שזה מגיד שאינו מיסרו אלא ממיתו ומת אפילו אחר שנה חייב עליו:
@21 **לא יוקם כי כספו**. ואם הרגו שוגג יגלה על ידו, ובדין זה אין בו חילוק בינו לבין רוצח לאדם שאינו עבדו כי אינו חייב גלות אלא אם הרגו ומת תחת ידו ממש וכמו שכתבנו בפסוק (י''ב) מכה איש וגו', ולא הוצרך לכתוב אלא דין שהוא משונה מדין רוצח לשאינו עבדו:
@22 **וכי ינצו אנשים**. פירוש וכל אחד מתכוין להרוג את חבירו ובאה המכה באשה בזה הוא שאמר כל צדדי הדינים האמורים בענין:
@22 **ונגפו וגו'**. אמר לשון רבים לומר שאם שניהם נפלו עליה ונגפוה משלשין ביניהם וכמו שכתב רמב''ם בפ''א מהלכות חובל ומזיק:
@22 **אשה הרה**. פירוש המצויה שם בידיעתם, אבל אם באה ועמדה בגבולם ונגפוה בלא ידיעה פטורים מכלום מדין שכתב בירושלמי ופסקו רמב''ם בפ''א מהלכות חובל ומזיק וזה לשונו אם היה אחד ישן ובא אחד ושכב בצדו הרי זה פטור הישן גם מהנזק כי זה אונס מיקרי:
@22 **כאשר ישית עליו בעל האשה** פירוש לצד כי הוא הנוטל דמי ולדות הוא יהיה בעל דינו בעונש זה לקחת ממנו הראוי לו:
@23 **ונתתה נפש וגו'**. נחלקו רבותינו ז''ל במכילתא יש אומרים מיתה הגם שנתכוין להרוג את זה והרג את זה ויש אומרים ממון. ולדבריו ידוייק אומרו **ונתתה** על נכון שהוא דבר הניתן מיד ליד. ולמאן דאמר נפש ממש אמר **ונתתה** לומר כי במקום נתינה האמורה בסמוך כשלא יהיה אסון תהיה זו ואין כאן נתינה אחרת כי פטור מדמי ולדות זולת אם היה אסון והוא בדרך שאינו חייב כגון שאמדו המכה שאינה כדי להמית הרי זה חייב וכמו שכתבתי בפסוק (י''ח) וכי יריבון:
@26 **וכי יכה וגו'**. בקידושין (כ''ד:) פליגי רבן שמעון בן גמליאל ורבנן רבן שמעון בן גמליאל סובר צריך לכוין לשחתה ורבנן סוברים הגם שלא נתכוון לשחתה אלא שצריך לכוין לעין עצמה. וקשה לרבנן היה לו לומר וכי ישחית איש את עין עבדו. ואולי כי הייתי אומר כי השחתה שאמר הכתוב היא לגופה ולא היינו יודעים שיכוין הכתוב לומר תנאי הוא הדבר שצריך שיכוין לה:
@26 **עוד** נראה שנתכוון לומר שהגם שלא שחתה בשעת הכאה עצמה אלא אחר זמן יהיה הדין כן ואינו דומה לשוגג שכתבנו למעלה שצריך שימות בשעה עצמה. ודרשת רבנן שצריך שיכוין לעין נשמעת מכינוי ושחתה:
@27 **ואם שן עבדו**. טעם שלא כלל הכתוב שן ועין וחלקם בב' מצות, יתבאר על דרך אומרם ז''ל בקדושין (כ''ד:) אמר ר' ששת היתה עינו סמויה וחטטה יוצא לחירות, ולפי זה יש בעין ב' דינים של שחרור. האחד אם כיהה עינו הגם שלא חטטה כמובן שם בקדושין שהגם שלא נחטטה כל שחסר מאורה ואינו יכול להשתמש בה יצא לחירות, והב' שהגם שהיתה כהויה אם חטטה יצא לחרות, ואם היה הכתוב כולל אותם בדין אחד היינו לומדין בעין כדין השן מה שן ביטולה הוא נפילתה גם עין ביטולה הוא נפילתה אבל כיהוי שאינו מחסר כלל מהעין לא יצא לחירות:
@28 **וכי יגח וגו' את איש**. טעם אומרו **את**. יתבאר על דרך אומרם בגמ' (סנהדרין ע''ט.) נתכוין להרוג שמעון והרג ראובן חייב שהרי נתכוין להרוג מי שחייב עליו, והוא אומרו **את איש** לרבות כל שנתכוין לאיש הגם שהרג אחר שלא נתכוין לו. ודוקא נתכוין לאיש אבל נתכוין לבהמה והרג האיש פטור כדאמרינן שם (ע''ח:):
@28 **ומת** פירוש אפילו מת אחר זמן כל שמת מחמת נגיחה, וכן משמע מדברי רש''י (ב''ק מ''א.) בפירוש סוגיית סכן ג' בני אדם ולא מתו יעויין שם:
@28 **ולא יאכל את בשר** ו. ואם אכלו לוקה, אבל שאר הנאות הנשמעות מאומרו ובעל השור נקי הגם שאסור אינו לוקה, ולזה לא כלל הכל בכללות אחד:
@28 כט) **והועד בבעליו**. אמר לשון רבים, נתכוון לומר שאם היו לו ב' בעלים חייבים שניהם מיתה, ולא יהיו כב, שהרגו אדם כאחת שפטורין למאן דאמר (ב''ק כ''ו:), כי התם פטורין ממיתה בידי אדם וחייבים בידי שמים וכאן פטורין ממיתה בידי אדם וחייבים בידי שמים. ובכופר להיותו ממון חייבין אפילו בידי אדם:
@30 **פדיון נפשו**. נחלקו בפרק ארבעה וחמשה (ב''ק מ') בשל מי שמין אם בשל מזיק אם בשל ניזק. והיה נראה כי להאומר בשל מזיק אם המית שור של ב' בני אדם חייבין לשלם דמי כל אחד מהם כי כולן נתחייבו לשמים. ולהאומר של ניזק אינם חייבין אלא דמי הניזק. וקשה אם כן מאי בעי שם ר' נחמן לר' אחא בר יעקב אם חייבין לתת כופר כל אחד שלם הלא דבר זה מחלוקת התנאים, אלא ודאי דהן אמת להאומר בשל מזיק ודאי שצריך לשלם ב' כופרים מידי דהוה שהמית שור אדם גדול ששוה מאתים לאדם ששוה חמשים שחייב לשלם ולא יגרע אם יחלקו לב' גופים וחייבים לתת דמי כופר שנים, ובעיא דר' נחמן היא אליבא דחכמים שסוברין שמין בשל ניזק, וכן משמע מדברי רמב''ם שפסק פי''א מהלכות נזקי ממון בדין דמי כופר ששמין דמי הנהרג ובשור ב' שותפין פסק (שם פ''י) שחייבין ליתן כופר שלם לכל אחד והבן. וטעם שפסק רמב''ם לחומרא משום דהויא ספק כופר נפש:
@30 **ואם** קדם גואל הדם והרג את זה קודם שיתן פדיון נפשו נראה לי שנהרג עליו שלא פטר הכתוב אלא הריגת הורג ביד בשוגג מדין יחם לבבו אבל אם שורו הרג אין כאן יחם לבבו כהורג ביד:
@33 **וכי יפתח וגו'**. פירוש אפילו בשעת פתיחת וכריית הבור אם נפל עליו שור או חמור חייב בעל הבור, ואפילו נהרג בתוך בורו יורשיו ישלמו וכדאיתא בפרק קמא דערכין (ז'):
@35 **שור איש את שור רעהו**. אומרו **את**, ירצה ששניהם שוים בחייהם כשנערכו אותם יהיו שוים, והוא אומרו **שור איש את שור** פירוש הנערך אתו, אבל אם היה גדול הנוגף אין לניזק אלא חצי נזקו, וכן מבואר בדברי רבותינו ז''ל (ב''ק ל''ד.) ואם אין שיעור המזיק כניזק אין לומר שיטול יותר מחציו של חי שאם כן לא היה הכתוב תולה במכירת השור החי אלא היה לו לומר יתן לו חצי נזקו של מת ויחצון המת, וממה שתלה בחצי שור החי שמע מינה שאין לו אלא חצי החי הגם שיעלה לפחות מחצי נזק, ולא חש עלי לטעות שאפילו יותר ממה ששוה. ואם תאמר כלך לדרך זה מה שתלה הדבר בחצי החי הוא אפילו יהיה בחציו יותר מחצי נזק ואמר ההשואה בשוודים להיכא שלא היה שוה שיטול יותר מחצי, זה אינו דלכשתאמר כי ניגף יטול חצי מזיק הרי לא חלקת אם כן לפעמים יגח שור שוה מאתים לשור שוה חמשים ולכשתדון כסברא זו הרי הוא נוטל כפלים מהזיקו ונראה למי דומה דין זה שנסכים עליו:
@36 **ולא ישמרנו**. יתבאר על דרך אומרם בפרק ד' וה' (ב''ק מ''ה:) ר' אליעזר אומר אין לו שמירה אלא סכין אמר רבה מאי טעמא דאמר קרא ולא ישמרנו שוב אין לו שמירה לזה אמר ליה אביי אלא מעתה ולא יכסנו נמי שוב אין לו וכו' עד כאן. ונראה כי דיוקא דרבה קאי וקאי, כי יש הפרש בין ולא יכסנו שהכתוב לא שינה שיעור הדבור שהתחיל לומר כי יפתח לשון עתיד כי יכרה וגו' ולא יכסנו לשון עתיד מה שאין כן ולא ישמרנו שהתחיל הכתוב לומר לשון עבר או נודע וגו' וגמר אומר לשון עתיד ולא ישמרנו שהיה לו לומר ולא שמרו ונכון. והתם לא חש רבה להשיב לאביי, ולסברת ר' יהודה שפוטרו בשמירה אפילו פחותה אמר הכתוב כסדר זה ולא ישמרנו לדרוש לזה ולא לאחר, ועיין שם בסוף הפרק:
@36 **ישלם שור**. אולי שהגם שאמרו (ב''ק ה'.) מועד ישלם מעידית שבנכסיו אם היה לבעל המזיק עידית יותר בנכסיו יכול לסלקו בשוה כשורו ולא אמרו עידית אלא לאפוקי פחות מזה:
@37 **וטבחו וגו'**. פירוש לשור ושה, אבל טלה וגדי וגדלו ברשותו ונשתנו בידו אינו חייב שקנאו בשינוי ושלו מכר או טבח וכן מוכח מדבריהם (ב''ק ס''ה):
@37 **השור**. במשנה (שם ס''ב:) אמרו אין חייב בד' וה' אלא דוקא שור ושה ולא חיה ועוף, וטעמם שהיה לו לומר כי יגנוב איש שור וטבחו או מכרו חמשה בקר ישלם וארבע צאן תחת השה, ודורש אחת מהם למעט כל חוץ מהם וביתור של אחד היה נשמע המכוון שישתנה הדין בין השור לשה:
@40 **אם המצא תמצא**. טעם הכפל לומר אחת לגופה שבאו עדים שגנבה, וב' לומר שמצאוה בעין אצלו, אבל זולת זה יתחייב בד' וה' שכל שאינה בידו בחזקת מכורה או שחוטה, ולא אמר הכתוב שנים לבד אלא בנמצאת. ותדע שלאו דוקא מכר או טבח אלא הוא הדין נתן או אבד כל שיצתה מרשותו, וכן מוכח בש''ס (ב''ק ע''ט:) להדיא, והוא הדין הקדיש. וראיתי לדייק מכאן שאם גנב מעובד כוכבים ומזלות אין בו דין ואם אין לו ונמכר בגניבתו שאמר בסמוך ממה שאמר סמוך לונמכר בגניבתו אם המצא תמצא וגו' שנים ישלם ואמר הכתוב בדין תשלומי ב' לרעהו ולא לעובד כוכבים ומזלות כמו שדרשו ז''ל (מכילתא) הא למדת כי דין ונמכר בגניבתו האמור בענין אין הכתוב מדבר אלא בגנב מישראל ולא מעובד כוכבים ומזלות ולא מהקדש, והם דברי רמב''ם בפ''ג מהלכות גניבה ולא מצאו לו שם טעם והנה הוא:
@41 **כ יבער איש וגו**. יתבאר על דרך מה שאמרו בהכונם (ב''ק נ''ו:) אמר רב המעמיד בהמת חבירו על קמת חבירו וכו' חייב, ואמרו שם אפילו קם לה באפה ואפילו הכישה חייב, והוא אומרו **כי יבער איש** פירוש. אפילו אם [אין] הבעיר שלו. ואומרו **ושילח את בעירו** פירוש ואפילו לא העמיד ולא קם לה באפה ולא הכישה אלא ששלחה לנפשה ולא שמרה מלכת והיא מעצמה ביערה בשדה הזולת אם הבהמה שלו כאומרו בעירה בכינוי חייב מיטב וגו':
@42 **כי תצא אש וגו'**. פירוש הגם שהדליק בתוך שלו כשיהיה באש הנדלקת שיעור לצאת למקום שאינו שלו. ושיעור תיבת **תצא** הוא שתהיה ראויה לצאת, אבל הדליק בתוך שלו ולא היה שיעור לצאת לחוץ ויצאתה פטור שזו מכה בידי שמים וכדאיתא בגמרא (ב''ק ס''א:) ואומרו **ומצאה קוצים** פירוש והגם שזולת הקוצים לא היתה משגת מקום קמה וגדיש להבעירם ובאמצעות הקוצים נאכל גדיש וגו' **שלם ישלם** פירוש שלם הגדיש או הקמה ישלם דמי העצים הגם שהם אדרבה היו סיבה לקלקול. ודוקא שמצאתם אבל בא אדם והניחם אחר שהבעיר, השני חייב לשלם.
@42 **המבעיר** וכפל לומר **הבערה** לרמוז גם אל העצים שהם הם המבעירים את הגדיש והקמה:
@42 **עוד** נתכוין באומרו **ומצאה** הגם שלא ידע המבעיר שהיו שם קוצים או אפילו לא היו שם בשעת ההבערה ובא אדם והניחם במחוז שלו ולא ידע כי יש הבערה הרי המבעיר חייב:
@42 **ובדרך** רמז תרמוז התורה את אשר יסובבו הרשעים ברשעם כדי שיתעורר האדם מתרדמת שינת שכלו בהביטו הפלגת הרעות אשר יביאו לעולם כי לא לבדם יריעו אלא יסובבו רע לכל העולם, והוא אומרו **כי תצא אש** הלא ידעת כי צרת העם תתכנה בשם אש. וצא ולמד משליח גבריאל (יומא ע''ז.) אשר שאל אש מבין הבדים (הכרובים) והוא בחינת תגבורת הדינים, ואמר **ומצאה קוצים** הם הרשעים שאינם אלא קוצים מכאיבים, ואומרו לשון **מצאה** על דרך אומרו (דברים לא כא) והיה כי תמצאן אותו וגו', והטעם משום שהרשע אין לו בעלים כי האדון ברוך הוא הנה הוא פקר בו והסיר אדנותו מעליו וה' הסתיר פניו ממנו ומעתה הרי הוא כמציאה וכל הפוגע בו יעשה בו רצונו, והודיע הכתוב עוד כי אחר שניתן רשות לאש הדינים להבעיר לא לקוצים לבד הם מבעירים אלא **ונאכל גדיש** כאן רמז אל תינוקות של בית רבן שעדיין אין להם קומה אלא גדושים שבולת עם חברתה כי בעונות הם הנתפסים בצרת עולם. גם אמרו ז''ל (שהש''ר פס' משכני) בפסוק (תהלים ח) מפי עוללים ויונקים יסדת עוז כי היו ערבים בשעת קבלת התורה וכשירשיעו בני אדם הנה הרשות נתונה לאש לבער בהם, ואומרו **או הקמה** כאן מודיע כי לפעמים חרב עד צואר הגיעה מופתי הדור יסודי עולם נלקחים בעונם כדי להציל על כללות הדור כאומרו (שה''ש א') אשכול הכופר וגו', ולהם יקרא קמה על דרך אומרו (שם ה') זאת קומתך דמתה לתמר שהם הצדיקים הנמשלים לתמר כאומרו (תהלים צ''ב) צדיק כתמר וגו', ולפעמים יגדל החטא ולא יצילו הצדיקים לבד וחימה שפוכה על כל שונאי ישראל, והוא אומרו **או השדה** שזה ירמוז אל כללות ישראל ולא יספיקו לא תינוקות ולא צדיקים להציל. והודיע הכתוב כי יש יום לאל איום לבא במשפט עם הסובבים את הדבר למיתת הצדיקים וגאוני עולם להשתלם מהם, והוא אומרו **שלם ישלם המבעיר** הם הרשעים הקוצים את כל אשר הרגו, ואמרו ז''ל (סנהדרין ק':) כי ה' יתן כח ברשעים לסבול שיעור המגיע להם בחטאם אוי לרשע רע לשמים ולבריות כמה יסבול בעד קלקולו, ותמצא (ב''ר פס''ג) שהצדיקים כשהיו בניהם מגיעים לכלל שנים שאינם נלכדים בעון אביהם היו שמחים ואומרים ברוך המקום שפטרם מעונש זה, הרי כי יעניש ה' לגורם עונש בשבילו לזולת, ובאמת כי יחרד אנוש ויכבה שלהבת יצרו המחטיא אותו באש המשפט בהעלותו על לבבו נהרות העונשים אשר יגיעוהו על כמה נפשות קטנים וגדולים אין קץ שכולם הוא הרצחן הגדול להם באמצעות תאותו הסרוחה, והנה אמרו ז''ל (קידושין מ':) לעולם יראה אדם כאלו כל העולם כולו חציו זכאי וכו' עשה עבירה אחת אוי לו שהכריע את כל העולם לחובה ודם כל העולם ודם זרעיותיהם על צוארו ועל נפשו עמוסים ויסבול מר המות בעד כל נפש אחת מהם ובכל צרתם לו צר כאשר עשה, והוא אומרו **שלם ישלם** וגו' טעם כפל שלם וגו' המבעיר וגו' כאן רמז הכתוב כי לא לאיש הרשע לבד יעשה ה' משפט התשלומין אלא גם להמחטיאו והוא יצר הרע בחינה המחטיאתו כי גם לו משפט חרוץ ביום ההוא יגדל המספד עליו בעשות בו ה' דין כמאמרם ז''ל (סוכה נ''ב.) שמביאו ה' ושוחטו ולא ימלט בבורחו לבצרה ואפילו לבצר (מכות י''ב.) כי מזיד הוא ומלך המשפט ישפוט בצדק להשתלם ממנו ונשגב ה' לבדו ובקמא (ב''ק ס'.) רמזו באופן אחר:
@43 **כי יתן איש**. פרשה זו העמידוה רבותינו ז''ל (ב''מ צ''ד:) בשומר חנם כי הוא לבדו פטור מגניבה ואבידה, ואמרו שעל כל פנים חייב בפשיעה, ולא נודע מנין להם כיון שהכתוב לא חייבו אלא לישבע שלא שלח ידו כל חוץ מזה פטור, ורש''י ז''ל בהשואל דף צ''ה כתב בדיבור המתחיל אשומר חנם וז''ל דכתיב ביה פשיעה דכתיב על כל דבר פשע. ונשאר לדעת על מי סמך הכתוב לדעת כי ידבר בשומר חנם. ואולי כי לצד שהלביש הנתינה בכסף או כלים שהם דברים שמן הסתם שאינם צריכין שכר לשומרם ובשומר שכר אמר דברים שמן הסתם צריכין שכר לשומרם שהם חמור או שור או שה וכל בהמה שכל מין זה יש בו טיפול ומן הסתם רגילות לשמור בשכר:
@43 **אל רעהו**. רבותינו ז''ל אמרו (שם נ''ז:) ולא של הקדש, ונראה לי לתת טעם הדבר שהוא לטעם עצמו שצוה ה' לפטור בבעלים ושפיר יקרא האדון בעליו של הקדש עמו של כל נפקד שאין לך שעה ורגע שאין ה' עושה פעולה עם האדם בין בבחינת גופו בין בבחינת צרכיו:
@43 **כסף או כלים**. לא היה צריך לומר אלא כי יתן איש אל רעהו והרי הוא אומר בסמוך על כל דבר פשע על שור על וגו' ודרשו ז''ל כל פרטים שיתחייב עליהם אם לא שמר ופשע. ואם לרשום הכתוב כי בשומר חנם הוא מדבר היה מספיק לומר כי יתן כסף, [כלים] למה לי. ובמכילתא אמרו כסף או כלים מה כסף שדרכו לימנות אף כלים שדרכם לימנות מכאן אמרו כל טענה שאינה במדה במשקל ובמנין אינה טענה עד כאן. ואין סתירה לדברינו מדכריהם. עוד נראה לי טעם אומרו **כלים** לומר שהגם שירצה השומר לשלם אינו נפטר, וכמו שכתב רמב''ם בפ''ו מהלכות שאלה ופקדון שאם הפקדון הוא כלי מתוקן משביעין אותו, והגם שהרמב''ם אמר משום תקנת חכמים אפשר שירמוז הכתוב לזה, וידוייק גם כן מה שגמר אומר הכתוב **אם לא שלח ידו במלאכת רעהו** דקדק לומר מלאכת לומר הגם שאין טענה אלא טענת מלאכה שבכלים ומשלם שויו:
@43 **לשמור**. במכילתא רבי ישמעאל אומר עד שיפקיד אצלו ויאמר לו שמור לי אבל אם אמר לו עיניך בו הרי זה פטור. ובהחובל (ב''ק צ''ג.) דרשו לשמור ולא לאבד ולקרוע לשמור ולא לחלק לעניים. ומדברי התוספת שם משמע שלא פטר התנא כל שלא אמר לו שמור לי אלא מפשיעה אבל אם אבדו בידים אינו פטור עד שיאמר לו בפירוש לאבד ולקרוע, וקשה לי מנין מצאו לדרוש ב' מיעוטים בב' הדרגות הא' אם לא אמר לו שמור פטור מפשיעה והב' אם אמר לו לאבד פטור אם אבד. ונראה כי דרשת מכילתא דרשה גמורה היא ודרשת החובל ולא לאבד סברא היא אלא שאסמכוה אקרא. ותדע כי אמרו עוד ולא לחלק לעניים וטעם מיעוט העניים מוכח משם שהוא מטעם שהוא ממון שאין לו תובעים, וכמו שאמר שם בההיא מעשה שהקדיש ההוא גברא ארנקי לצדקה אפקדיה רב יוסף בההוא גברא אתו גנבי גנבוהו וחייביה רב יוסף אמר ליה אביי והתניא לשמור ולא לחלק לעניים אמר ליה עניי פומבדיתא מיקץ קץ להו ופרש''י והוה להו ממון שיש לו תובעים, הרי שטעמו הוא זה, ולטעם זה לא היה צריך מיעוט דזה כיון דאקדשיה לממון זה לעניים פקע זכותו ממנו ונשאר הממון אין לו תובעים, ונראה כי הוא הדין אם אמר לו לשמור לחלקם לעניים שהוא פטור מטעם שהוא ממון שאין לו תובעים, והראיה ממה שמקשה אביי לרב יוסף מברייתא לשמור ולא לחלק ומאי קושיא דלמא הוא אמר לו בפירוש לשמור מה תאמר שלא אמר לו לשמור אם כן הוה ליה להקשותו מברייתא דלשמור עד שאמר לו שמור וזולת זה יהיה פטור אפילו בממון שאינו לחלק, עוד אמרו שם במכילתא אחר דברי ר' ישמעאל ר' נתן אומר לשמור להביא כל הדומה לכסף וכלים:
@45 **על כל דבר פשע וגו'**. אמרו ז''ל (ב''מ נ''ז:) על כל וגו' כלל על שור וגו' פרט על כל וגו' חזר וכלל מה הפרט דבר המטלטל וגופו ממון וכו' יצאו קרקעות שאין מטלטלין ועבדים שהוקשו לקרקעות יצאו שטרות שאין גופן ממון עד כאן. ופסק כן רמב''ם פ''ב מהלכות גניבה. הנה פשטן של דברים יגידו כי הגם שפשע שומר חנם וכו' פטור כי זולת הפשיעה אפילו בכסף וכלים פטור הוא. וראיתי לרמב''ם שכתב בפ''ב מהלכות שכירות וזה לשונו יראה לי שאם פשע השומר בעבדים וכיוצא בהם חייב לשלם שאינו פטור בעבדים וקרקעות ושטרות אלא מדין גניבה ואבידה שאם היה שומר חנם ונגנבו או אבדו וכו' פטור משבועה כו' אבל אם פשע בה חייב לשלם שכל הפושע מזיק הוא ואין הפרש בין דין מזיק קרקע לדין מזיק מטלטלין ודין אמת הוא זה למבינים וכו' עד כאן. וחלקו עליו רבוואתא ז''ל בטענה הנשמעת והיא שאם היה פושע מזיק ממש לא היה פטור אם בעליו עמו שאמר הכתוב לא ישלם ואפילו אם פשע וכמו שכתב רמב''ם עצמו בפ''א מהלכות שכירות וזה לשונו ואפילו פשע כו' ואבד מחמת הפשיעה פטור עד כאן. ופשוט שדין פושע אינו כדין מזיק כי הפושע אינו לא שומר ולא מזיק אלא שבהסתלקות שמירתו ההיזק בא מעצמו אבל המזיק הוא גורם לו ההיזק. ועוד הקשו אם כן יתחייב על כל פנים שומר חנם שבועה שלא פשע כיון שאם פשע חייב:
@45 **ונראה** לומר כי מה שהקשו משמירה בבעלים שאני ושאני כי בבעלים גילה הכתוב בפירוש כי פטור הוא הגם שהזיק כמובן מהכתובים וכמו שדרשו בהשואל, אבל מה שמיעט הכתוב קרקעות ושטרות בדין שומר חנם לא מצינו שמיעטם בפירוש אפילו פשע כי לא הוזכרה פשיעה כלל אלא שליחות יד דכתיב אם לא שלח, ומה שאנו מחייבין שומר חנם על הפשיעה אינו אלא לצד דין מזיק ואיך נפרש המיעוט על דבר שלא הוזכר כלל, ואם אומרו דבר פשע, כבר פירשוהו שיכוין על פשעו בו שגנבו הוא ואומר נגנב אבל הפשיעה לא הוזכרה. והן אמת כי אם הפשיעה לא היה בה משפט מזיק היינו אומרים כי מיעט לכל משפטי שומר חנם הגם שלא הוזכרו אכן למה שאנו רואים כי מה שחייבו חכמינו ז''ל פושע הוא מדין מזיק אם כן מנין לנו להקל בדבר, ולזה כתב הרמב''ם שאין לפוטרו. ואם תאמר כיון שפושע דין מזיק יש לו אם כן בעל הבית שהדליק גדישו של שכיר או כסותו יהיה פטור שהרי פושע מזיק ופטר רחמנא. ואולי כי לא הקל הכתוב אלא בשומר. עוד נראה כי גם הרמב''ם יודה שאין לו דין מזיק ממש, ואם שרף כסותו המופקדת אצלו מהבעלים חייב עליה, ופושע כמזיק ולא מזיק ממש. ותמצא שכתב רמב''ם פכ''א מהלכות אישות האשה ששברה כלים בעת מלאכתה פטורה מתקנת חכמים עד כאן. הרי ששבירה בידים אינה פטורה אלא מתקנה, ומה שהקשו עליו אם כן יתחייב שבועה על הפשיעה, כתב רמב''ם פ''ד מהלכות שאלה ופקדון המפקיד אצל חבירו חנם ונגנב וכו' הרי זה נשבע וכו' אם לא שלח ידו וגו' ומגלגלין עליו שלא פשע עד כאן. משמע מדברי הרב כי עיקר שבועה דאורייתא אינה אלא שנגנבה ואינו ברשותו אבל שבועת שלא פשע מדין גלגול אנו באים עליה, ומעתה שבועת שלא פשע האמורה בשומר חנם תקנת חכמים הוא שלא אמרה תורה אלא שלא שלח, ולזה כל שישנה לשבועה של תורה גלגלו בה חכמים שבועת לא פשע וכל שאינה שבועת התורה שפטרתו פקע גלגול:
@45 **נמצינו** אומרים שלא בא המיעוט של ההקדשות הקרקעות וכו' אלא על שבועת שומר חנם שלא שלח ידו דוקא ואם יטענו שפשע בה יתחייב שבועת היסת כתקנת רב נחמן (ב''מ ה'.) ולפי זה מה שאמרו בסוף פרק החובל (ב''ק צ''ג.) בההוא ארנקי של צדקה שהפקידו רב יוסף אצל ההוא גברא נגנב וחייבו רב יוסף והקשה אביי לשמור ולא לחלק אם כן שסובר שממעט הכתוב אפילו מדין פושע כי התם שפושע היה ממה שחייבו לשלם והוא שומר חנם, לפי מה שכתבתי בפסוק לשמור כי דין זה דלחלק מסברא פטור הוא בלא מיעוטא דלשמור אלא דאסמכוה אקרא או שבא הכתוב לבל תטעה מדבריו לחייב אפילו לחלק, לזה שמר לך הסברא הנשמעת לך כי כל ממון שאין לו תובעים פטור הוא כי לכל אחד יאמר וגו' מה שאין כן דין פושע בממון שיש לו תובעים שהשכל נותן כי פושע מזיק הוא אם לא תהיה ראיה ברורה לפוטרו, כמבואר, כשלא בבעלים, בדינו עומד:
@47 **בין שניהם**. ירצה כי יש עונש לנשבע ולמשביע אם ידע שהוא רוצה לישבע לשקר ומסכים על הדבר:
@51 **אם בעליו עמו וגו'**. יש לנו לדון במשפט זה האם נשפטה בדין זה לעולם הבא כשיבוא בעל הפקדון הוא אדון העולם אשר הפקיד הנפש ביד האדם לשמור דכתיב (דבדים ד ט) ושמור נפשך מאד כשיבא לתבוע פקדונו מכל א' ונמצא נגנב או נשבר או נשבה או מת כי כל בחינת אלו ישנם מצויות בעוברי עבירה יש מי שנפשו נגנבת ממנו במקרה לא טהור ויש שהוא מזיד בעבירה ואבר מאברי הנשמה המיוחד כנגד המצוה שעבר עליה הוא נפגם ולפעמים בעשות עון מהכריתות ומיתות בית דין גורם מיתה לנפש כאומדו (בראשית יז יד) ונכדתה הנפש ולפעמים יגרום לה שביה על דרך אומרם (זהר ח''ב צ''ה:) הנפשות העשוקות וגו' ובעמוד בעל הפקדון ויטעון טענה הנשמעת תן לי הנפש כמו שנתתיה לך כאומרו (קהלת י''ב) והרוח תשוב אל האלהים אשד נתנה ודרשו ז''ל (שבת קנ''ב:) תנה לו כמו שנתנה לך האם יכולין הנפקדים ליפטר בטענת בעליו עמו, כי אמרו ז''ל (ב''מ צ''ז.) אפילו אמר לו השקיני מים ושאל ממנו חפצו הרי זה שאלה בבעלים והוא הדין כל השומרים, והן האדון קדם לזון ולכלכל מיום היות האדם והוא הנופח באף האדם נשמת חיים ומתעסק בצורכי אדם מלבד אשר יעשה לכללות העולם מחדש בכל יום מעשה בראשית לזה יקרא בעליו עמו מתחלה ועד סוף והרי שומרי הנפשות פטורים הגם שלא ישיבו הנפש כמו שנתנה:
@51 **ואומר** לנפש אדם אל תבטחי בעושק משפט זה כי לב' סיבות לא יפטר בטענה זו, האחד כי כאן פירש בפירוש שיתחייבו השומרים וכל תנאי שבשמירה קיים וכאומרם בהשוכר את הפועלים (ב''מ צ''ד.) מתנה בעל הפקדון על שומר חנם להיות חייב כשואל והטעם כי כל תנאי שבממון קיים והוא הדין שיכול להתנות המפקיד על השומר שיתחייב הגם שהוא בבעלים ואין זה מתנה על מה שכתוב בתורה בדרך זה כמובן מההיא דאמר שמואל במס' מכות (ג':) ע''מ שלא תשמטנו שביעית אין שביעית משמטתו, ואמרו ז''ל שהטעם הוא שכל תנאי שבממון קיים ובמציאות שלפנינו כאלו התנה בפירוש על הדבר ממה שקבע עונשין לכל העובר על הפקודים ועוד לו שהוסיף להשביעה על הדבר, ב' יש לך לדעת כי שופטי ארץ לא ישפטו כל החיובים אלא מעט מהרבה וכל המשפטים השופט כל הארץ ישפוט בצדק ומי יאמר כי הפושע בנכסי רעהו והוא בבעלים שלא ישפטהו השופט כמו שהוא שופט כמה וכמה שפטורין בדיני אדם וחייבים בדיני שמים וכו' וכמו שפירשתי למעלה בפסוק (כ''א י''ב) מות יומת כי לא לכל מחוייבי מיתה יצו ה' לשופטי ארץ להרוג וכו'. ותמצא כיוצא בזה שצוה ה' כי שומר חנם ושומד שכר ושואל פטורין בהקדשות ואפילו פשעו ואפילו לרמב''ם שחלק לחייב בפשיעה בקרקעות ועבדים נראה מדבריו כי יודה בהקדשות שפטור גם בפשיעה מטעם כי בא המיעוט בכל השומרים, וממנה אתה למד כי לא פטור ומותר הוא ואדרבה עונשו גדול הוא שזלזל נכסי שמים אלא שלא קבע ה' משפטו לדייני ארץ וסלק דינו לפניו. ויש עוד לאלוה מילין כפי פנימיות התורה ואין כאן מקומן:
@57 **וגר לא תונה וגו' כי גרים וגו'**. רש''י ז''ל פירש אף הוא יכול להונותך כי גרים וגו', ור''א פי' זכור כי הייתם כמותו, ורמב''ן דחה ב' הדרכים ופי' כי תדעו שאשמע צעקת דלים כאשר שמע צעקתך וגו':
@57 **ונראה** לו' על פי הקדמה הידועה כי נשמות בני ישראל הם שורש הקדושה בני אברהם יצחק ויעקב חבל נחלתו יתברך וכל זולתם הם חלק רע, ולזה לא יקפידו בזלזול אדם שאינו מהם ובאונאתו לצד שיחשבוהו שפחות הוא מהדרגות הקדושה ומזה יולד ענפי האונאה, לזה כאשר צוה עליהם לבל יונום ולא ילחצום אמר הטעם שאני מצוך לבל תונהו שאין לך לומר שהוא בחינת שורש הרע או כיון שהוא מוטבע בבחינת הקליפה הרי נגרע מערכך **כי אתם גרים הייתם במצרים** פירוש על דרך מה שפירשתי (ויגש מו ג) כי לגוי גדול אשימך שם ובפסוק (כ' ב') אשר הוצאתיך מארץ מצרים בפרשת יתרו שנשמות ישראל עצמם היו טבועות בקליפה ואם כן יהיה גר זה כאחד מכם באין הבדל ולזה לא תונהו ולא תלחצנו:
@59 **אם ענה תענה אותו**. צריך לדעת למה הוצרך לומר תיבת אותו ולא הספיק באומרו אם תענה וגו' והדבר ידוע שחוזר אל הסמוך. ונראה על פי מה שאמרו במכילתא בפסוק לא תענון אין לי אלא יתום ואלמנה שאר כל אדם מנין תלמוד לומר לא תענון עד כאן. וכפי זה יש אזהרה גם לשאר כל אדם מלא תענון לזה אמר הכתוב **אותו** פירוש אותו שמוזכר בפירוש הוא שעונשו נשיהם אלמנות ובניהם יתומים אבל המענה כל אדם אין עונשו כל כך:
@61 **אם כסף**. במכילתא רבי ישמעאל אומר כל אם שבמקרא רשות חוץ מזו וכו'. וצריך לדעת למה ידבר ה' בדרך ספק במקום ודאי. ואולי כי בא הכתוב להודיע ולהשיב גם כן לאשר ישאל השואל בראותו כי ירבה כבוד אדם בזהב לרוב ואוצרותיו מלאים הון עתק ללא צורך בו ויאמר אדם מה הנה אוצרות זהב לאדם ללא דבר למה לא הספיק ה' לתת לו מזונותיו הצריכין ולא יהיה זה גדול מיעקב אבינו אשר שאל (ברשית כח כ) לחם לאכול ובגד ללבוש, הן אמת כי מה שיחסר לאדם מכדי צורכו יש טעם בדבר ליסרו על עונו מה שאין כן אוצרות הון למה לאיש אין לו צורך בהם, לזה הודיע הכתוב כי הסובב דבר הוא אותם שאינם ראוים לקבל חקם לצד מעשיהם כי ה' בחסדו נותן שפע הצריך בריוח לכל איש ואיש די מחסורו והיה כי יחטא אדם ואינו ראוי לקבל פרנסתו בכבוד מאל הכבוד החלק המגיעו לא יטלנו עליון אלא הרי הוא מתקבץ אל מקום אחר ותהיה פרנסת הלז עם אדם אחר הבא לו דרך שם פרנסתו ויתפרנם בפחיתות ובביזוי כאשר גזר הגוזר בצדק. ויעשה ה' בדרך זה לב' מדות טובות הא' להשתלם אדם בעולם הזה פעלו הרע, והב' כדי שיזכה הנותן באמצעות נתינת צדקה וחסד לרעהו. וזה הוא אומרו **אם כסף תלוה את עמי** פירוש אם ראית שהיה לך כסף יתר על מה שאתה צריך לעצמך שאתה מלוה לעמי תדע לך שאין זה חלק המגיעך אלא חלק אחרים שהוא העני עמך, ובזה רמז כי צריך לפתוח לו משלו. ואולי כי רמז לו גם כן שלא יתנשא ויתגדל על העני בראותו כי הוא הנותן לו, והוא אומרו **לא תהיה לו כנושה** לשון נשיאות ומעלה כי משלו הוא נותן לו. וחזר לומר כנגד ההלואה **לא תשימון עליו** וגו':
@62 **אם חבול תחבול**. נראה כי ירמוז להעיר אדם הנרדם אשר בידו שלמת מי שאמר עליו הכתוב (משלי כ''ז) רעך ורעה אביך וגו' והנפש תתיחס לשלמה על דרך אומרם במסכת שבת (קנ''ב:) משל למלך שחלק בגדי מלכות וכו', וכבר פירשנו בו כי לצד שנפש אדם היא מאורו יתברך, שנאמר בו (תהלים קד) עוטה אור כשלמה, ויצו ה' אם משכנה בחובו שהם חטאיו יש לו זמן להשיבו עד בא השמש על דרך אומרו (תהלים צ) תשב אנוש עד דכא, ואמרו ז''ל (קהלת רבה פ''ב) עד דכדוכה של מות כי יש לו זמן תשובה עד ביאת שמשו. וטעם כפל **חבול תחבול**, דע כי כל אדם מישראל יש לו ג' בחינות נפש רוח נשמה וכאן רמז הכתוב על שלשתן, כנגד הנשמה אמר **אם חבול**, וכנגד הרוח אמר **תחבול**, וכנגד הנפש אמר **שלמת רעך**, וכנגדם אמר ג' חלוקות, א' כי היא **כסותה לבדה** היא הנשמה, ב' **היא שמלתו לעורו** והיא הרוח, ג' **במה ישכב** והיא הנפש אשר עמו בקבר וכאומרו (איוב י''ד) ונפשו עליו תאבל. ואומרו **והיה כי יצעק** פירוש חוזר לענין ראשון תשיבנו לו שהיא התשובה כי לא יצטרך לצער להשיבו אלא כי יצעק ישמע ה' וגו' ויעבור חטאתיו:
@69 **לא תהיה אחרי רבים וגו'**. רבותינו ז''ל הרבו לדרוש בפסוק זה אבל אין המקרא מתיישב לפי פשוטו. ונראה לפרש הכתוב לפי מה שאמרה התורה ושפטו העדה והצילו וגו', ואמרו ז''ל (סנהדרין ב'.) עדה שופטת ועדה מצלת אבל אם פתחו כולם לחובה פטור (שם י''ז.) ובא הכתוב כאן להסיר ב' מכשולין אשר יכשל בהם חכם מאמצעות דין זה, הא' בהגיע משפט כזה ויראה חכם אחד מהשופטים שכל חבריו פתחו לחובה והוא חושב בדעתו כי הוא זכאי ויתחכם לומר אם נאמר זכאי הנה הוא יצא חייב כי יש שם עדה שופטת ועדה מצלת ונמצאו דברי עושים הפך דעתי לזה אתחכם ואומר חייב שבזה תהיה סברתי מתקיימת שיצא זכאי מטעם פתחו כולם וכו', וגם אהיה מקיים המוסר לבטל דעתי לפני דעת המרובין שאומרים חייב ונאמר חייב עמהם, לזה בא הכתוב וצוה על זה בדיוק לבל עשותו ואמר **לא תהיה אחרי רבים לרעות** פירוש כשתהיה סובר סברא אחת שבאומרך דעתך יצא זה הנידון חייב בדינו וכגון שכולם אמרו חייב ואתה חושב זכאי לא תתחכם להיות אחרי רבים שאומרים חייב והוא אומרו **לרעות** ותאמר אתה כדעתם חייב הפך מה שנראה לך כדי שיצא זכאי כדעתך אלא אמור דעתך כפי מה שידעת במשפטי התורה ואין לך להתחכם על המשפט כי ה' הוא האלהים והוא שאמר פתחו כולם לחובה זכאי לא אמר ה' שיזכה זה אלא אם לך יראה חייב ולא שיראה לך זכאי שאז חייב הוא כמשפט האלהים:
@69 **עוד** יש מכשול ב' במשפט זה באופן אחר והוא אם יראה בעיני חכם שהוא חייב ככל הדיינים שאמרו חייב ורואה שאם יאמר חייב הנה הוא יוצא זכאי הפך דבריו שאומר חייב לזה יתחכם לומר זכאי כדי שיוטה המשפט אחרי רבים שאומרים חייב ויצא חייב כפי סברתו, ויש בזה גם כן כפיית ראש בגמר המשפט לנטות אחרי רבים, לזה אמר **ולא תענה על ריב** וגו' פירוש לא תענה מענה על ריב לנטות **אחרי רבים** פירוש שתהיה כוונתך במענך כדי שיהיה כמשפט יחיד ורבים וזה יגיד שאם יגלה דעתו כמות שהוא אין כאן הטייה אחרי רבים אלא כולם בדעת אחת. וביאר הכתוב טעם הקפדתו על הדבר ואמר **להטות** פירוש כשתהיה כוונתך להטות ממה שבדעתך בעיון משפט התורה שהוא חייב ואתה מטה לומר זכאי כדי שיצא חייב לנטות אחרי רבים ויצא חייב אלא אמור דעתך הגם שיצא זכאי הפך דעתך ה' זכהו. וטעם משפט זה לצד כי ה' יושב במסיבת הדיינים והוא ישפוט בפיהם וכשיראה משפט מרומה ואין בו מציאות לזכות הזכאי יתחכם לפתוח כולן לחובה וצוה שיצא זכאי בזה:
@70 **ודל לא תהדר בריבו**. ירמוז בתיבת **בריבו** על דרך אומרם ז''ל (ויק''ר פל''ד) כי העני עושה מריבה עם קונו למה זן לכל והוא ברעב ובעירום וכל הנותן פרוטה לעני ומפרנסו הרי זה משבית ריב עני מעל השמים ובזמן שאין חונן דלים טענת עני היא טענה הנשמעת ומהודרת, ולזה יצו ה' שלא יסובבו הידור לריב העני עם קונו אלא יחוננוהו כמשפט חונן דלים:
@73 **לא תטה משפט אביונך**. אולי שיצו ה' על משפט העניים על דרך אומרם ז''ל (ב''מ ע''א.) ענייך ועניי עירך וכו' עניי עירך ועניי עיר אחרת עניי עירך קודמין, ולזה בא המצוה כאן בלאו לבל יטה משפט הקדום לאחרו, והוא אומרו אביונך:
@74 **כי לא אצדיק רשע**. לדבריהם ז''ל (סנהדרין ל''ג:) שפירשו נקי זה מי שיש עליו מגיד זכות וצדיק זה מי שיצא צדיק בדינו ויש עליו מגיד חובה, יכוין הכתוב לומר טעם הדברים שלא תאמר איך אחר שנגמר דינו לחובה יחזור הדין לזכות, לזה אמר **כי לא אצדיק רשע** פירוש ממה נפשך אם מה שיצא חייב הוא כפי האמת והצדק לא אצדיק רשע ולא יועיל המלמד זכות, ואם מה שיצא חייב היה שלא כפי הדין למה יבולע נקי חנם. וכנגד חלוקת מי שיצא צדיק בדינו אמר גם כן **כי לא אצדיק רשע** פירוש כיון שיצא צדיק לא הצדקתיהו והוא רשע כי אלהים נצב בעדת אל ובקרב אלהים ישפוט והוא שופט בצדק ומן הנמנע שיחתום ה' על דבר שקר ח''ו. וצא ולמד אומרם ז''ל (כתובות כ''א:) דאסור למחתם על מלתא דמתחזי כשקרא. ואם תאמר ולמה אין אנו אומרים כן ביצא חייב, יש לך לדעת כי ה' ינחם על הרעה ולא ינחם על הטובה ומי שיצא חייב חזר בו ה' לזכותו אבל מי שיצא זכאי לא ינחם ה' מהטובה, ולפעמים יספיק לאדם זה עינוי זה שיצא משפטו חייב ואימות מות יגיעוהו בראותו כי נגמר דינו למות, ולזה אחר כך בקרב אלהים ישפוט לזכותו:
@76 **ואתם ידעתם את נפש וגו** '. עיין מה שכתבתי בפסוק (כ''ב כ') וגר לא תונה ופסוק זה יצדיק לך כל מה שכתבתי לך:
@77 **ושש שנים וגו'**. סמך מצוה זו למה שלפניה לומר כדי שלא תטעמו טעם גרות עוד על דרך אומרו (ויקרא כו לד) אז תרצה הארץ את שבתותיה וגו':
@79 **תעשה מעשיך**. ולא כל מעשיך כמו שאמר בעשרת הדברות כי בששת ימים של שנת השמיטה שעליה חוזר צווי שבת כאן אינו יכול לעשות כל מלאכתו כי מלאכת אדמה אסורה לו כאמור בסמוך:
@80 **ובכל אשר אמרתי וגו'**. טעם אומרו **ובכל** וגו' **תשמרו** ולא אמר וכל אשר וגו' תשמרו, יכוין לומר על דרך אומרם ז''ל (מכות כ''ג:) כי מנין מצות עשה הם רמ''ח כנגד רמ''ח אברים של אדם ושס''ה לא תעשה הם כנגד שס''ה גידיו (זהר ח''א ק''ע:) והוא מה שרמז שלא יאמר אדם אקיים כך וכך מצות ויספיקו לשמירתי, לזה אמר **ובכל אשר** וגו' פירוש בכל המצות תהיו נשמרים ובחסרון אחד מהם תחסר השמירה לאותו אבר המכוון לה:
@80 **ושם אלהים וגו'**. בא לומר כשם ששמירת כל המצות תועיל לכל אדם למנין אבריו ושס''ה גידיו כמו כן יש שמירה לכללות האדם בכפירת עבודה זרה שכל הכופר בעבודה זרה כמודה בכל התורה ויחזק בשומר ועושה כל אשר תמצא ידו עשות ויהיו נשמרים באמצעות כפירת עבודה זרה כל איבריו וגידיו הגם שלא עשה המצוה ההיא ולא באה לידו העבירה ונשמר ממנה ודוקא מן הסתם אבל אם מבטל להדיא קצת מהמצות לא יהיה נשמר באותו אבר המכוון לאותה מצוה שמבטל לצד כפירתו בעבודה זרה:
@82 **כאשר צויתיך**. לפי שיש הרבה פרטי מצות שלא נתפרשו כאן, הא' שצריך להיות מצה מדבר הבא לידי חימוץ (פסחים ל''ה:), ב' שלא יצא ידי חובתו במעשה קדרה, ג' שלא יהיה חמץ מיום טוב ראשון וכל זה מפורש בפרשת בא כמבואר במכילתא לזה אמר **כאשר צויתיך** לרמוז לתנאי המצוה הנזכרים:
@83 **בכורי מעשיך**. פירוש למעט דעייל ביד גוי שאינו מעשיו וכמו שמיעט באומרו קצירכם כמו שדרשו בר''ה (י''ג.) שכל שהביאה שליש ביד גוי לא יביא ממנה בכורים:
@86 **ראשית בכורי וגו'**. אולי שירמוז שלא ישחית זרעו ושתהיה טיפה ראשונה שתצא ממנו מובאת בית ה' על דרך אומרם (יומא ב'.) ביתו זו אשתו, ודייק לומר **בית ה'** לשלול בית אשה זונה, והוא מצוה שקיים יעקב אבינו עליו השלום דכתיב (בראשית מט) כחי וראשית אוני, וגמר אומרו **לא תבשל גדי בחלב אמו** לרמוז סוד גדול כי המשחיתים זרעם סובבים מיתת הקטנים מבין שדי אמם, וכמו שפירש הדבר באומרו בפסוק (מיכה ו') האתן בכורי פשעי פרי בטני חטאת נפשי כי כשאדם משחית זרעו נברא ממנו משחית רע והוא שולט אחר כך בבן היולד, והם נפשות העשוקות כאמור בספר הזוה''ק (ח''א רי''ט.), ומי גרם זה שלא הביא בכוריו בית ה', וכפי דרך הפשט טעם סמך **לא תבשל** וגו' עם הביכורים, להאומר (חולין קי''ד:) בשר בחלב אסור בהנאה שהוא עיקר ההלכה נתכוין לסומכו עם הביכורים להיות שהם אסורים בהנאה, (רמב''ם פ''ב) ועיין בספרי פרי תואר:
@87 **הנה אנכי וגו'**. פירוש מלאך זה הוא המלאך הגואל את האבות לא משרת ממשרתיו אלא מלאך גדול כידוע למשכילים כי אין אנו מכידים מלאך אמצעי אלא הוא יתברך ושכינת עוזו המתיחדת עמו בסוד (זכרי' יא) ה' אחד ושמו אחד:
@88 **השמר מפניו וגו'**. כאן צוה על מצות עשה ומצות לא תעשה, כנגד מצות לא תעשה אמר **השמר** וגו' כי כל השמר וגו' לא תעשה, וכנגד מצות עשה אמר **ושמע בקולו**:
@88 **אל תמר בו**. כאן רמז לפעולת האדם אשר תסובב תמורת טוב ברע ועבד מולך ושפחה יורשת גבירתה, ועל ידי זה יתנקם נקם מהעושה תמורה ולא ישא לפשעכם, גם מלאך זה ידוע הוא כי הוא בחינת המשפט ולא ישא עון כאומרו **לא ישא** וגו', ואומרו **כי שמי בקרבו** השכילו בדבר הזה כי באמצעות חטא האדם יסובב פרידת אלוף מקרבו. ואשכילך כי מטט''רון הקדוש אמרו ז''ל (סנהדרין ל''ח:) שמו כשם רבו והוא שדי כי עולה מספר עצמו של השם ובחטא האדם יסתלק שם שדי ממנו, והוא סוד אומרו (ישעי' י''ט) ונהר יחרב וגו' והשכיל לב משכיל בדברים באומרו **כי אם שמוע תשמע בקולו** כמדבר על זולת וגמר אומרו **ועשית את אשר אדבר** ולא אמר אשר ידבר לומר כי שמי בקרבו והבן:
@89 **ואיבתי וגו'**. אולי שירמוז כי באמצעות עסק התורה והמצוה הנה האדון יעקר שורש הקליפה וענפיה שהם המסיתים והמדיחים והמבקשים להשפיל דגל התורה, ועיין מה שפירשתי בפרשת בראשית במעשה קין בהתווכחות האדון עמו:
@90 **והביאך וגו' והכחדתיו**. יכוין כי באמצעות הכנסת ישראל יהיו נכחדים האומות ההם, ועיין מה שפירשתי בפסוק (במדבר יד ט) סר צלם וגו' וה' אתנו וגו' כי הקדושה תשאוב חלק המחיה ותשאר כפגר מובס, והוא סוד אומרם ז''ל (שבת ל''ד.) יהיב עיניה ביה ונעשה גל של עצמות כי יברר וישאוב חלק המחיה ממקום תחנותו:
@91 **לא תשתחוה וגו'**. צריך לדעת למה הוצרך לצוות לזה אחר שהזהיר כמה אזהרות על כיעור זה ועל הדומה לו ומה גם שבסמוך למעלה הזהיר אפילו על בל ישא את שמותם על שפתיו ולא לגרום שיזכרו שמם הזולת דכתיב (פסוק י''ג) ולא ישמע על פיך אם כן מה מקום להזהיר עוד על העבודה. ורמב''ן יישב כי להיותה חמורה ירבה בה האזהרות, ומן התימה הוא שאחר שהשווה אותה לכל התורה כולה כאמור למעלה בין לענין עונש בין לעגין שכר הנה העובדה עובר על תרי''ג אזהרות ומה גם שיש מצות שיש בהם ב' לאוין ויותר ומצוה זו שקולה כנגד הכל:
@91 **ונראה** לומר כי טעם הכתוב הוא לג' סבות, האחד להיות שרצה להזהיר שלא ידמה להאומות במעשיהם לזה אם לא היה מקדים לומר לא תשתחוה ולא תעבדם לא יעלה על דעת אנוש לומר שיכוין הכתוב לומר על מעשה חול שאין בו עבודה זרה שאסור ובהכרח לומר שאינו אומר אלא על מעשה איסור שהוא עבודה זרה אך אחר שאמר **לא תשתחוה ולא תעבדם** בזה גילה דעתו כי מה שאמר **לא תעשה כמעשיהם** הוא אפילו דבר שאינו ניכר שיש בו עבודה זרה והוא שלא ידמה להם לא במלבושיהם ולא בתגלחתם כלל, וכאן נכלל כל שהוא מיוחד למעשה הגוים כאמור בדבריהם ז''ל (שבת ס''ז.), והב' להודיענו בא כי כל מעשיהם יש בו עבודה זרה כי ה' יודע מחשבות בני אדם ויסוד כל דבר ואם כן כל העושה מעשה גוים הרי זה טועם מעון עבודה זרה, והג' להיות שרצה לצוות על הריסתם ושברונם לזה קדם לומר **לא תשתחוה** וגו' לומר שאם לא הרס ולא שיבר הנה הוא כעובד עבודה זרה כי ה' תופס על המחשבה בעבודה זרה וצריכין היכר לשלילת מחשבת עבודה זרה מלבם ואין היכר אלא בשבר מצבותיהם ואם לא יעשו כן הרי הם כעובדי עבודה זרה וזה לך האות, ולזה הוצרך לומר **לא תשתחוה ולא תעבדם** וגו' כי הרס לומר שבהעדר הרס הנה הוא עובר על לא תעבדם. ותמצא שהקפיד ה' על ישראל שלא עשו כן בכניסתם לארץ (שופטים ב'):
@92 **ועבדתם את ה'**. אולי שהוא נמשך עם מה שלמעלה כי כשישבר כח העבודה זרה ויהרוס מבצריה בזה עובד את ה' וישפיע לו טובה ויברך לחמו. ואומרו **ואת מימיך** פירוש להיות שמהמים יולד הכחישות ותולדות החולאים וליחות הרעות לזה הבטיח שיברך מימיו שיצמחו צמח האדם בתכלית הבריאות כידוע למשכילים בהבחנת המימות כי אחרי מים חיים ישוטט האדם לשכון שם והבטחה גדולה הבטיח הבורא ברוך הוא בזה, ולזה סמך לברכת המים ולא תהיה משכלה וגו', וצא ולמד מה שדרשו ז''ל (ברכות נ''ט:) במי פרת:
@92 **והסירותי וגו'**. רשם ה' הבחנת הברכה בשלשה דברים, הא' שיהיה האדם בריא להתעדן בטוב ה'. והוא אומרו **והסירותי** וגו' שזולת זה כל אוכל תתעב נפשם, ב' ירבה לו בנים, והוא אומרו **לא תהיה משכלה** וגו', ג' שישלים ימיו אורך ימים ושנות חיים, והוא אומרו **את מספר ימיך** וגו'. גם בזה הראה ה' הפלגת הברכה כי זולת ג' דברים אלו אין היכר לברכה. שאם היו האוכלים מועטים ומשוללי הבריאות ושנים מועטות כל שהוא שיתן ה' יספיק לספוק צרכם ונמצא בירך לחמו ומימיו ואין בהבטחה זו דבר גדול אלא באמצעות ג' דברים אלו:
@94 **את אימתי וגו'**. הגם שאמר למעלה (פסוק כ''ג) והכחדתיו כאן גילה כי בתחלה לא לכל יכחיד אלא עד שיפרה יוסיף ה' להום את העם הצריך ישראל לארצו וכן על זה הדרך יהיו כובשים והולכים וכמו שגילה לבסוף באומרו **לא אגרשנו** וגו' עד אשר תפרה ותנחל הכל:
@99 **לא תכרות וגו**. קשה אם כבר צוה שיהרסו וישברו אותם מה מקום לצוות על כריתת ברית עמהם, ועוד איך יוצדק לכרות ברית לאלהיהן, ואם על עבודת עבודה זרה הוא אומר מאי איריא בכריתת ברית:
@99 **אכן** כוונת הכתוב הוא לומר שאין אוסר כריתת ברית עם האומות אלא כל עוד שהם ואלהיהן עמהם אבל אם כפרו באלהיהן אין איסור לזה אמר **לא תכרות להם ולאלהיהם** פירוש כשיהיו להם אלהיהן ברית. ונתכוון גם לומר כי הכורת ברית לעובד עבודה זרה כאלו כרת ברית לעבודה זרה עצמה מב' טעמים. האחד כי סופו ליכשל כמאמר הסמוך פן יחטיאו וגו' כי תעבוד. והב' כי בחינת העבודה זרה תתלבש בעובדיה ובזה נמצא שכורת ברית גם לאלהיהן רחמנא ליצלן, ואין לומר כי לזה לבד נתכוין שאם כן היה לו לומר לא תכרות להם ברית ולאלהיהן ואז היינו אומרים שהכוונה היא אם כרת להם ברית מעלה עליו הכתוב כאלו וכו', אכן מאומרו הזכרת הברית אחר הזכרת אלהיהן יגיד גם מה שפירשנו שלא אסר אלא בזמן שלא קבל שלא לעבוד עבודה זרה אבל אם אין לו אלוה מותר לכרות לו ברית כמו שכרתו ברית לגבעונים. וטעם שהקפידו ישראל אחר כך, לצד שאמרו ז''ל (ירושלמי שביעית פ''ו) שמתחלה היו מהמורדים בישראל בשליחות אגרת יהושע ונתחייבו כליה כמצות המלך לא תחיה כל נשמה:
@100 **פן יחטיאו אותך לי**. כאן גילה האדון כי החסרון נוגע לבורא. והשכלת הדברים היא כי ישראל להיותם בחינת הקדושה בעת אשר יעבדו עבודה זרה הנה הם גורעים מערך קודש ונחסרים משורשם ונמצא החסרון נוגע לשורש הקדושה:
@100 **כי** יהיה לך למוקש וגו'. פירוש נתן טעם מנין יעלה על הדעת שיחשדו ישראל על זה להמיר כבודם בלא יועיל, לזה הודיע כי העבודה זרה מטעה את עובדיה לינקש אחריה, כאומרם ז''ל (ע''ז נ''ה.) שיש עבודה זרה שמגלה מצפונות ומטמונות ומגדת עתידות ולזה חש ה' על בניו לבל ינקשו:
@101 **ואל משה וגו'**. משמעות הכתובים יגיד כי פרשה זו במקומה נאמרה אחר מתן תורה ואין להאריך בכיתי הוכחות המעידים על הדבר, וכן ראיתי לראב''ע ורשב''ם ורמב''ן שיחדיו היו תמים בדעת זו:
@101 **אלא** שראיתי במכילתא סברא באין חולק עליה כי ביום ה' בחודש שהיתה הפסקה בנה משה מזבח האמור בפרשת המשפטים וכרת עמהם הברית על כמה מהמצות אשר כבר קבלום עליהם למר על ז' מצות ולמר על מה שנצטוו במרה, ויש מרבותינו שאמרו שם שעל מצות הנאמרות בפרשת בהר סיני עד סוף אם בחקותי, ומשמע מדבריו כי אלו קדמו קודם מתן תורה ועליהם כרת ברית האמור לפי שלא כרתו ברית עד עתה על שום קבלת מצוה ובחן אותם משה אם מעצמן יקיימו עליהם הברית על מה שעבר הגם שלא חייבם ה' עליו. ואולי כי דבר משה כן לצד שרמזו ה' באומרו (לעיל י''ט ג') ותגיד לבני ישראל ודרשו ז''ל (שבת פ''ז.) שנתכוון לומר לו משוך אותם בדברי אגדה וגם זה מכלל המשכת הלב שמעצמם ישבעו על הראשונות. גם מסוגיית הגמ' (שם פ''ח.) שאמרו שהקדימו ישראל נעשה לנשמע כשבא משה אליהם וירדו ס' ריבוא מלאכים וקשרו להם ב' כתרים וכו' זה יגיד שקודם מתן תורה היתה פרשה זו:
@111 **ואל אצילי וגו'**. צריך לדעת למה הוצרך לומר ואל אצילי ולא הספיק לומר ולא שלח בהם ידו והדבר מובן שעל הזקנים וגו' המוזכרים בסמוך הוא אומר. ואולי כי טעם הוא נותן למה לא שלח ידו לצד שהיו אצילי פירוש גדולי ישראל ואילו עשו כן זולתם היה שולח ידו. או על דרך אומרם ז''ל (במד''ר פט''ו) שלא רצה לערבב השמחה כי כל ישראל יתאבלו עליהם לצד היותם גדוליהם ואציליהם לזה לא שלח ידו:
@111 **לא שלח וגו' ויאכלו וגו'**. קשה למה חזר לו' פעם ב' **ויחזו** וגו' ולא הספיק מה שקדם באומרו ויראו את וגו' והנה רבותינו ז''ל (ויק''ר פ''כ) אמרו כי נתכוין לו' כי על ידי מחזה שדי נהנו והרגישו הבריאות והשובע כאיש אכל ושתה. ועדיין קשה למה הפסיק הכתוב באמצע הענין במאמר לא שלח ידו כי מן הראוי היה לו להקדים לו' מעשיהם בשלימות ואחר כך אריכות אפים שהאריך ה' להם ולא הרגם מיד על זה הדרך ויראו את אלהי ישראל וגו' ויחזו את האלהים ויאכלו וגו' ואל אצילו בני ישראל. וגם לא היה צריך לכתוב פעם ב' ויחזו וגו' והיה מספיק במה שהתחיל לומר ויראו את אלהי ישראל וגו' לטוהר ויאכלו וגו' ודרשת חכמינו ז''ל לא זזה ממקומה:
@111 **ואולי** שכוונת הכתוב על דרך אומרו (לקמן ל''ג כ''ג) והסירותי את כפי וראית וגו' הרי כי ה' יעשה הבדלה בידו לנבראים מהביט אל האלהים ואפילו למשה כשנגלה אליו בגלוי שכינה שם כפו עליו פירוש בחינה המפסקת לבל יסתכל, וכאן הודיע הכתוב כי לאצילי ישראל לא שלח ידו למנוע מהם המחזה לצד היותם חשובים בעיניו והניחם לזון עיניהם מאורו יתברך. וזה הוא שיעור הכתוב **ויראו את אלהי ישראל** פירוש ראו אור גדול של אלהי ישראל אבל לא נסתכלו אלא תחת רגליו ואחר כך לצד שלא שלח ה' ידו פירוש כחו ורשיונו למנוע מהם ובזה היה להם כח לחזות בנועם ה' ונהנו זו אכילה זו שתיה ושבעה בטוב נפשם, ולא יקשה למה למשה שם כפו עליו ומנעו מהביט ולאצילי ישראל לא שלח ידו כי מה שהוצרך ה' לשום כפו על משה לא לשלול ממנו השגה שהשיגו אצילי ישראל כי השגה זו היתה למשה בתמידות אלא להביט בהשגה מופלאת אשרי כל מחזה עליון יחזה. ויש עוד לאלוה מילין בפירושן של דברים ושומר אני עצמי מהעלות על ספר דברים היושבים בסתר עליון לבל יהנו מהם מי שאינו ראוי לאור באור החיים:
@111 **חסלת פרשת משפטים**
